          src={sys3}
          alt="Layer 3"
          style={styles.image3}
        />
        <div
          className="clock unique-solar-clock"
          style={styles.clock}
          ref={clockRefs.clock}
        >
          <div
            className="ball hour unique-solar-clock"
            style={{ ...styles.ball, ...styles.hour }}
            ref={clockRefs.hour}
          ></div>
          <div
            className="ball minute unique-solar-clock"
            style={{ ...styles.ball, ...styles.minute }}
