import React, { useEffect, useRef, useMemo, useCallback } from 'react';
import { useMillisecondClock } from '@/utils/hooks';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import type { FontConfig } from '@/types/clock';
import sageFontUrl from '@/assets/fonts/2025/25-04-08-sage.ttf?url';

// Component Props interface
interface TripleCactusClockProps {
  // No props required for this component
}

// Clock refs interface
interface ClockRefs {
  hours: React.RefObject<HTMLDivElement | null>;
  minutes: React.RefObject<HTMLDivElement | null>;
  seconds: React.RefObject<HTMLDivElement | null>;
  milliseconds: React.RefObject<HTMLDivElement | null>;
}

const TripleCactusClock = () => {
  const clockRefs: ClockRefs = {
    hours: useRef<HTMLDivElement>(null),
    minutes: useRef<HTMLDivElement>(null),
    seconds: useRef<HTMLDivElement>(null),
    milliseconds: useRef<HTMLDivElement>(null),
  };

  // Font loading configuration (memoized)
  const fontConfigs = useMemo<FontConfig[]>(() => [
    {
      fontFamily: 'CactusClockFont',
      fontUrl: sageFontUrl,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ], []);

  // Load fonts using suspense-based loader
  useSuspenseFontLoader(fontConfigs);

  // Use the standardized hook for smooth millisecond clock updates
  const currentTime = useMillisecondClock();
  const componentId = useRef(`cactus-clock-${Date.now()}`);

  const setDigits = useCallback((container: HTMLDivElement | null, text: string): void => {
    if (!container) return;
    container.innerHTML = '';
    for (let char of text) {
      const span = document.createElement('span');
      span.textContent = char;
      Object.assign(span.style, {
        color: '#f3f586',
        fontSize: '12vh',
        lineHeight: '8vh',
        textAlign: 'center',
        fontVariantNumeric: 'tabular-nums',
        fontFeatureSettings: '"tnum"',
        fontFamily: 'CactusClockFont, sans-serif',
      });
      container.appendChild(span);
    }
  }, []);

  const updateClock = useCallback((): void => {
    setDigits(clockRefs.hours.current, String(currentTime.getHours()).padStart(2, '0'));
    setDigits(clockRefs.minutes.current, String(currentTime.getMinutes()).padStart(2, '0'));
    setDigits(clockRefs.seconds.current, String(currentTime.getSeconds()).padStart(2, '0'));
    setDigits(
      clockRefs.milliseconds.current,
      String(currentTime.getMilliseconds()).padStart(3, '0'),
    );
  }, [currentTime, setDigits]);

  useEffect(() => {
    updateClock();
  }, [updateClock]);

  return (
    <div
      style={{
        margin: 0,
        padding: 0,
        boxSizing: 'border-box',
        height: '100%',
        overflow: 'hidden',
        background: '#01151d',
      }}
    >
      <style>{`
        @keyframes skyCycle {
          0% { background: #3bbdf0; }
          15% { background: #8fbee2; }
          25% { background: #e8a30d; }
          50% { background: #fd1d1d; }
          60% { background: #b43a87; }
          75% { background: #833ab4; }
          90% { background: #02027f; }
          100% { background: #010102; }
        }
        @keyframes sunVertical {
          0% { top: 10%; opacity: 1; }
          45% { top: 50%; opacity: 1; }
          100% { top: 90%; opacity: 0; }
        }
      `}</style>
      <div
        style={{
          position: 'relative',
          width: '100vw',
          height: '100dvh',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'flex-end',
          flexDirection: 'column',
          animation: 'skyCycle 20s ease-in-out infinite alternate',
        }}
      >
        {/* Sun / Clock */}
        <div
          style={{
            position: 'absolute',
            left: '50%',
            transform: 'translateX(-50%)',
            animation: 'sunVertical 20s linear infinite alternate',
            zIndex: 2,
          }}
        >
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              fontFamily: 'CactusClockFont',
            }}
          >
            <div
              style={{ display: 'flex', gap: '1.3vh', margin: '1vh 0' }}
              ref={clockRefs.hours}
            ></div>
            <div
              style={{ display: 'flex', gap: '1.3vh', margin: '1vh 0' }}
              ref={clockRefs.minutes}
            ></div>
            <div
              style={{ display: 'flex', gap: '1.3vh', margin: '1vh 0' }}
              ref={clockRefs.seconds}
            ></div>
            <div
              style={{ display: 'flex', gap: '1.3vh', margin: '1vh 0' }}
              ref={clockRefs.milliseconds}
            ></div>
          </div>
        </div>

        {/* Mountains */}
        <div
          style={{
            position: 'absolute',
            bottom: '40vh',
            width: '100%',
            height: 0,
            zIndex: 1,
            display: 'flex',
            justifyContent: 'center',
            gap: '1vw',
            opacity: 0.6,
          }}
        >
          {['#48638f', '#707d93', '#48638f'].map((color, i) => (
            <div
              key={i}
              style={{
                width: 0,
                height: 0,
                borderLeft: '15vw solid transparent',
                borderRight: '15vw solid transparent',
                borderBottom: `15vh solid ${color}`,
              }}
            />
          ))}
        </div>

        {/* Ground and Cacti */}
        <div
          style={{
            position: 'absolute',
            bottom: 0,
            height: '27vh',
            width: '100%',
            background: '#c5a770',
            zIndex: 2,
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'flex-end',
          }}
        >
          <div
            style={{
              display: 'flex',
              justifyContent: 'center',
              gap: '15vw',
              marginBottom: '8vh',
            }}
          >
            {Array.from({ length: 3 }).map((_, i) => (
              <div
                key={i}
                style={{
                  width: '2vw',
                  height: '15vh',
                  background: '#228b22',
                  borderRadius: '1vw',
                  position: 'relative',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                <div
                  style={{
                    position: 'absolute',
                    width: '1vw',
                    height: '6vh',
                    background: '#228b22',
                    borderRadius: '50% 50% 0 0',
                    left: '-1vw',
                    top: '20%',
                    transform: 'rotate(-40deg)',
                    transformOrigin: 'bottom right',
                  }}
                ></div>
                <div
                  style={{
                    position: 'absolute',
                    width: '1vw',
                    height: '6vh',
                    background: '#228b22',
                    borderRadius: '50% 50% 0 0',
                    right: '-1vw',
                    top: '10%',
                    transform: 'rotate(40deg)',
                    transformOrigin: 'bottom left',
                  }}
                ></div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TripleCactusClock;

import React, { useEffect, useRef, useState } from 'react';
import { useClockTime } from '@/utils/hooks';
import roomImage from '@/assets/images/2025/25-04/25-04-09/room.webp';

export { roomImage }; // Export for preloading pipeline

// Window size interface
interface WindowSize {
  width: number;
  height: number;
}

const EmptyRoomClock: React.FC = () => {
  const hourRef = useRef<HTMLDivElement>(null);
  const minuteRef = useRef<HTMLDivElement>(null);
  const secondRef = useRef<HTMLDivElement>(null);

  const [windowSize, setWindowSize] = useState<WindowSize>({
    width: window.innerWidth,
    height: window.innerHeight,
  });

  // Use the standardized hook for smooth clock updates
  const currentTime = useClockTime();

  useEffect(() => {
    const handleResize = () =>
      setWindowSize({ width: window.innerWidth, height: window.innerHeight });
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    const hour = currentTime.getHours() % 12;
    const minute = currentTime.getMinutes();
    const second = currentTime.getSeconds();

    const hourDeg = (hour + minute / 60) * 30;
    const minuteDeg = (minute + second / 60) * 6;
    const secondDeg = second * 6;

    if (hourRef.current)
      hourRef.current.style.transform = `translate(-50%) rotate(${hourDeg}deg)`;
    if (minuteRef.current)
      minuteRef.current.style.transform = `translate(-50%) rotate(${minuteDeg}deg)`;
    if (secondRef.current)
      secondRef.current.style.transform = `translate(-50%) rotate(${secondDeg}deg)`;
  }, [currentTime]);

  const clockSize = Math.min(windowSize.width, windowSize.height) * 0.4;

  // Distance from bottom of viewport
  const clockBottom = windowSize.height * 0.2; // 10% from bottom
  const clockLeft = windowSize.width * 0.6; // center horizontally

  return (
    <div
      style={{
        position: 'relative',
        width: '100vw',
        height: '100dvh',
        overflow: 'hidden',
        backgroundColor: '#000',
      }}
    >
      <img
        decoding="async"
        loading="lazy"
        src={roomImage}
        alt="Room background"
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          objectFit: 'fill',
          zIndex: 0,
        }}
      />

      <div
        style={{
          width: clockSize,
          height: clockSize,
          backgroundImage: `url(${roomImage})`,
          backgroundSize: 'cover',
          filter: 'brightness(0.92)',
          backgroundPosition: 'center',
          border: '2px solid #a19f63',
          borderRadius: '50%',
          position: 'absolute',
          bottom: clockBottom,
          left: clockLeft,
          transform: 'translateX(-50%) rotateX(-9deg) rotateZ(3deg)',
          transformOrigin: 'bottom center',
          boxShadow: `
            1px 1px rgba(191, 32, 32, 0.5),
            -1px 1px rgba(191, 32, 32, 0.5),
            -1px -1px rgba(191, 32, 32, 0.5),
            1px -1px rgba(191, 32, 32, 0.5),
            -10px 15px 30px rgba(0, 0, 0, 0.5)
          `,
          zIndex: 1,
          transition:
            'width 0.3s ease, height 0.3s ease, bottom 0.3s ease, left 0.3s ease',
        }}
      >
        <div
          ref={hourRef}
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            width: clockSize * 0.023,
            height: clockSize * 0.21,
            background: '#333',
            borderRadius: '4px',
            transformOrigin: 'bottom center',
          }}
        />
        <div
          ref={minuteRef}
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            width: clockSize * 0.019,
            height: clockSize * 0.356,
            background: '#666',
            borderRadius: '4px',
            transformOrigin: 'bottom center',
          }}
        />
        <div
          ref={secondRef}
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            width: clockSize * 0.0044,
            height: clockSize * 0.5,
            background: 'rgb(186, 41, 41)',
            borderRadius: '4px',
            transformOrigin: 'bottom center',
          }}
        />
        <div
          style={{
            position: 'absolute',
            left: '50%',
            bottom: '50%',
            width: clockSize * 0.022,
            height: clockSize * 0.022,
            background: '#333',
            borderRadius: '50%',
            transform: 'translate(-50%, 50%)',
          }}
        />
        <div
          style={{
            position: 'absolute',
            bottom: -(clockSize * 0.045),
            left: clockSize * 0.044,
            width: clockSize * 0.35,
            height: clockSize * 0.045,
            background: 'rgba(0, 0, 0, 0.2)',
            filter: 'blur(10px)',
            borderRadius: '50%',
            zIndex: -1,
          }}
        />
      </div>
    </div>
  );
};

export default EmptyRoomClock;

