import React, { useEffect, useState, useMemo, useCallback } from 'react';
import { useSecondClock } from '@/utils/hooks';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import type { FontConfig } from '@/types/clock';
import backgroundImage from '@/assets/images/2025/25-04/25-04-14/bricks.webp';

// Time interface
interface TimeState {
  hours: number;
  minutes: number;
  seconds: number;
}

// Component Props interface
interface BlueBrickClockProps {
  // No props required for this component
}

const BlueBrickClock = () => {
  // Font loading configuration (memoized) - no custom fonts needed
  const fontConfigs = useMemo<FontConfig[]>(() => [], []);
  useSuspenseFontLoader(fontConfigs);

  // Use the standardized hook for smooth clock updates
  const currentTime = useSecondClock();

  const [time, setTime] = useState<TimeState>({
    hours: currentTime.getHours(),
    minutes: currentTime.getMinutes(),
    seconds: currentTime.getSeconds(),
  });

  const updateClock = useCallback((): void => {
    setTime({
      hours: currentTime.getHours(),
      minutes: currentTime.getMinutes(),
      seconds: currentTime.getSeconds(),
    });
  }, [currentTime]);

  useEffect(() => {
    updateClock();
  }, [updateClock]);

  const ballStyle = {
    width: '2vw',
    height: '3vw',
    background: 'radial-gradient(circle at 30% 30%, #7d9ac9, #a5c1e6)',
    boxShadow: '0 0 1vw 0.4vw rgba(117, 151, 215, 0.8)',
    animation: 'pop 0.6s cubic-bezier(0.28, 0.84, 0.42, 1)',
  };

  const renderBalls = useCallback((count: number) =>
    Array.from({ length: count }, (_, i) => <div key={i} style={ballStyle} />), [ballStyle]);

  return (
    <div
      style={{
        margin: 0,
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        height: '100dvh',
        position: 'relative',
        boxSizing: 'border-box',
      }}
    >
      <div
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          transform: 'rotate(180deg)',
