    left: '-5%',
    width: '110%',
    height: '110%',
    borderRadius: '50%',
    animation: 'rotateCounterClockwise 30s linear infinite',
    zIndex: 2,
  };

  const circleImgStyle = {
    width: '100%',
    height: '100%',
    objectFit: 'cover',
    borderRadius: '50%',
    filter: 'saturate(300%)',
  };

  const handBaseStyle = {
    position: 'absolute',
    width: '100%',
    height: '100%',
    top: 0,
    left: 0,
    transformOrigin: 'center center',
    pointerEvents: 'none',
    zIndex: 9,
  };

  const handImgStyle = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -100%)',
  };

  const hourImgStyle = {
    ...handImgStyle,
    height: '34vh',
    filter: 'contrast(120%) brightness(100%)',
    zIndex: 9,
  };

  const minuteImgStyle = {
    ...handImgStyle,
    height: '44vh',
    zIndex: 6,
  };

  const secondImgStyle = {
    ...handImgStyle,
    height: '40vh',
  };

  const fullPageImageStyle = {
    position: 'fixed',
    top: 0,
    left: 0,
    width: '100vw',
    height: '100vh',
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    backgroundRepeat: 'no-repeat',
    zIndex: 6,
    filter: 'saturate(300%)',
  };

  const fullPageImage2Style = {
    ...fullPageImageStyle,
    zIndex: 2,
    filter: 'saturate(200%)',
  };

  return (
    <>
      <style>
        {`
          @keyframes rotateCounterClockwise {
            from {
              transform: rotate(0deg);
            }
            to {
              transform: rotate(-360deg);
            }
          }
        `}
      </style>

      <div style={bodyStyle}>
        <div style={clockWrapperStyle}>
          <div style={clockStyle}>
            <div style={circleStyle}>
              <img
                decoding="async"
                loading="lazy"
                src={cakeGif}
                alt="Rotating Image"
                style={circleImgStyle}
              />
            </div>

            <div
              ref={clockRefs.minuteHand}
              style={{ ...handBaseStyle, zIndex: 9 }}
              className="minute"
            >
              <img
                decoding="async"
                loading="lazy"
                src={minuteImg}
                alt="Minute hand"
                style={minuteImgStyle}
              />
            </div>

            <div
              ref={clockRefs.hourHand}
              style={{ ...handBaseStyle, zIndex: 9 }}
              className="hour"
            >
              <img
                decoding="async"
                loading="lazy"
                src={hourImg}
                alt="Hour hand"
                style={hourImgStyle}
              />
            </div>

            <div ref={clockRefs.secondHand} style={handBaseStyle} className="second">
              <img
                decoding="async"
                loading="lazy"
                src={secondImg}
                alt="Second hand"
                style={secondImgStyle}
              />
            </div>
          </div>
        </div>

        <img
          decoding="async"
          loading="lazy"
          src={confGif}
          alt="Confetti gif"
          style={fullPageImageStyle}
        />
        <img
          decoding="async"
          loading="lazy"
          src={confJpg}
          alt="Confetti background"
          style={fullPageImage2Style}
        />
      </div>
    </>
  );
};

export default BirthdayCakeClock;

