import { useSecondClock } from '@/utils/hooks';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import type { FontConfig } from '@/types/clock';
import styles from './Clock.module.css';

// Digit style interface
interface DigitStyle {
  bg: string;
  color: string;
}

// Component Props interface
interface StripeClockProps {
  // No props required for this component
}

// Digit color mapping
const digitStyles: Record<string, DigitStyle> = {
  0: { bg: '#0E51FAFF', color: '#F87E04FF' },
  1: { bg: '#FA0820FF', color: '#2F9B04FF' },
  2: { bg: '#F7FF06FF', color: '#A205C2FF' },
  3: { bg: '#2F9B04FF', color: '#FA0820FF' },
  4: { bg: '#FC8004FF', color: '#0E51FAFF' },
  5: { bg: '#A205C2FF', color: '#F7FF06FF' },
  6: { bg: '#141313FF', color: '#F4F2F2FF' },
  7: { bg: '#F4F2F2FF', color: '#141313FF' },
  8: { bg: '#966105FF', color: '#F92FB9FF' },
  9: { bg: '#F92FB9FF', color: '#966105FF' },
};

// Load Google Font dynamically
const loadFont = () => {
  const link = document.createElement('link');
  link.href = 'https://fonts.googleapis.com/css2?family=Asset&display=swap';
  link.rel = 'stylesheet';
  document.head.appendChild(link);
};

export default function StripeClock() {
  // Font loading configuration (memoized) - no custom fonts needed
  const fontConfigs = useMemo<FontConfig[]>(() => [], []);
  useSuspenseFontLoader(fontConfigs);

  // Use the standardized hook for smooth clock updates
  const currentTime = useSecondClock();
  const [time, setTime] = useState<Date>(currentTime);

  useEffect(() => {
    setTime(currentTime);
  }, [currentTime]);

  const timeStr = time
    .toLocaleTimeString('en-GB', { hour12: false })
    .replace(/:/g, '');

  // Container style
  const containerStyle = {
    display: 'flex',
    flexDirection: 'column', // stack stripes vertically
    width: '100vw',
    height: '100dvh',
    margin: 0,
    padding: 0,
    fontFamily: "'Asset', monospace",
    fontWeight: 'bold',
  };

  // Stripe style function
  const getStripeStyle = (char) => ({
    flex: 1, // each stripe takes equal vertical space
    width: '100vw', // full viewport width
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    fontSize: '8vh',
    fontWeight: 'bold',
    transition: 'all 0.5s ease',
    backgroundColor: digitStyles[char].bg,
    color: digitStyles[char].color,
  });

  return (
    <div className={styles.container}>
      <div className={styles.clock}>
        {timeStr.split('').map((char, idx) => (
          <div 
            key={idx} 
            className={styles.stripe}
            style={{
              backgroundColor: digitStyles[char].bg,
              color: digitStyles[char].color,
            }}
          >
            {char}
          </div>
        ))}
      </div>
    </div>
  );
}

import React, { useEffect, useRef } from 'react';
import backgroundImg from '@/assets/images/2025/25-04/25-04-18/Antarctica.jpg';

const AntarcticaClock: React.FC = () => {
  const clockRef = useRef(null);
  const hourRef = useRef(null);
  const minuteRef = useRef(null);
  const secondRef = useRef(null);

  useEffect(() => {
    const clock = clockRef.current;

    // Clear any existing ticks (in case of remount)
    while (clock.firstChild) {
      clock.removeChild(clock.firstChild);
    }

    // Create tick marks
    for (let i = 0; i < 60; i++) {
      const tick = document.createElement('div');
      tick.className = 'tick';
      if (i % 5 === 0) tick.classList.add('major');
      tick.style.transform = `rotate(${i * 6}deg)`;
      clock.appendChild(tick);
    }

    // Append hands
    clock.appendChild(hourRef.current);
    clock.appendChild(minuteRef.current);
    clock.appendChild(secondRef.current);

    const updateClock: React.FC = () => {
      const now = new Date();
      const hours = now.getHours() % 12;
      const minutes = now.getMinutes();
      const seconds = now.getSeconds();
      const ms = now.getMilliseconds();

      const hourAngle = hours * 30 + minutes / 2;
      const minuteAngle = minutes * 6 + seconds / 10;
      const baseSecondAngle = seconds * 6;
      const progress = ms / 1000;
      const secondAngle = baseSecondAngle + progress * 6;

      hourRef.current.style.transform = `translateX(-50%) rotate(${hourAngle}deg)`;
      minuteRef.current.style.transform = `translateX(-50%) rotate(${minuteAngle}deg)`;
      secondRef.current.style.transform = `translateX(-50%) rotate(${secondAngle}deg)`;

      requestAnimationFrame(updateClock);
    };

    updateClock();
  }, []);

  return (
    <>
      <style>
        {`
          .tick {
            position: absolute;
            width: 0.1vw;
            height: 37.5vh;
            background-color: #b6eef6;
            top: 1.2vh;
            left: 50%;
            transform-origin: 50% 14.5vh;
          }

          .tick.major {
            height: 58vh;
            width: 0.1vw;
          }

          .hand {
            position: absolute;
            bottom: 50%;
            left: 50%;
            transform-origin: bottom;
            background-color: #b3edf2;
          }

          .hour-hand {
            width: 3.7vw;
            height: 17vh;
          }

          .minute-hand {
            width: 2vw;
            height: 33vh;
          }

          .second-hand {
            width: 0.3vw;
            height: 100vh;
            background-color: rgb(72, 219, 242);
          }

          .center {
            position: absolute;
            width: 1.5vh;
            height: 1.5vh;
            background-color: #333;
            border-radius: 50%;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            z-index: 10;
          }

          @keyframes slow-rotate {
            0% {
              transform: rotate(0deg) scale(1.5);
            }
            100% {
              transform: rotate(-360deg) scale(1.5);
            }
          }

          .bgimage {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            filter: contrast(0.4);
            z-index: 0; /* changed from -1 */
            animation: slow-rotate 440s linear infinite;
            transform-origin: center center;
          }
        `}
      </style>

      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          height: '100dvh',
          width: '100vw',
          margin: 0,
          overflow: 'hidden',
          position: 'relative',
        }}
      >
        <img
          decoding="async"
          loading="lazy"
          src={backgroundImg}
          alt="Antarctica"
          className="bgimage"
        />
        <div
          ref={clockRef}
          className="clock"
          style={{
            position: 'relative',
            width: '50vh',
            height: '30vh',
            borderRadius: '50%',
            zIndex: 1, // added this so clock is above background image
          }}
        >
          <div className="center" />
          <div ref={hourRef} className="hand hour-hand" />
          <div ref={minuteRef} className="hand minute-hand" />
          <div ref={secondRef} className="hand second-hand" />
        </div>
      </div>
    </>
  );
};

export default AntarcticaClock;

