    position: 'absolute',
    top: 0,
    left: 0,
    width: '100vw',
    height: '160vh',
    objectFit: 'cover',
    opacity: '60%',
    transform: 'scaleX(-1)',
    zIndex: 3,
  };

  const bgImageStyle3: CSSProperties = {
