        decoding="async"
        loading="lazy"
        src={coinGif}
        alt="coin background"
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          objectFit: 'cover',
          zIndex: -1,
        }}
      />
      <div
        ref={clockRef}
        id="clock"
        style={{
          width: '80vh',
          height: '80vh',
          borderRadius: '50%',
          position: 'relative',
          transformStyle: 'preserve-3d',
          animation: 'spin 7s linear infinite',
        }}
      >
        <div
          className="hour-hand"
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            transformOrigin: 'bottom center',
            backgroundColor: '#d3ad62',
            width: '0.6vw',
            height: '12vw',
            transform: 'translateX(-50%)',
          }}
        />
        <div
          className="minute-hand"
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            transformOrigin: 'bottom center',
            backgroundColor: '#d3ad62',
            width: '0.4vw',
            height: '16vw',
            transform: 'translateX(-50%)',
          }}
        />
        <div
          className="second-hand"
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            transformOrigin: 'bottom center',
            backgroundColor: '#d3ad62',
            width: '0.2vw',
            height: '18vw',
            transform: 'translateX(-50%)',
          }}
        />
        <div
          className="center"
          style={{
            width: '8vh',
            height: '8vh',
            backgroundImage: `url(${spinWebp})`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            backgroundRepeat: 'no-repeat',
