            transform: 'translate(-50%, -50%)',
            zIndex: 10,
          }}
        ></div>
      </div>
      <style>{`
        @keyframes spin {
          0% { transform: rotateY(0deg); }
          100% { transform: rotateY(360deg); }
        }

        .hand {
          position: absolute;
          bottom: 50%;
          left: 50%;
          transform-origin: bottom center;
          background-color: #d3ad62;
        }

        .hour-hand {
          width: 0.6vw;
