import React, { useEffect, useRef, useMemo, useCallback } from 'react';
import { useSecondClock } from '@/utils/hooks';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import type { FontConfig } from '@/types/clock';
import type { CSSProperties } from 'react';
import fontUrl from '@/assets/fonts/2025/25-04-29-bang.ttf?url';
import gif1 from '@/assets/images/2025/25-04/25-04-29/fw.webp';
import gif2 from '@/assets/images/2025/25-04/25-04-29/84298.gif';
import gif3 from '@/assets/images/2025/25-04/25-04-29/giphy.gif';

// Component Props interface
interface FireworksClockProps {
  // No props required for this component
}

const FireworksClock: React.FC<FireworksClockProps> = () => {
  const clockRef = useRef<HTMLDivElement>(null);
  const componentId = `fireworks-clock-${Math.random().toString(36).substr(2, 9)}`;

  // Font loading configuration (memoized)
  const fontConfigs = useMemo<FontConfig[]>(() => [
    {
      fontFamily: 'bang',
      fontUrl: fontUrl,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ], []);

  // Load fonts using suspense-based loader
  useSuspenseFontLoader(fontConfigs);

  // Use the standardized hook for smooth clock updates
  const currentTime = useSecondClock();

  const showClock = useCallback((): void => {
    const clock = clockRef.current;
    if (!clock) return;

    const timeString = currentTime
      .toLocaleTimeString('en-US', { hour12: false })
      .slice(0, 5);

    clock.innerHTML = '';
    clock.style.animation = 'none';
    void clock.offsetWidth;
    clock.style.animation = `${componentId}-riseUp 1.5s ease-out forwards`;

    for (const char of timeString) {
      const span = document.createElement('span');
      span.textContent = char;
      span.style.color = getRandomBrightColor();
      span.style.fontSize = getRandomFontSize();
      span.style.fontWeight = 'bold';
      span.style.position = 'relative';
      span.style.display = 'inline-block';
      span.style.willChange = 'transform, opacity';
      span.style.textShadow = '0 0 0.5rem white';

      const { dx, dy, rot } = getRandomExplosionVector();
      span.style.setProperty('--dx', dx);
      span.style.setProperty('--dy', dy);
      span.style.setProperty('--rot', rot);
      clock.appendChild(span);
    }

    setTimeout(() => {
      for (const digit of clock.children) {
        (digit as HTMLElement).style.animation = `${componentId}-explodeWild 1.5s ease-out forwards`;
      }
    }, 1500);
  }, [currentTime, componentId]);

  const getRandomBrightColor = useCallback((): string => {
    const hue = Math.floor(Math.random() * 360);
    return `hsl(${hue}, 100%, 50%)`;
  }, []);

  const getRandomFontSize = useCallback((): string => {
    return `${Math.floor(Math.random() * 2) + 4}rem`;
  }, []);

  const getRandomExplosionVector = useCallback((): { dx: string; dy: string; rot: string } => {
    const dx = `${(Math.random() - 0.5) * 80}vw`;
    const dy = `${(Math.random() - 0.5) * 80}vh`;
    const rot = `${Math.random() * 1440 - 720}deg`;
    return { dx, dy, rot };
  }, []);

  useEffect(() => {
    showClock();
  }, [showClock]);

  const containerStyle = {
    fontFamily: 'bang, sans-serif',
    margin: 0,
    padding: 0,
    background: 'rgb(9, 9, 9)',
    height: '100dvh',
    width: '100vw',
    overflow: 'hidden',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'flex-end',
    position: 'relative',
  };

  const bgStyle = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    objectFit: 'cover',
    opacity: 0.7,
    filter: 'saturate(1.3)',
    zIndex: 0,
  };

  const clockStyle = {
    display: 'flex',
    position: 'relative',
    zIndex: 50,
    flexWrap: 'wrap',
    justifyContent: 'center',
    alignItems: 'center',
    gap: '0.5rem',
    fontFamily: 'bang, sans-serif !important',
  };

  return (
    <div style={containerStyle} data-component={componentId}>
      <img
        decoding="async"
        loading="lazy"
        src={gif1}
        alt="bg1"
        style={bgStyle}
      />
      <img
        decoding="async"
        loading="lazy"
        src={gif2}
        alt="bg2"
        style={bgStyle}
      />
      <img
        decoding="async"
        loading="lazy"
        src={gif3}
        alt="bg3"
        style={bgStyle}
      />
      <div ref={clockRef} style={clockStyle} />
      <style>{`
        @keyframes ${componentId}-pulse {
          from {
            transform: scale(1);
            opacity: 0.6;
          }
          to {
            transform: scale(1.03);
            opacity: 0.75;
          }
        }

        @keyframes ${componentId}-riseUp {
          0% {
            transform: translateY(100vh);
          }
          100% {
            transform: translateY(-70vh);
          }
        }

        @keyframes ${componentId}-explodeWild {
          0% {
            opacity: 1;
            transform: scale(1) translate(0, 0) rotate(0deg);
          }
          100% {
            opacity: 0;
            transform: scale(5) translate(var(--dx), var(--dy)) rotate(var(--rot));
          }
        }

        [data-component="${componentId}"] img {
          animation: ${componentId}-pulse 3s infinite alternate ease-in-out;
        }
      `}</style>
    </div>
  );
};

export default FireworksClock;

