    position: 'relative',
  },
  throw: {
    position: 'absolute',
    top: 0,
    right: 0,
    width: '100%',
    height: '100%',
    pointerEvents: 'none',
    overflow: 'hidden',
    zIndex: 1,
  },
  stationaryClock: {
    position: 'fixed',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    fontSize: '12vw',
    fontFamily: 'Courier New',
    color: 'rgba(255, 255, 255, 0.08)',
    zIndex: 0,
    pointerEvents: 'none',
    userSelect: 'none',
    whiteSpace: 'nowrap',
  },
};

export default NumberTossClock;

