import image3 from '@/assets/images/2025/25-05/25-05-18/bloo.gif'; // top layer

const Clock: React.FC = () => {
  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'blu',
      fontUrl: bluFont,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  const [time, setTime] = useState(new Date());

  // Font loading handled by useMultipleFontLoader

  // Update time every second
  useEffect(() => {
    const interval = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(interval);
  }, []);

  // Format time with leading zeros
  const formatTime = (unit) => String(unit).padStart(2, '0');
  const hours = formatTime(time.getHours());
  const minutes = formatTime(time.getMinutes());
  const seconds = formatTime(time.getSeconds());

  // Load font via FontFace API
  useEffect(() => {
    const font = new FontFace('blu', `url(${bluFont})`);
    font.load().then((loadedFont) => {
      document.fonts.add(loadedFont);
    });
  }, []);

  return (
    <div style={{ ...styles.container, fontFamily: `'blu', monospace` }}>
      {/* Background layers */}
      <img
        decoding="async"
        loading="lazy"
        src={image1}
