            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            zIndex: 1,
          }}
        />
        <div
          style={{
            backgroundImage: `url(${bg1})`,
            backgroundRepeat: 'repeat',
            backgroundSize: '35vh 45vh',
