import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useSecondClock } from '@/utils/hooks';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import type { FontConfig } from '@/types/clock';
import torGif from '@/assets/images/2025/25-05/25-05-24/tor.gif';
import speedFont from '@/assets/fonts/2025/25-05-24-speed.ttf';

const NUM_PARTICLES = 100;

const Clock: React.FC = () => {
  // 1. Font Loading
  const fontConfigs = useMemo<FontConfig[]>(() => [
    {
      fontFamily: 'speed',
      fontUrl: speedFont,
      options: { weight: 'normal', style: 'normal' }
    }
  ], []);
  useSuspenseFontLoader(fontConfigs);

  const currentTime = useSecondClock();
  const [timeString, setTimeString] = useState('');
  const flashRef = useRef<HTMLDivElement>(null);

  // 2. Initialize Particles (Ref-based to avoid re-renders during animation)
  const particles = useRef(
    Array.from({ length: NUM_PARTICLES }, (_, i) => ({
      el: null as HTMLSpanElement | null,
      angle: Math.random() * 2 * Math.PI,
      baseHeight: (i / NUM_PARTICLES) * 100, // in vh
      speed: Math.random() * 0.2 + 0.2,
      wobblePhase: Math.random() * 2 * Math.PI,
      wobbleFreq: Math.random() * 0.15 + 0.1,
      wobbleAmp: Math.random() * 2 + 1,
      secondaryWobblePhase: Math.random() * 2 * Math.PI,
      secondaryWobbleFreq: Math.random() * 0.2 + 0.05,
    }))
  );

  // 3. Logic Helpers
  const updateTimeText = () => {
    const now = new Date();
    let hours = now.getHours() % 12 || 12;
    const mins = now.getMinutes().toString().padStart(2, '0');
    setTimeString(`${hours}${mins}`);
  };

  const getRandColor = () => {
    const rand = Math.random();
    if (rand < 0.4) return `rgb(${Math.random() * 50 + 90}, ${Math.random() * 40 + 50}, ${Math.random() * 30 + 30})`;
    if (rand < 0.7) return `rgb(${Math.random() * 30 + 10}, ${Math.random() * 30 + 10}, ${Math.random() * 30 + 10})`;
    return `rgb(${Math.random() * 40 + 60}, 80, 70)`;
  };

  useEffect(() => {
    updateTimeText();
    let animationFrame: number;
    let clockInterval = setInterval(updateTimeText, 60000);
    let startTime = Date.now();

    const animate = () => {
      const elapsed = (Date.now() - startTime) / 1000;
      const swayOffset = Math.sin(elapsed) * 5;

      particles.current.forEach((p) => {
        if (!p.el) return;

        p.angle += p.speed * 0.05;
        p.baseHeight -= p.speed * 0.5;

        // Reset particle when it goes off top
        if (p.baseHeight < -10) {
          p.baseHeight = 110;
          p.el.textContent = timeString[Math.floor(Math.random() * timeString.length)] || '0';
          p.el.style.color = getRandColor();
        }

        const normalizedHeight = 1 - p.baseHeight / 100;
        const radius = (3 + normalizedHeight * 20) + Math.sin(elapsed + p.wobblePhase) * 1.5;
        const wobble = Math.sin(elapsed * p.wobbleFreq + p.wobblePhase) * p.wobbleAmp;

        const x = 50 + swayOffset + Math.cos(p.angle) * radius + wobble;
        const y = p.baseHeight;
        const scale = 0.5 + (p.baseHeight / 100) * 1.5;

        p.el.style.transform = `translate(${x}vw, ${y}vh) scale(${scale}) rotate(${p.angle * 50}deg)`;
        p.el.style.zIndex = Math.floor(scale * 10).toString();
      });

      animationFrame = requestAnimationFrame(animate);
    };

    // Flash Loop
    let flashTimeout: NodeJS.Timeout;
    const runFlash = () => {
      if (flashRef.current) {
        flashRef.current.style.backgroundColor = Math.random() > 0.5 ? 'white' : 'black';
        flashRef.current.style.opacity = '1';
        setTimeout(() => { if(flashRef.current) flashRef.current.style.opacity = '0' }, 50);
      }
      flashTimeout = setTimeout(runFlash, Math.random() * 2000 + 1000);
    };

    animate();
    runFlash();

    return () => {
      cancelAnimationFrame(animationFrame);
      clearInterval(clockInterval);
      clearTimeout(flashTimeout);
    };
  }, [timeString]);

  return (
    <div className="tornado-clock">
      <style>{`
        @font-face { font-family: 'speed'; src: url(${speedFont}); }
        .tornado-clock {
          position: relative; width: 100vw; height: 100vh; overflow: hidden;
          background: radial-gradient(ellipse at center, #8d906e 0%, #eaf5a2 100%);
        }
        .tornado-clock__letter {
          position: absolute; top: 0; left: 0; pointer-events: none;
          will-change: transform; font-family: 'speed', sans-serif;
          font-size: 5vh;
        }
        .tornado-clock__bg {
          position: absolute; width: 100%; height: 100%; object-fit: cover;
          opacity: 0.3; filter: contrast(0.2) invert(1); z-index: 0;
        }
        .flash-overlay {
          position: fixed; inset: 0; pointer-events: none; 
          transition: opacity 0.1s; z-index: 100; opacity: 0;
        }
      `}</style>

      <img src={torGif} className="tornado-clock__bg" alt="" />

      {/* React renders the spans once; the useEffect animates them via refs */}
      {particles.current.map((p, i) => (
        <span 
          key={i} 
          ref={el => p.el = el} 
          className="tornado-clock__letter"
        >
          {timeString[Math.floor(Math.random() * timeString.length)]}
        </span>
      ))}

      <div ref={flashRef} className="flash-overlay" />
    </div>
  );
};

export default Clock;

import React, { useEffect, useRef } from 'react';
import libreBaskerville from './LibreBaskerville.ttf';
import monofett from './Monofett-Regular.ttf';
import nanumCoding from './NanumGothicCoding.ttf';
import oxanium from './Oxanium-VariableFont_wght.ttf';
import robotoSlab from './RobotoSlab-VariableFont_wght.ttf';

const BounceClock: React.FC = () => {
  const roomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const room = roomRef.current;

    const fontStyles = `
      @font-face {
        font-family: 'Libre Baskerville';
        src: url(${libreBaskerville}) format('truetype');
      }
      @font-face {
        font-family: 'Monofett';
        src: url(${monofett}) format('truetype');
      }
      @font-face {
        font-family: 'Nanum Gothic Coding';
        src: url(${nanumCoding}) format('truetype');
      }
      @font-face {
        font-family: 'Oxanium';
        src: url(${oxanium}) format('truetype');
      }
      @font-face {
        font-family: 'Roboto Slab';
        src: url(${robotoSlab}) format('truetype');
      }
    `;

    const styleEl = document.createElement('style');
    styleEl.textContent = fontStyles;
    document.head.appendChild(styleEl);

    function createClock() {
      const sizes = [
        { size: 3, gravity: 1.0 },
        { size: 5, gravity: 0.5 },
        { size: 7, gravity: 0.01 },
        { size: 10, gravity: 0.05 },
        { size: 13, gravity: 0.001 },
      ];

      const { size, gravity } = sizes[Math.floor(Math.random() * sizes.length)];

      const clock = document.createElement('div');
      clock.className = 'clock';
      clock.style.width = `${size}rem`;
      clock.style.height = `${size}rem`;
      clock.style.left = `${Math.random() * 100}vw`;
      clock.style.top = `-20vh`;

      const color = `hsl(${Math.floor(Math.random() * 360)}, 10%, 30%)`;
      clock.style.background = color;
      clock.style.boxShadow = `0 0 ${size * 0.2}rem ${color}`;

      const hour = document.createElement('div');
      hour.className = 'hand hour';
      hour.style.width = `${size * 0.05}rem`;
      hour.style.height = `${size * 0.25}rem`;
      hour.style.top = `${size * 0.25}rem`;
      hour.style.left = `${size / 2 - (size * 0.05) / 2}rem`;

      const minute = document.createElement('div');
      minute.className = 'hand minute';
      minute.style.width = `${size * 0.025}rem`;
      minute.style.height = `${size * 0.4}rem`;
      minute.style.top = `${size * 0.1}rem`;
      minute.style.left = `${size / 2 - (size * 0.025) / 2}rem`;

      clock.appendChild(hour);
      clock.appendChild(minute);
      room.appendChild(clock);

      let y = -20;
      let velocity = 0;
      const bounce = 0.7;

      function animate() {
        velocity += gravity;
        y += velocity;

        if (y > window.innerHeight * 0.01 * (100 - size)) {
          y = window.innerHeight * 0.01 * (100 - size);
          velocity *= -bounce;
        }

        clock.style.top = `${(y / window.innerHeight) * 100}vh`;
        requestAnimationFrame(animate);
      }

      animate();
      updateHands(hour, minute);

      setTimeout(() => {
        clock.classList.add('fade-out');
        clock.addEventListener('transitionend', () => {
          if (clock.parentElement) {
            clock.parentElement.removeChild(clock);
          }
        });
      }, 30000);
    }

    function updateHands(hour, minute) {
      const now = new Date();
      const h = now.getHours();
      const m = now.getMinutes();
      hour.style.transform = `rotate(${(h % 12) * 30 + m * 0.5}deg)`;
      minute.style.transform = `rotate(${m * 6}deg)`;
    }

    const interval = setInterval(createClock, 1000);

    return () => {
      clearInterval(interval);
      document.head.removeChild(styleEl);
    };
  }, []);

  return (
    <div style={styles.body}>
      <div style={styles.titleContainer}>
        <div style={styles.chltitle}>Cubist Heart Laboratories</div>
        <div style={styles.bttitle}>BorrowedTime</div>
      </div>
      <div style={styles.dateContainer}>
        <a href="../fireworks/" style={{ ...styles.date, ...styles.dateleft }}>
          04/29/25
        </a>
        <a href="../index.html" style={styles.clockname}>
          Bounce
        </a>
        <a
          href="../slowlightning/"
          style={{ ...styles.date, ...styles.dateright }}
        >
          05/01/25
        </a>
      </div>
      <div ref={roomRef} style={styles.room} />
    </div>
  );
};

const styles = {
  body: {
    margin: 0,
    padding: 0,
    overflow: 'hidden',
    height: '100vh',
    background: 'linear-gradient(to top, #9ea4a0, #d7d7d8)',
    fontFamily: 'sans-serif',
    position: 'relative',
  },
  room: {
    position: 'relative',
    width: '100vw',
    height: '100vh',
    overflow: 'hidden',
  },
  titleContainer: {
    color: '#cacccb',
    textShadow: '#82877e 0.05rem 0',
    position: 'absolute',
    top: '0.5vh',
    left: '50%',
    transform: 'translateX(-50%)',
    width: '98vw',
    display: 'flex',
    zIndex: 6,
  },
  chltitle: {
    fontFamily: 'Roboto Slab',
    fontSize: '2.1vh',
    position: 'absolute',
    top: '0.3vh',
    right: '1vw',
    letterSpacing: '0.1vh',
  },
  bttitle: {
    position: 'relative',
    left: 0,
    fontFamily: 'Oxanium',
    fontSize: '2.7vh',
    fontStyle: 'italic',
    letterSpacing: '-0.1vh',
  },
  dateContainer: {
    color: '#bcb885',
    position: 'absolute',
    bottom: '0.5vh',
    left: '50%',
    transform: 'translateX(-50%)',
    width: '98vw',
    display: 'flex',
    zIndex: 6,
  },
  date: {
    fontFamily: 'Nanum Gothic Coding',
    fontSize: '3vh',
  },
  dateleft: {
    position: 'relative',
    left: 0,
  },
  dateright: {
    position: 'absolute',
    right: 0,
  },
  clockname: {
    position: 'fixed',
    left: '50%',
    transform: 'translateX(-50%)',
    fontFamily: 'Oxanium',
    fontSize: '4vh',
    lineHeight: '4vh',
  },
};

// Global CSS classes injected into the page for animation
const globalCSS = document.createElement('style');
globalCSS.textContent = `
.clock {
  position: absolute;
  border-radius: 50%;
  transition: transform 5s ease, opacity 5s ease;
  box-shadow: 0 0 2rem rgba(0, 0, 0, 0.3);
  will-change: transform, opacity;
}
.hand {
  position: absolute;
  transform-origin: bottom center;
  border-radius: 0.2rem;
}
.hour {
  background: rgb(192, 188, 188);
}
.minute {
  background: rgb(216, 209, 153);
}
.fade-out {
  transform: scale(0);
  opacity: 0;
}
a {
  color: inherit;
  text-decoration: none;
}
a:hover {
  color: #e8ecec;
  background-color: rgb(21, 0, 255);
}
`;
document.head.appendChild(globalCSS);

export default BounceClock;

