import number8Img from '@/assets/images/2025/25-06/25-06-02/num8.webp';
import number9Img from '@/assets/images/2025/25-06/25-06-02/num9.webp';
import number10Img from '@/assets/images/2025/25-06/25-06-02/num10.webp';
import number11Img from '@/assets/images/2025/25-06/25-06-02/num11.webp';
import number12Img from '@/assets/images/2025/25-06/25-06-02/num12.webp';

import hourHandImg from '@/assets/images/2025/25-06/25-06-02/hour.png';
import minuteHandImg from '@/assets/images/2025/25-06/25-06-02/min.png';
import secondHandImg from '@/assets/images/2025/25-06/25-06-02/min.png';

export default function AnalogImageClock() {
  const [time, setTime] = useState(new Date());
  const [gradientShift, setGradientShift] = useState<number>(0); // for gradient animation

  useEffect(() => {
    const interval = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const anim = setInterval(() => {
      setGradientShift((prev) => (prev + 0.5) % 360);
    }, 50);
    return () => clearInterval(anim);
  }, []);

  const numberImages = [
    number12Img,
    number1Img,
    number2Img,
    number3Img,
    number4Img,
    number5Img,
    number6Img,
    number7Img,
    number8Img,
    number9Img,
    number10Img,
    number11Img,
  ];

  const hours = time.getHours() % 12;
  const minutes = time.getMinutes();
  const seconds = time.getSeconds();

  const hourDeg = (hours + minutes / 60) * 30;
  const minuteDeg = (minutes + seconds / 60) * 6;
  const secondDeg = seconds * 6;

  const renderNumbers = () =>
    numberImages.map((img, i) => {
      const angle = (i * 30 - 90) * (Math.PI / 180); // start from top
      const radius = 40; // percent of clock container
      const x = 50 + radius * Math.cos(angle);
      const y = 50 + radius * Math.sin(angle);
      return (
        <img
          decoding="async"
          loading="lazy"
          key={i}
          src={img}
          alt={`number-${i}`}
          style={{
            position: 'absolute',
            width: '10vmin',
            height: '10vmin',
            left: `${x}%`,
            top: `${y}%`,
            transform: 'translate(-50%, -50%)',
          }}
        />
      );
    });

  const handStyle = (deg, widthVmin, heightVmin) => ({
    position: 'absolute',
    width: `${widthVmin}vmin`,
    height: `${heightVmin}vmin`,
    top: '50%',
    left: '50%',
    transform: `rotate(${deg}deg) translate(-50%, -50%)`,
    transformOrigin: '50% 50%',
  });

  const backgrounds = [
    { src: bg1Img, opacity: 0.91, zIndex: 1 },
    { src: bg2Img, opacity: 0.91, zIndex: 2 },
    { src: bg3Img, opacity: 0.8, zIndex: 3 },
    { src: bg4Img, opacity: 0.7, zIndex: 4 },
  ];

  return (
    <div
      style={{
        position: 'relative',
        width: '100vw',
        height: '100vh',
        background: `linear-gradient(${gradientShift}deg, #1a1a1a, #3a3a3a, #5a5a5a)`,
        transition: 'background 0.05s linear',
        overflow: 'hidden',
      }}
    >
      {/* Backgrounds */}
      {backgrounds.map((bg, idx) => (
        <img
          decoding="async"
          loading="lazy"
          key={idx}
          src={bg.src}
          alt={`background-${idx}`}
          style={{
            position: 'absolute',
            width: '100%',
            height: '100%',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            zIndex: bg.zIndex,
            opacity: bg.opacity,
            objectFit: 'cover',
          }}
        />
      ))}

      {/* Centered Clock */}
      <div
        style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          width: '80vmin',
          height: '80vmin',
          borderRadius: '50%',
          transform: 'translate(-50%, -50%)',
          overflow: 'visible',
          zIndex: 10,
        }}
      >
        {renderNumbers()}
        <img
          decoding="async"
          loading="lazy"
          src={hourHandImg}
          alt="hour-hand"
          style={handStyle(hourDeg, 2, 25)}
        />
        <img
          decoding="async"
          loading="lazy"
          src={minuteHandImg}
          alt="minute-hand"
          style={handStyle(minuteDeg, 1.5, 35)}
        />
        <img
          decoding="async"
          loading="lazy"
          src={secondHandImg}
          alt="second-hand"
          style={handStyle(secondDeg, 1, 40)}
        />
      </div>
    </div>
  );
}

