const Clock: React.FC = () => {
  const [time, setTime] = useState<Date>(() => new Date());

  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'air',
      fontUrl: airFontUrl,
