    .toLocaleTimeString('en-US', {
      hour12: false,
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    })
    .replace(/:/g, '');
  const format = [
    'digit',
    'digit',
    'colon',
    'digit',
    'digit',
    'colon',
    'digit',
