          if (type === 'colon') {
            return (
              <div
                key={idx}
                style={{ ...styles.colon, ...styles.jostle }}
                aria-hidden="true"
              >
                :
              </div>
            );
          }
          return (
            <div key={idx} style={{ ...styles.digitBox, ...styles.jostle }}>
              {timeParts[i++]}
            </div>
          );
        })}
      </div>
