    }),
    digit: {
      color: '#D0C7C7FF',
      textShadow: '#14170EFF 0.2rem 0.2rem 0, #2C2D29FF -0.2rem -0.2rem 0',
      position: 'relative',
      transformStyle: 'preserve-3d',
      width: '0.3rem',
      height: '1rem',
      fontSize: '4.8rem',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
    },
    faceFront: {
      position: 'absolute',
      width: '100%',
      height: '100%',
      backfaceVisibility: 'hidden',
      color: 'white',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      fontSize: '4.8rem',
    },
    faceBack: {
      position: 'absolute',
      width: '100%',
      height: '100%',
      backfaceVisibility: 'hidden',
      color: '#080D01FF',
      textShadow: '#EBE7E7FF 0.3rem 0.3rem 0, #F0EEEEFF -0.3rem -0.3rem 0',
      backgroundColor: 'rgba(27, 5, 117, 0.2)',
      transform: 'rotateY(180deg)',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      fontSize: '4.8rem',
    },
  };

  return (
    <div style={styles.root}>
      <div style={styles.container}>
        <div id="clockBox" style={styles.box}>
          {[...Array(16)].map((_, i) => (
            <div key={i} className="face" style={styles.face(i)}>
              {[...Array(6)].map((__, j) => (
                <div key={j} className="digit" style={styles.digit}>
                  <div className="face-front" style={styles.faceFront}>
                    {digits[j] || '0'}
                  </div>
                  <div className="face-back" style={styles.faceBack}>
                    {digits[j] || '0'}
                  </div>
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      <style>{`
        @keyframes rotate {
          0% { transform: rotateX(0deg) rotateY(0deg); }
          100% { transform: rotateX(360deg) rotateY(360deg); }
        }
      `}</style>
    </div>
  );
};

export default FiligreeClock;

