import React, { useEffect, useState } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import treeFont from '@/assets/fonts/2025/25-06-05-tree.ttf';
import tree1Img from '@/assets/images/2025/25-06/25-06-05/tree1.webp';
import tree2Img from '@/assets/images/2025/25-06/25-06-05/tree2.webp';

const TreehouseClock: React.FC = () => {
  const [time, setTime] = useState(new Date());

  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'TreeFont',
      fontUrl: treeFont,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  useEffect(() => {
    const interval = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(interval);
  }, []);

  let hours = time.getHours() % 12 || 12;
  let minutes = time.getMinutes().toString().padStart(2, '0');
  let hourStr = hours.toString();

  const digitStyle = {
    color: 'rgb(224, 200, 127)',
    textShadow:
      'red 0.04vw 0 0.1vw, rgb(1, 16, 1) 0 -0.1vw 0.1vw, rgb(175, 192, 24) 0 0 1vw',
    fontSize: '2.7rem',
    fontFamily: 'TreeFont, sans-serif',
    textAlign: 'center',
  };

  const treeStyle1 = {
    position: 'absolute',
    left: '50%',
    top: '50%',
    height: '92vh',
    width: '95vw',
    transform: 'translate(-50%, -50%) scaleX(-1)',
    zIndex: 7,
    opacity: 0.6,
  };

  const treeStyle2 = {
    position: 'absolute',
    left: '52%',
    top: '50%',
    height: '93vh',
    width: '95vw',
    transform: 'translate(-50%, -50%)',
    zIndex: 2,
    opacity: 0.6,
  };

  const treeStyle2a = {
    position: 'absolute',
    left: '46%',
    top: '50%',
    height: '94vh',
    width: '93vw',
    transform: 'translate(-50%, -50%) scaleX(-1)',
    zIndex: 5,
    opacity: 0.6,
  };

  const bodyStyle = {
    margin: 0,
    padding: 0,
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    height: '100dvh',
    width: '100vw',
    background:
      'linear-gradient(180deg, rgb(142, 183, 243) 0%, rgb(108, 164, 197) 80%)',
    position: 'relative',
    overflow: 'hidden',
  };

  const clockStyle = {
    display: 'flex',
    alignItems: 'center',
    position: 'relative',
    zIndex: 5,
    top: '-9vh',
    gap: '0.3rem',
    left: '-4vw', // 👈 Move to the left
  };

  return (
    <div style={bodyStyle}>
      <img
        decoding="async"
        loading="lazy"
        src={tree1Img}
        alt="tree1"
        style={treeStyle1}
      />
      <img
        decoding="async"
        loading="lazy"
        src={tree2Img}
        alt="tree2"
        style={treeStyle2}
      />
      <img
        decoding="async"
        loading="lazy"
        src={tree2Img}
        alt="tree2"
        style={treeStyle2a}
      />
      <div style={clockStyle}>
        {hourStr.length === 2 ? (
          <>
            <div style={digitStyle}>{hourStr[0]}</div>
            <div style={digitStyle}>{hourStr[1]}</div>
          </>
        ) : (
          <>
            <div style={{ ...digitStyle, visibility: 'hidden' }}>0</div>
            <div style={digitStyle}>{hourStr[0]}</div>
          </>
        )}
        <span style={digitStyle}>:</span>
        <div style={digitStyle}>{minutes[0]}</div>
        <div style={digitStyle}>{minutes[1]}</div>
      </div>
    </div>
  );
};

export default TreehouseClock;

import React, { useEffect } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import rrrrFont from '@/assets/fonts/2025/25-06-06-rrrr.ttf';

const RollingClock: React.FC = () => {
  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'rrrr',
      fontUrl: rrrrFont,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);
  useEffect(() => {
    const ticker = document.getElementById('ticker');
    const clockSpeed = 40;
    const screenWidth = window.innerWidth;

    function createClock() {
      const clockContainer = document.createElement('div');
      clockContainer.className = 'clock-container';
      clockContainer.style.left = screenWidth + 'px';

      const clock = document.createElement('div');
      clock.className = 'clock';

      for (let i = 1; i <= 12; i++) {
        const num = document.createElement('div');
        num.className = 'number';
        num.innerText = i;
        const angle = (i - 3) * 30 * (Math.PI / 180);
        const r = 40;
        const x = 50 + r * Math.cos(angle);
        const y = 50 + r * Math.sin(angle);
        num.style.left = `${x}%`;
        num.style.top = `${y}%`;
        num.style.transform = `translate(-50%, -50%) rotate(${(i - 3) * 30}deg)`;
        clock.appendChild(num);
      }

      const hourHand = document.createElement('div');
      hourHand.className = 'hand hour';
      const minuteHand = document.createElement('div');
      minuteHand.className = 'hand minute';
      const secondHand = document.createElement('div');
      secondHand.className = 'hand';
      const centerDot = document.createElement('div');
      centerDot.className = 'center-dot';

      clock.appendChild(hourHand);
      clock.appendChild(minuteHand);
      clock.appendChild(secondHand);
      clock.appendChild(centerDot);
      clockContainer.appendChild(clock);
      ticker.appendChild(clockContainer);

      function updateHands() {
        const now = new Date();
        const utc = now.getTime() + now.getTimezoneOffset() * 60000;
        const edt = new Date(utc - 4 * 3600000);
        const sec = edt.getSeconds();
        const min = edt.getMinutes();
        const hr = edt.getHours();

        secondHand.style.transform = `rotate(${sec * 6}deg)`;
        minuteHand.style.transform = `rotate(${min * 6 + sec * 0.1}deg)`;
        hourHand.style.transform = `rotate(${(hr % 12) * 30 + min * 0.5}deg)`;
      }

      updateHands();
      setInterval(updateHands, 1000);

      const clockWidth = 300;
      const totalTravel = screenWidth + clockWidth + 100;
      const start = performance.now();

      function animate(now) {
        const elapsed = now - start;
        const distance = (elapsed / 2000) * clockSpeed;
        const angle = -(distance / (Math.PI * clockWidth)) * 360;
        clockContainer.style.left = `${screenWidth - distance}px`;
        clockContainer.style.transform = `translateY(-50%) rotate(${angle}deg)`;
        if (distance < totalTravel) {
          requestAnimationFrame(animate);
        } else {
          clockContainer.remove();
        }
      }

      requestAnimationFrame(animate);
    }

    createClock();
    const intervalId = setInterval(createClock, 3500);
    return () => clearInterval(intervalId);
  }, []);

  return (
    <div style={styles.wrapper}>
      <style>{`
        @font-face {
          font-family: 'rrrr';
          src: url(${rrrrFont}) format('truetype');
        }

        #ticker {
          position: absolute;
          top: 50%;
          left: 0;
          width: 100vw;
          height: 100dvh;
          transform: translateY(-50%);
        }

        .clock-container {
          position: absolute;
          top: 50%;
          transform: translateY(-50%);
          width: 400px;
          height: 400px;
        }

        .clock {
          position: relative;
          width: 100%;
          height: 100%;
          border-radius: 50%;
        }

        .number {
          position: absolute;
          font-family: 'rrrr', sans-serif;
          font-size: 1.2rem;
          color: #C9F7E3FF;
        }

        .hand {
          position: absolute;
          bottom: 50%;
          left: 50%;
          transform-origin: bottom center;
          background: white;
          border-radius: 0.5rem;
        }

        .hand.hour {
          height: 60px;
          width: 8px;
          background: green;
        }

        .hand.minute {
          height: 90px;
          width: 6px;
          background: blue;
        }

        .hand {
          height: 600px;
          width: 2px;
          background: cyan;
        }

        .center-dot {
          position: absolute;
          top: 50%;
          left: 50%;
          width: 19px;
          height: 19px;
          background: black;
          border-radius: 50%;
          transform: translate(-50%, -50%);
        }
      `}</style>
      <div id="ticker" />
    </div>
  );
};

const styles = {
  wrapper: {
    overflow: 'hidden',
    margin: 0,
    padding: 0,
    height: '100vh',
    width: '100vw',
    backgroundImage:
      'radial-gradient(#301e01 11px, transparent 11px), radial-gradient(#301e01 11px, transparent 11px)',
    backgroundSize: '56px 56px',
    backgroundPosition: '0 0, 28px 28px',
    backgroundColor: '#4b1a03',
    position: 'relative',
    fontFamily: "'rrrr', sans-serif",
  },
};

export default RollingClock;

