const StitchesClock: React.FC = () => {
  useEffect(() => {
    // Load font with unique name
    const font = new FontFace('ZombieStitch_2025_10_29', `url(${fontUrl})`);
    font.load().then((loadedFont) => {
      document.fonts.add(loadedFont);
    });

    const updateClock: React.FC = () => {
      const now = new Date();
      let h = now.getHours();
      const m = now.getMinutes();
      const ampm = h >= 12 ? 'PM' : 'AM';

      h = h % 12 || 12;
      const hStr = String(h);
      const mStr = String(m).padStart(2, '0');
      const allChars = hStr + mStr + ampm;

      const container = document.getElementById('clockRow');
      if (!container) return;
      container.innerHTML = '';

      for (let i = 0; i < allChars.length; i++) {
        const ch = allChars[i];
        const span = document.createElement('span');
        span.className = 'digit';
        span.textContent = ch;
        Object.assign(span.style, styles.digit);
        container.appendChild(span);
      }
    };

    updateClock();
    const interval = setInterval(updateClock, 10000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div style={styles.body}>
      <div
        style={{ ...styles.bgImage, backgroundImage: `url(${bgImageUrl})` }}
      />
      <img
        decoding="async"
        loading="lazy"
        src={overlayImageUrl}
        alt="stitched overlay"
        style={styles.bgOverlay}
      />
      <div id="clockRow" style={styles.clockRow}></div>
    </div>
  );
};

