import React, { useEffect } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import kla from '@/assets/images/2025/25-06/25-06-16/kla.webp';
import klax from '@/assets/images/2025/25-06/25-06-16/klax.png';
import klaxon from '@/assets/images/2025/25-06/25-06-16/klaxon.png';
import klaHand from '@/assets/images/2025/25-06/25-06-16/kla.png';
import klaxFont from '@/assets/fonts/2025/25-06-16-klax.ttf';
import overlayImage from '@/assets/images/2025/25-06/25-06-16/klax.webp';

const romanNumerals = [
  'xii',
  'i',
  'ii',
  'iii',
  'iv',
  'v',
  'vi',
  'vii',
  'viii',
  'ix',
  'x',
  'xi',
];

const KlaxonClock: React.FC = () => {
  useEffect(() => {
    const fontStyle = document.createElement('style');
    fontStyle.textContent = `
      @font-face {
        font-family: 'klax';
        src: url(${klaxFont}) format('truetype');
      }
    `;
    document.head.appendChild(fontStyle);

    const clock = document.getElementById('clock');
    const numberElements = [];

    romanNumerals.forEach((num, i) => {
      const angleDeg = i * 30;
      const angleRad = (angleDeg * Math.PI) / 180;
      const radius = 43;

      const x = 50 + radius * Math.sin(angleRad);
      const y = 50 - radius * Math.cos(angleRad);

      const el = document.createElement('div');
      el.className = 'number';
      el.style.left = `${x}%`;
      el.style.top = `${y}%`;
      el.textContent = num;
      el.style.transform = `translate(-50%, -50%) rotate(${angleDeg}deg)`;
      el.dataset.angle = angleDeg;
      el.isFlashing = false;
      el.lastPassedTime = 0;
      numberElements.push(el);
      clock.appendChild(el);
    });

    const flashStartOffset = 6;
    const flashEndOffset = 6;
    const lingerDuration = 300;

    const updateClock: React.FC = () => {
      const now = new Date();
      const ms = now.getMilliseconds();
      const sec = now.getSeconds() + ms / 1000;
      const min = now.getMinutes();
      const hr = now.getHours();

      const secondDeg = sec * 6;
      const minuteDeg = min * 6 + sec * 0.1;
      const hourDeg = (hr % 12) * 30 + min * 0.5;

      document.getElementById('second').style.transform =
        `translateX(-50%) rotate(${secondDeg}deg)`;
      document.getElementById('minute').style.transform =
        `translateX(-50%) rotate(${minuteDeg}deg)`;
      document.getElementById('hour').style.transform =
        `translateX(-50%) rotate(${hourDeg}deg)`;

      const normalizedSecond = secondDeg % 360;

      numberElements.forEach((el) => {
        const numAngle = parseFloat(el.dataset.angle);
        let startAngle = (numAngle - flashStartOffset + 360) % 360;
        let endAngle = (numAngle + flashEndOffset) % 360;

        let insideZone = false;
        if (startAngle < endAngle) {
          insideZone =
            normalizedSecond >= startAngle && normalizedSecond <= endAngle;
        } else {
          insideZone =
            normalizedSecond >= startAngle || normalizedSecond <= endAngle;
        }

        if (insideZone) {
          el.isFlashing = true;
          el.lastPassedTime = performance.now();
          el.classList.add('flash-red');
        } else {
          const nowTime = performance.now();
          if (el.isFlashing && nowTime - el.lastPassedTime < lingerDuration) {
            el.classList.add('flash-red');
          } else {
            el.isFlashing = false;
            el.classList.remove('flash-red');
          }
        }
      });

      requestAnimationFrame(updateClock);
    };

    requestAnimationFrame(updateClock);
  }, []);

  const formatDate = (offset) => {
    const d = new Date();
    d.setDate(d.getDate() + offset);
    return `${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getDate()).padStart(2, '0')}/${String(d.getFullYear()).slice(-2)}`;
  };

  return (
    <div style={styles.body}>
      <div style={styles.bgImage}></div>

      <div style={styles.overlay}></div>

      <div style={styles.clockWrapper}>
        <div style={styles.clock} id="clock">
          <img
            decoding="async"
            loading="lazy"
            src={klax}
            alt="Hour Hand"
            className="hand hour"
            id="hour"
            style={styles.handHour}
          />
          <img
            decoding="async"
            loading="lazy"
            src={klaxon}
            alt="Minute Hand"
            className="hand minute"
            id="minute"
            style={styles.handMinute}
          />
          <img
            decoding="async"
            loading="lazy"
            src={klaHand}
            alt="Second Hand"
            className="hand second"
            id="second"
            style={styles.handSecond}
          />
        </div>
      </div>

      <style>{`
        .number {
          position: absolute;
          font-size: 29.5vh;
          font-weight: bold;
          transform-origin: center center;
          z-index: 6;
          opacity: 0.8;
          font-family: 'klax', serif;
        }

        .flash-red {
          animation: flash 0.01s ease-in-out alternate infinite;
        }

        @keyframes flash {
          from {
            color: rgb(246, 114, 37);
          }
          to {
            color: rgb(247, 46, 136);
            text-shadow:
              0 0 1rem rgb(11, 237, 211),
              0 0 2rem rgb(237, 11, 11),
              0 0 5rem rgb(238, 8, 54),
              0 0 5rem rgb(238, 8, 85);
          }
        }
      `}</style>
    </div>
  );
};

const styles = {
  body: {
    margin: 0,
    padding: 0,
    height: '100dvh',
    width: '100vw',
    background: '#0c0c0c',
    position: 'relative',
    overflow: 'hidden',
    fontFamily: 'klax, serif',
  },
  bgImage: {
    backgroundImage: `url(${kla})`,
    position: 'fixed',
    top: 0,
    left: 0,
    width: '100vw',
    height: '100vh',
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    backgroundRepeat: 'no-repeat',
    filter: 'brightness(50%)',
    zIndex: 1,
    pointerEvents: 'none',
  },
  overlay: {
    backgroundImage: `url(${overlayImage})`,
    position: 'fixed',
    top: 0,
    left: 0,
    width: '100vw',
    height: '100vh',
    backgroundSize: '190%', // Scale up the image
    backgroundPosition: 'center',
    backgroundRepeat: 'no-repeat',
    zIndex: 2,
    pointerEvents: 'none',
    opacity: 0.7,
    mixBlendMode: 'screen',
  },

  clockWrapper: {
    position: 'relative',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    width: '100vw',
    height: '100vh',
    zIndex: 5,
  },
  clock: {
    width: '80vmin',
    height: '80vmin',
    borderRadius: '50%',
    position: 'relative',
    color: 'rgb(241, 231, 244)',
  },
  handHour: {
    position: 'absolute',
    bottom: '50%',
    left: '50%',
    transformOrigin: 'bottom',
    transform: 'translateX(-50%)',
    height: '35%',
    filter:
      'sepia(100%) saturate(150%) hue-rotate(-10deg) brightness(90%) contrast(120%)',
    zIndex: 7,
    pointerEvents: 'none',
  },
  handMinute: {
    position: 'absolute',
    bottom: '50%',
    left: '50%',
    transformOrigin: 'bottom',
    transform: 'translateX(-50%)',
    height: '45%',
    zIndex: 7,
    pointerEvents: 'none',
  },
  handSecond: {
    position: 'absolute',
    bottom: '50%',
    left: '50%',
    transformOrigin: 'bottom',
    transform: 'translateX(-50%)',
    height: '55%',
    zIndex: 7,
    pointerEvents: 'none',
  },
};

export default KlaxonClock;

import React, { useEffect, useRef } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import backFont from '@/assets/fonts/2025/25-06-17-back.ttf';

const BackslantClock: React.FC = () => {
  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'back',
      fontUrl: backFont,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  const ids = ['h0', 'h1', 'm0', 'm1', 's0', 's1'];
  const trains = useRef({});
  const positions = useRef({});
  const lastDigits = useRef({});
  const targetOffsets = useRef({});
  const currentOffsets = useRef({});

  // Font loading handled by useMultipleFontLoader

  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = `
      .digitTrain span {
        color: rgb(4, 95, 151);
        text-shadow: #f24e07 0.2rem 0.2rem 0;
      }
      .digitTrain span.active {
        color: #FF5500FF; /* Bright red for active digit */
        text-shadow: #080707FF 0.2rem 0.2rem 0;
      }
      .digitTrain span.leaving {
        transition: opacity 0.4s linear;
        opacity: 0;
      }
    `;
    document.head.appendChild(style);
  }, []);

  useEffect(() => {
    const createDigitLine: React.FC = () => {
      const frag = document.createDocumentFragment();
      for (let i = 0; i < 50; i++) {
        const span = document.createElement('span');
        span.textContent = i % 10;
        frag.appendChild(span);
      }
      return frag;
    };

    ids.forEach((id) => {
      const trainEl = document.getElementById(id + 'train');
      trainEl.appendChild(createDigitLine());
      trains.current[id] = trainEl;
      positions.current[id] = 0;
      lastDigits.current[id] = null;
      targetOffsets.current[id] = 0;
      currentOffsets.current[id] = 0;
    });

    const lerp = (a, b, t) => a + (b - a) * t;

    const getNextPosition = (id, digit) => {
      const train = trains.current[id];
      const currentPos = positions.current[id];
      const children = Array.from(train.children);
      for (let i = currentPos + 1; i < children.length; i++) {
        if (children[i].textContent === digit) return i;
      }
      for (let i = 0; i <= currentPos; i++) {
        if (children[i].textContent === digit) return i;
      }
      return currentPos;
    };

    const updateClock: React.FC = () => {
      const now = new Date();
      const digits = [
        ...now.getHours().toString().padStart(2, '0'),
        ...now.getMinutes().toString().padStart(2, '0'),
        ...now.getSeconds().toString().padStart(2, '0'),
      ];

      digits.forEach((digit, i) => {
        const id = ids[i];
        const train = trains.current[id];

        if (digit !== lastDigits.current[id]) {
          Array.from(train.children).forEach((span) => {
            if (!span.classList.contains('leaving'))
              span.classList.remove('active');
          });

          const oldSpan = train.querySelector('span.active');
          if (oldSpan) {
            oldSpan.classList.add('leaving');
            oldSpan.addEventListener(
              'animationend',
              () => oldSpan.classList.remove('leaving', 'active'),
              { once: true },
            );
          }

          positions.current[id] = getNextPosition(id, digit);
          const spanWidth = train.children[0].offsetWidth || 0;
          targetOffsets.current[id] = positions.current[id] * spanWidth;
          lastDigits.current[id] = digit;

          const newSpan = train.children[positions.current[id]];
          if (newSpan) newSpan.classList.add('active');
        }
      });

      ids.forEach((id) => {
        const train = trains.current[id];
        currentOffsets.current[id] = lerp(
          currentOffsets.current[id],
          targetOffsets.current[id],
          0.1,
        );
        train.style.transform = `translateX(-${currentOffsets.current[id]}px)`;
      });

      requestAnimationFrame(updateClock);
    };

    updateClock();
  }, []);

  const formatDate = (offsetDays = 0) => {
    const date = new Date();
    date.setDate(date.getDate() + offsetDays);
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    const y = String(date.getFullYear()).slice(-2);
    return `${m}/${d}/${y}`;
  };

  return (
    <div style={styles.body}>
      <div style={styles.wrapper}>
        <div style={styles.clock} role="timer" aria-label="Digital clock">
          {ids.map((id) => (
            <div key={id} style={styles.clockRow}>
              <div
                id={`${id}train`}
                className="digitTrain"
                style={styles.digitTrain}
              ></div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const styles = {
  body: {
    margin: 0,
    padding: 0,
    height: '100dvh',
    width: '100vw',
    backgroundImage:
      'linear-gradient(24deg, #211408 6.25%, #f3a64e 6.25%, #ea8007 25%, #fff 25%, #f9c2c2 31.25%, #e3630d 31.25%, #e3630d 50%, #211408 50%, #0b30ea 56.25%, #ed8917 56.25%, #ed8917 75%, #f60808 75%, #fff 81.25%, #e3630d 81.25%, #e3630d 100%)',
