import React, { useEffect, useRef, useState } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import morseFont from '@/assets/fonts/2025/25-06-27-morse.ttf';
import birdsGif from '@/assets/images/2025/25-06/25-06-27/birds.gif';

const colors = [
  '#c0c6c7',
  '#99a3a3',
  '#96431FFF',
  '#666666',
  '#333333',
  '#777777',
  '#444444',
  '#999999',
  '#888888',
  '#aaaaaa',
  '#bbbbbb',
  '#66615C',
  '#c0c6c7',
  '#99a3a3',
  '#894528FF',
  '#7E4930FF',
];

const totalLines = 250;
const svgWidth = 1000; // virtual coordinate system for SVG
const svgHeight = 500;

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

const MorseClock: React.FC = () => {
  const [time, setTime] = useState(new Date());
  const [digits, setDigits] = useState(Array(6).fill('0'));
  const [changingIndices, setChangingIndices] = useState(new Set());
  const wiresRef = useRef([]);
  const svgRef = useRef(null);

  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'morse',
      fontUrl: morseFont,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  // Initialize wires on mount
  useEffect(() => {
    if (!svgRef.current) return;
    wiresRef.current = [];

    // Calculate evenly spaced Y positions with shuffle
    const step = svgHeight / (totalLines + 1);
    const yPositions = Array.from(
      { length: totalLines },
      (_, i) => (i + 1) * step,
    );

    // Shuffle positions
    for (let i = yPositions.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [yPositions[i], yPositions[j]] = [yPositions[j], yPositions[i]];
    }

    // Clear previous SVG children
    while (svgRef.current.firstChild) {
      svgRef.current.removeChild(svgRef.current.firstChild);
    }

    for (let i = 0; i < totalLines; i++) {
      const sagFactor = randomInt(10, 100);
      const baseY = yPositions[i];
      const controlX = randomInt(svgWidth * 0.3, svgWidth * 0.7);
      const controlY = baseY + sagFactor;

      const path = document.createElementNS(
        'http://www.w3.org/2000/svg',
        'path',
      );
      const d = `M0 ${baseY} Q${controlX} ${controlY} ${svgWidth} ${baseY}`;
      path.setAttribute('d', d);
      path.setAttribute('stroke', colors[i % colors.length]);
      path.setAttribute('stroke-width', (1 + (i % 3) * 0.5).toString());
      path.setAttribute('fill', 'none');
      path.style.transition = 'd 0.5s ease-in-out';
      svgRef.current.appendChild(path);

      wiresRef.current.push({
        path,
        currentStartY: baseY,
        currentEndY: baseY,
        currentControlX: controlX,
        currentControlY: controlY,
        targetStartY: baseY,
        targetEndY: baseY,
        targetControlX: controlX,
        targetControlY: controlY,
        fixedStartY: baseY,
        fixedEndY: baseY,
      });
    }
  }, []);

  // Update wires animation function
  function updateWires() {
    wiresRef.current.forEach((wire) => {
      const sagFactor = randomInt(10, 100);
      wire.targetControlY = wire.fixedStartY + sagFactor;
      wire.targetControlX = randomInt(svgWidth * 0.3, svgWidth * 0.7);

      // Interpolate positions
      wire.currentControlY +=
        (wire.targetControlY - wire.currentControlY) * 0.1;
      wire.currentControlX +=
        (wire.targetControlX - wire.currentControlX) * 0.1;

      // Compose new path d attribute
      const d = `M0 ${wire.fixedStartY} Q${wire.currentControlX} ${wire.currentControlY} ${svgWidth} ${wire.fixedEndY}`;
      wire.path.setAttribute('d', d);
    });
  }

  // Update time and digits every second
  useEffect(() => {
    const interval = setInterval(() => {
      const now = new Date();

      setTime(now);

      const hours = now.getHours().toString().padStart(2, '0');
      const minutes = now.getMinutes().toString().padStart(2, '0');
      const seconds = now.getSeconds().toString().padStart(2, '0');
      const newDigits = [...hours, ...minutes, ...seconds];

      // Detect which digits changed to animate fade
      setChangingIndices((prev) => {
        const changed = new Set();
        newDigits.forEach((digit, idx) => {
          if (digit !== digits[idx]) changed.add(idx);
        });
        return changed;
      });

      setDigits(newDigits);
      updateWires();
    }, 1000);

    return () => clearInterval(interval);
  }, [digits]);

  // Clear changing classes after fade duration (300ms)
  useEffect(() => {
    if (changingIndices.size === 0) return;
    const timeout = setTimeout(() => {
      setChangingIndices(new Set());
    }, 300);
    return () => clearTimeout(timeout);
  }, [changingIndices]);

  // Styles

  const styles = {
    container: {
      margin: 0,
      height: '100dvh',
      width: '100vw',
      background: 'linear-gradient(to bottom, #87CEEB 0%, #E0F6FF 100%)',
      position: 'relative',
      overflow: 'hidden',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      fontFamily: "'morse', Arial, sans-serif",
    },
    bgImage: {
      position: 'absolute',
      top: 0,
      left: 0,
      width: '100vw',
      height: '60vh',
      objectFit: 'cover',
      zIndex: 0,
      opacity: 0.5,
      userSelect: 'none',
      pointerEvents: 'none',
    },
    svg: {
      position: 'absolute',
      top: 0,
      left: 0,
      width: '100vw',
      height: '100vh', // increase from 50vh to 100vh or desired height
      zIndex: 1,
      pointerEvents: 'none',
    },

    clock: {
      display: 'flex',
      flexDirection: 'column', // vertical stack
      gap: '2rem',
      position: 'relative',
      zIndex: 4,
      userSelect: 'none',
      alignItems: 'center', // center digits horizontally
    },
    digitBox: {
      width: '900%',
      height: '1.5rem', // taller for vertical stacking
      backgroundColor: '#b87333',
      color: '#b90404',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      fontSize: '3rem',
      boxShadow:
        '0px -0.2rem 0px #9db4a0, 0px 0.2rem 0px #9db4a0, 0px -0.325rem 0.25rem #ecf1c6, 0px 0.45rem 0.525rem #1a1b1a',
      fontWeight: 'normal',
      textShadow:
        '0px -0.125rem 0px rgb(250, 247, 247), -0.125rem 0px 0px rgb(247, 242, 242), 0.125rem 0px 0px rgba(0, 0, 0), 0px 0.125rem 0px rgba(0, 0, 0), 0px -0.0625rem 0px rgb(248, 241, 241), -0.0625rem 0px 0px rgba(0, 0, 0), 0.0625rem 0px 0px rgba(0, 0, 0), 0px 0.0625rem 0px rgba(0, 0, 0)',
      transition: 'opacity 0.3s ease-in-out',
      userSelect: 'none',
    },
    digitText: (isChanging) => ({
      opacity: isChanging ? 0 : 1,
      transition: 'opacity 0.3s ease-in-out',
    }),
  };

  return (
    <div style={styles.container}>
      <img
        decoding="async"
        loading="lazy"
        src={birdsGif}
        alt="Background"
        style={styles.bgImage}
        draggable={false}
      />
      <svg
        ref={svgRef}
        viewBox={`0 0 ${svgWidth} ${svgHeight}`}
        preserveAspectRatio="none"
        style={styles.svg}
      ></svg>
      <div style={styles.clock} aria-label="Morse Code Clock">
        {digits.map((digit, i) => (
          <div key={i} style={styles.digitBox} aria-live="polite">
            <span style={styles.digitText(changingIndices.has(i))}>
              {digit}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MorseClock;

import React, { useEffect, useRef } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import twentyFont from '@/assets/fonts/2025/25-06-28-twenty.otf';

const Clock24: React.FC = () => {
  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'twenty',
      fontUrl: twentyFont,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  const hourRef = useRef();
  const minuteRef = useRef();
  const secondRef = useRef();

  // Font loading handled by useMultipleFontLoader

  useEffect(() => {
    const updateClock: React.FC = () => {
      const now = new Date();
      const h = now.getHours();
      const m = now.getMinutes();
      const s = now.getSeconds();
      const ms = now.getMilliseconds();

      const hourDeg = ((h % 24) + m / 60 + s / 3600) * 15;
      const minuteDeg = (m + s / 60) * 6;
      const secondDeg = (s + ms / 1000) * 6;

      if (hourRef.current)
        hourRef.current.style.transform = `translateX(-50%) rotate(${hourDeg}deg)`;
      if (minuteRef.current)
        minuteRef.current.style.transform = `translateX(-50%) rotate(${minuteDeg}deg)`;
      if (secondRef.current)
        secondRef.current.style.transform = `translateX(-50%) rotate(${secondDeg}deg)`;

      requestAnimationFrame(updateClock);
    };

    requestAnimationFrame(updateClock);
  }, []);

  const pieSections = Array.from({ length: 24 }, (_, i) => {
    const angle = (i / 24) * 360;
    return (
      <div
        key={`pie-${i}`}
        style={{
          position: 'absolute',
          width: '100%',
          height: '100%',
          clipPath: 'polygon(50% 50%, 50% 0%, 100% 0%)',
          transform: `rotate(${angle}deg)`,
          transformOrigin: '50% 50%',
          background: i % 2 === 1 ? 'rgba(1, 24, 24, 0.2)' : 'transparent',
        }}
      />
    );
  });

  const numbers = Array.from({ length: 24 }, (_, i) => {
    const hour = i % 24 || 24;
    const angle = (i / 24) * 360;
    const radius = 42;
    const x = 50 + radius * Math.sin((angle * Math.PI) / 180);
    const y = 50 - radius * Math.cos((angle * Math.PI) / 180);
    const isEven = hour % 2 === 0;

    return (
      <div
        key={`num-${hour}`}
        style={{
          position: 'absolute',
          fontSize: '6rem',
          fontFamily: 'twenty, sans-serif',
          left: `${x}%`,
          top: `${y}%`,
          transform: `translate(-50%, -50%) rotate(${angle}deg)`,
          color:
            hour === 24
              ? 'red'
              : isEven
                ? 'rgb(9, 9, 9)'
                : 'rgb(253, 249, 249)',
          textAlign: 'center',
        }}
      >
        {hour}
      </div>
    );
  });

  return (
    <div
      style={{
        margin: 0,
        height: '100dvh',
        width: '100vw',
        backgroundColor: 'rgb(161, 161, 160)',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
      }}
    >
      <div
        style={{
          position: 'relative',
          width: '100vmin',
          height: '100vmin',
          borderRadius: '50%',
          overflow: 'hidden',
          fontFamily: 'twenty, sans-serif',
        }}
      >
        {pieSections}
        {numbers}
        <div
          ref={hourRef}
          style={{
            zIndex: 9,
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            transformOrigin: 'bottom center',
            transform: 'translateX(-50%) rotate(0deg)',
            width: '6.8%',
            height: '20%',
            background:
              'repeating-linear-gradient(to bottom, black, black 4.167%, white 4.167%, white 8.333%)',
          }}
        />
        <div
          ref={minuteRef}
          style={{
            zIndex: 9,
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            transformOrigin: 'bottom center',
            transform: 'translateX(-50%) rotate(0deg)',
            width: '3.11%',
            height: '40%',
            background:
              'repeating-linear-gradient(to bottom, black, black 4.167%, white 4.167%, white 8.333%)',
          }}
        />
        <div
          ref={secondRef}
          style={{
            zIndex: 9,
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            transformOrigin: 'bottom center',
            transform: 'translateX(-50%) rotate(0deg)',
            width: '1.7%',
            height: '50%',
            background:
              'repeating-linear-gradient(to bottom, black, black 4.167%, white 4.167%, white 8.333%)',
          }}
        />
        <div
          style={{
            position: 'absolute',
            width: '2%',
            height: '2%',
            background: 'rgb(237, 7, 15)',
            borderRadius: '50%',
            top: '49%',
            left: '49%',
            zIndex: 10,
          }}
        />
      </div>
    </div>
  );
};

export default Clock24;

import React, { useEffect, useState } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import stretchFont from '@/assets/fonts/2025/25-06-29-stretch.ttf';

const StretchClock: React.FC = () => {
  const [time, setTime] = useState<any>({ hours: '', minutes: '', seconds: '' });

  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'stretch',
      fontUrl: stretchFont,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  // Font loading handled by useMultipleFontLoader

  useEffect(() => {
    const updateClock: React.FC = () => {
      const now = new Date();
      let hours = now.getHours() % 12 || 12;
      const minutes = now.getMinutes().toString().padStart(2, '0');
      const seconds = now.getSeconds();

      setTime((prev) => ({
        hours: prev.hours !== hours.toString() ? hours.toString() : prev.hours,
        minutes: prev.minutes !== minutes ? minutes : prev.minutes,
        seconds:
          prev.seconds !== seconds.toString()
            ? seconds.toString()
            : prev.seconds,
      }));
    };

    updateClock();
    const interval = setInterval(updateClock, 1000);
    return () => clearInterval(interval);
  }, []);

  const clockStyle = {
    height: '100dvh',
    width: '100vw',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    backgroundImage:
      'repeating-linear-gradient(335deg, #07bb4f 0, #e51a8a 0.2px, transparent 0, transparent 50%)',
    backgroundSize: '1.1vw 1.1vw',
    backgroundColor: '#bbcdc4',
    position: 'relative',
    fontSize: '4rem',
  };

  const baseTimeUnitStyle = (color, opacity, zIndex) => ({
    fontFamily: 'stretch',
    position: 'absolute',
    width: '100%',
    height: '100%',
    fontSize: '7rem',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    lineHeight: 1,
    textAlign: 'center',
    overflow: 'hidden',
    margin: 0,
    padding: 0,
    color,
    opacity,
    zIndex,
  });

  const spanStyle = {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    transform: 'scale(3.5, 2) skew(30deg)',
    width: '100%',
    height: '100%',
    lineHeight: 1,
  };

  return (
    <div style={clockStyle}>
      <div style={baseTimeUnitStyle('#090213', 1, 1)}>
        <span key={time.hours} style={spanStyle} className="morph">
          {time.hours}
        </span>
      </div>
      <div style={baseTimeUnitStyle('#76f705', 0.8, 2)}>
        <span key={time.minutes} style={spanStyle} className="morph">
          {time.minutes}
        </span>
      </div>
      <div style={baseTimeUnitStyle('#eefa03', 0.6, 3)}>
        <span key={time.seconds} style={spanStyle} className="morph">
          {time.seconds}
        </span>
      </div>
      <style>{`
        @keyframes morph {
          0% {
            transform: scale(3.5, 2) skew(40deg) rotateX(0deg);
            opacity: 1;
          }
          50% {
            transform: scale(3.0, 1.5) skew(20deg) rotateX(45deg);
            opacity: 0.5;
          }
          100% {
            transform: scale(3.5, 2) skew(30deg) rotateX(0deg);
            opacity: 1;
          }
        }

        .morph {
          animation: morph 0.5s ease-in-out;
        }
      `}</style>
    </div>
  );
};

export default StretchClock;

