import React, { useEffect, useState, useRef, useCallback, useMemo } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import kalFont from '@/assets/fonts/2025/25-07-04-kal.otf';
import bgImage from '@/assets/images/2025/25-07/25-07-04/7ZAx.webp';

/** * CONFIGURATION 
 * Defined outside to prevent re-allocation on every frame
 */
const SEGMENTS = 12;
const COLORS = [
  '#ff0040', '#045DF7FF', '#F9D108FF', '#00ff00',
  '#FC7B02FF', '#ff00ff', '#00bfff', '#ffffff',
  '#D0FF00FF', '#C12FFBFF', '#FAA404FF', '#12F5DBFF',
];

const Clock: React.FC = () => {
  const [time, setTime] = useState(new Date());
  const requestRef = useRef<number | null>(null);

  // 1. Font Loading Logic
  const fontConfigs = useMemo(() => [
    {
      fontFamily: 'kal',
      fontUrl: kalFont,
      options: { weight: 'normal', style: 'normal' }
    }
  ], []);

  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  // 2. Optimized Animation Loop
  const animate = useCallback(() => {
    setTime(new Date());
    requestRef.current = requestAnimationFrame(animate);
  }, []);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [animate]);

  // 3. Loading State Guard
  if (!fontsLoaded) {
    return (
      <div style={loadingOverlayStyle}>
        Initializing Synchronicity...
      </div>
    );
  }

  // 4. Time Formatting
  const h = time.getHours();
  const hourText = (h % 12 || 12).toString().padStart(2, '0');
  const minuteText = time.getMinutes().toString().padStart(2, '0');
  const secondText = time.getSeconds().toString().padStart(2, '0');
  const ampm = h >= 12 ? 'PM' : 'AM';
  const s = time.getSeconds();

  // 5. Segment Rendering Logic
  const renderRingSegments = (offset: number) => {
    return Array.from({ length: SEGMENTS }).map((_, i) => {
      const angle = i * (360 / SEGMENTS);
      const colorIndex = (i + s + offset) % COLORS.length;

      return (
        <React.Fragment key={i}>
          <div
            className="segment hour"
            style={{
              transform: `rotate(${angle}deg) translate(30vmin)`,
              color: COLORS[(colorIndex + 2) % COLORS.length],
            }}
          >
            {hourText}
          </div>
          <div
            className="segment minute"
            style={{
              transform: `rotate(${angle}deg) translate(20vmin)`,
              color: COLORS[(colorIndex + 4) % COLORS.length],
            }}
          >
            {minuteText}
          </div>
          <div
            className="segment second"
            style={{
              transform: `rotate(${angle}deg) translate(10vmin)`,
              color: COLORS[(colorIndex + 6) % COLORS.length],
            }}
          >
            {secondText}
          </div>
          <div
            className="segment ampm"
            style={{
              transform: `rotate(${angle}deg) translate(5vmin)`,
              color: COLORS[(colorIndex + 8) % COLORS.length],
            }}
          >
            {ampm}
          </div>
        </React.Fragment>
      );
    });
  };

  return (
    <div style={containerStyle}>
      {/* Background Image Layer */}
      <img 
        decoding="async" 
        src={bgImage} 
        alt="background" 
        style={bgStyle} 
      />



      {/* Clock Layers */}
      <div className="kaleidoscope spin-cw">{renderRingSegments(0)}</div>
      <div className="kaleidoscope spin-ccw">{renderRingSegments(6)}</div>

      <style>{`
        @keyframes spin-cw { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        @keyframes spin-ccw { from { transform: rotate(360deg); } to { transform: rotate(0deg); } }

        .kaleidoscope { 
          font-family: 'kal', sans-serif; 
          position: absolute; 
          inset: 0; 
          display: flex; 
          justify-content: center; 
          align-items: center; 
          z-index: 2; 
          pointer-events: none;
          perspective: 1000px;
        }

        .spin-cw { animation: spin-cw 60s linear infinite; opacity: 0.8; }
        .spin-ccw { animation: spin-ccw 120s linear infinite; opacity: 0.5; filter: blur(1px); }

        .segment { 
          position: absolute; 
          font-weight: 900; 
          mix-blend-mode: screen; 
          transition: color 0.8s ease, transform 0.5s ease-out; 
          font-size: 5rem; 
          white-space: nowrap;
          will-change: transform, color;
        }

        .minute { font-size: 3rem; opacity: 0.8; }
        .second { font-size: 1.5rem; opacity: 0.6; }
        .ampm { font-size: 0.7rem; letter-spacing: 1px; }

        @media (max-width: 768px) {
          .segment { font-size: 3rem; }
          .minute { font-size: 1.8rem; }
          .second { font-size: 1rem; }
        }
      `}</style>
    </div>
  );
};

/**
 * STYLES
 */
const containerStyle: React.CSSProperties = {
  margin: 0,
  padding: 0,
  background: 'black',
  height: '100dvh',
  width: '100vw',
  overflow: 'hidden',
  position: 'relative',
};

const bgStyle: React.CSSProperties = {
  position: 'fixed',
  top: 0,
  left: 0,
  width: '100vw',
  height: '100dvh',
  objectFit: 'cover',
  filter: 'brightness(180%) saturate(200%) hue-rotate(-190deg) blur(2px)',
  zIndex: 1,
  pointerEvents: 'none',
};

const headerStyle: React.CSSProperties = {
  position: 'absolute',
  top: '15px',
  left: '50%',
  transform: 'translateX(-50%)',
  width: '90%',
  display: 'flex',
  color: 'rgba(255,255,255,0.4)',
  zIndex: 6,
  fontSize: '0.8rem',
  fontFamily: 'monospace',
  borderTop: '1px solid rgba(255,255,255,0.1)',
  paddingTop: '5px',
  pointerEvents: 'none',
};

const loadingOverlayStyle: React.CSSProperties = {
  background: 'black',
  height: '100dvh',
  width: '100vw',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  color: '#444',
  fontFamily: 'monospace',
  letterSpacing: '2px',
};

export default Clock;

import React, { useEffect, useRef, useState } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import vegasFontUrl from '@/assets/fonts/2025/25-07-05-vegas.ttf';

const VegasClock: React.FC = () => {
  const hour1Ref = useRef(null);
  const hour2Ref = useRef(null);
  const minute1Ref = useRef(null);
  const minute2Ref = useRef(null);
  const second1Ref = useRef(null);
  const second2Ref = useRef(null);
  const playerRef = useRef(null);
  const playerContainerRef = useRef(null);

  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'vegas',
      fontUrl: vegasFontUrl,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  // Initialize YouTube IFrame API
  useEffect(() => {
    const scriptId = 'youtube-iframe-api-script';
    let scriptTag = document.getElementById(scriptId) as HTMLScriptElement | null;

    if (!window.YT && !scriptTag) {
      scriptTag = document.createElement('script');
      scriptTag.id = scriptId;
      scriptTag.src = 'https://www.youtube.com/iframe_api';
      document.body.appendChild(scriptTag);
    }

    window.onYouTubeIframeAPIReady = () => {
      if (!playerRef.current && playerContainerRef.current) {
        playerRef.current = new window.YT.Player(playerContainerRef.current, {
          videoId: 'jtvmwjzZY0c',
          playerVars: {
            autoplay: 1,
            mute: 1,
            controls: 0,
            modestbranding: 1,
            loop: 1,
            playlist: 'jtvmwjzZY0c',
            playsinline: 1,
          },
          events: { onReady: (event) => event.target.playVideo() },
        });
      }
    };

    // Cleanup function
    return () => {
      if (playerRef.current) {
        try {
          playerRef.current.destroy();
        } catch (e) {
          // Player might already be destroyed
        }
        playerRef.current = null;
      }
      window.onYouTubeIframeAPIReady = null;
    };
  }, []);

  // Clock logic
  useEffect(() => {
    if (!fontsLoaded) return;

    const refs = {
      hour1: hour1Ref.current,
      hour2: hour2Ref.current,
      minute1: minute1Ref.current,
      minute2: minute2Ref.current,
      second1: second1Ref.current,
      second2: second2Ref.current,
    };

    const flickerClasses = [
      'flicker-015-a',
      'flicker-015-b',
      'flicker-015-c',
      'flicker-03-a',
      'flicker-03-b',
      'flicker-03-c',
    ];

    const getRandomInt = (min, max) =>
      Math.floor(Math.random() * (max - min + 1)) + min;

    const setFlicker = (elementId, minInterval, maxInterval) => {
      const element = refs[elementId];
      if (!element) return;
      flickerClasses.forEach((cls) => element.classList.remove(cls));
      const flickerClass =
        flickerClasses[Math.floor(Math.random() * flickerClasses.length)];
      element.classList.add(flickerClass);
      const duration = flickerClass.includes('015') ? 150 : 300;
      setTimeout(() => element.classList.remove(flickerClass), duration);
      setTimeout(
        () => setFlicker(elementId, minInterval, maxInterval),
        getRandomInt(minInterval, maxInterval),
      );
    };

    const updateClock: React.FC = () => {
      const now = new Date();
      let hours = now.getHours();
      const minutes = String(now.getMinutes()).padStart(2, '0');
      const seconds = String(now.getSeconds()).padStart(2, '0');
      hours = hours % 12 || 12;
      const hourStr = String(hours).padStart(2, '0');
      hour1Ref.current.textContent = hourStr[0];
      hour2Ref.current.textContent = hourStr[1];
      minute1Ref.current.textContent = minutes[0];
      minute2Ref.current.textContent = minutes[1];
      second1Ref.current.textContent = seconds[0];
      second2Ref.current.textContent = seconds[1];
    };

    updateClock();
    const interval = setInterval(updateClock, 1000);

    setTimeout(() => setFlicker('minute2', 1000, 3000), 2000);
    setTimeout(() => setFlicker('hour1', 4000, 12000), 2000);

    return () => clearInterval(interval);
  }, [fontsLoaded]);

  const iframeStyle = {
    position: 'fixed',
    top: 0,
    left: 0,
    width: '100vw',
    height: '100vh',
    zIndex: -1,
    pointerEvents: 'none',
  };

  const wrapperStyle = {
    position: 'fixed',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    width: 'max-content',
    zIndex: 10,
  };

  const clockContainerStyle = {
    display: fontsLoaded ? 'flex' : 'none', // hide until ready
    flexDirection: 'row',
    gap: '1vmin',
    alignItems: 'center',
    whiteSpace: 'nowrap',
    overflow: 'hidden',
  };

  const digitGroupStyle = {
    fontFamily: 'vegas, sans-serif',
    display: 'flex',
    gap: '0.1vmin',
  };

  const digitBoxStyle = {
    color: '#edcb0b',
    textShadow:
      '#c406fe 0 0.2rem, #f84802 0 -0.2rem, #48d9e9 0.2rem 0, #f84802 -0.2rem 0',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    fontSize: '3.5rem',
    width: '2.2rem',
    height: '4rem',
    textAlign: 'center',
    boxSizing: 'border-box',
    zIndex: 19,
  };

  return (
    <>
      <style>{`
        @keyframes flicker015a { 0%, 50%, 100% { opacity: 1; } 25%, 75% { opacity: 0; } }
        @keyframes flicker015b { 0%, 33%, 66% { opacity: 1; } 16%, 50%, 83% { opacity: 0; } }
        @keyframes flicker015c { 0%, 40% { opacity: 1; } 20%, 60%, 80% { opacity: 0; } }
        @keyframes flicker03a  { 0%, 50%, 100% { opacity: 1; } 25%, 75% { opacity: 0; } }
        @keyframes flicker03b  { 0%, 20%, 60% { opacity: 1; } 10%, 40%, 80% { opacity: 0; } }
        @keyframes flicker03c  { 0%, 33%, 66% { opacity: 1; } 16%, 50%, 83% { opacity: 0; } }

        .flicker-015-a { animation: flicker015a 0.15s 1; }
        .flicker-015-b { animation: flicker015b 0.15s 1; }
        .flicker-015-c { animation: flicker015c 0.15s 1; }
        .flicker-03-a  { animation: flicker03a 0.3s 1; }
        .flicker-03-b  { animation: flicker03b 0.3s 1; }
        .flicker-03-c  { animation: flicker03c 0.3s 1; }
      `}</style>

      {/* YouTube video as background */}
      <div ref={playerContainerRef} style={iframeStyle}></div>

      {/* Clock */}
      <div style={wrapperStyle}>
        <div style={clockContainerStyle}>
          <div style={digitGroupStyle}>
            <div ref={hour1Ref} style={digitBoxStyle}></div>
            <div ref={hour2Ref} style={digitBoxStyle}></div>
          </div>
          <div style={digitGroupStyle}>
            <div ref={minute1Ref} style={digitBoxStyle}></div>
            <div ref={minute2Ref} style={digitBoxStyle}></div>
          </div>
          <div style={digitGroupStyle}>
            <div ref={second1Ref} style={digitBoxStyle}></div>
            <div ref={second2Ref} style={digitBoxStyle}></div>
          </div>
        </div>
      </div>
    </>
  );
};

export default VegasClock;

