    width: '100vw',
    display: 'flex',
    justifyContent: 'flex-start',
    alignItems: 'flex-start',
    background: '#7E8280FF',
    fontFamily: 'suv, sans-serif',
    padding: '0vw',
    boxSizing: 'border-box',
    overflow: 'hidden',
