  const clockStyle = {
    position: 'fixed',
    left: '200px',
    top: '51vh',
    transform: 'translateY(-50%)',
    display: 'flex',
    textAlign: 'left',
    zIndex: 2,
    lineHeight: 1,
    gap: '0rem',
  };

  const spanStyle = {
    fontFamily: 'suv, sans-serif',
    display: 'block',
    fontSize: '1.1rem',
    color: 'transparent',
    backgroundImage: `
      linear-gradient(
        145deg,
        #ffffff 0%,
        #d0d0d0 25%,
        #b0b0b0 50%,
        #eeeeee 70%,
        #999999 100%
      )
    `,
