    backgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    textShadow: `
      0.05rem 0.05rem 0.1rem rgba(255, 255, 255, 0.8),
      -0.05rem -0.05rem 0.1rem rgba(0, 0, 0, 0.4),
