      <div style={bgImageStyle} />
      <div id="clock" style={clockStyle}>
        <span style={spanStyle}>{time.h}</span>
        <span style={spanStyle}>{time.m}</span>
        <span style={spanStyle}>{time.ampm}</span>
      </div>
    </div>
  );
};

export default Clock;

