import React, { useEffect } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import fibFont from '@/assets/fonts/2025/25-07-12-fib.otf';
import fibImage from '@/assets/images/2025/25-07/25-07-12/fib.gif';

const FibonacciClock: React.FC = () => {
  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'fib',
      fontUrl: fibFont,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  useEffect(() => {
    const updateClock: React.FC = () => {
      const now = new Date();
      const seconds = now.getSeconds();
      const minutes = now.getMinutes();
      const hours = now.getHours() % 12;

      const secondDeg = (seconds / 60) * 360;
      const minuteDeg = (minutes / 60) * 360 + (seconds / 60) * 6;
      const hourDeg = (hours / 12) * 360 + (minutes / 60) * 30;

      document.querySelector('.second-hand').style.transform =
        `rotate(${secondDeg}deg)`;
      document.querySelector('.minute-hand').style.transform =
        `rotate(${minuteDeg}deg)`;
      document.querySelector('.hour-hand').style.transform =
        `rotate(${hourDeg}deg)`;
    };

    updateClock();
    const interval = setInterval(updateClock, 1000);
    return () => clearInterval(interval);
  }, []);

  const fontFace = `
    /* Font loading handled by useMultipleFontLoader */
  `;

  const numbers = [
    { angle: 30, value: '0' },
    { angle: 60, value: '1' },
    { angle: 90, value: '1' },
    { angle: 120, value: '2' },
    { angle: 150, value: '3' },
    { angle: 180, value: '5' },
    { angle: 210, value: '8' },
    { angle: 240, value: '13' },
    { angle: 270, value: '21' },
    { angle: 300, value: '34' },
    { angle: 330, value: '55' },
    { angle: 0, value: '89' },
  ];

  return (
    <div
      style={{
        margin: 0,
        height: '100dvh',
        width: '100vw',
        backgroundColor: '#cac7c7',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        overflow: 'hidden',
        position: 'relative',
      }}
    >
      <style>{fontFace}</style>
      <img
        decoding="async"
        loading="lazy"
        src={fibImage}
        alt="background"
        style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          width: '150vmax',
          height: '150vmax',
          objectFit: 'cover',
          filter: 'contrast(0.3) brightness(1.6) saturate(0.2)',
          zIndex: 1,
          animation: 'slow-rotate 60s linear infinite',
          transformOrigin: 'center center',
          transform: 'translate(-50%, -50%) scale(-1, -1)',
        }}
      />
      <div
        style={{
          width: '40vh',
          height: '40vh',
          borderRadius: '50%',
          position: 'relative',
          zIndex: 3,
        }}
      >
        {numbers.map(({ angle, value }, i) => (
          <div
            key={i}
            className="number"
            style={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform: `rotate(${angle}deg)`,
              transformOrigin: 'center',
              fontFamily: 'fib',
              fontSize: '1.7rem',
              color: '#171715',
              textShadow: '0.15rem 0.04rem #f1c72f',
            }}
          >
            <div
              style={{
                position: 'absolute',
                transform: 'translate(-50%, -21vh)',
              }}
            >
              {value}
            </div>
          </div>
        ))}

        <div
          className="hand hour-hand"
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            width: '0.7vh',
            height: '6.5vh',
            backgroundColor: '#191918',
            transformOrigin: 'bottom',
            borderRadius: '0.3vh',
            filter: 'drop-shadow(0.15rem 0.04rem rgb(231, 196, 23))',
          }}
        />
        <div
          className="hand minute-hand"
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            width: '0.5vh',
            height: '13vh',
            backgroundColor: '#191918',
            transformOrigin: 'bottom',
            borderRadius: '0.25vh',
            filter: 'drop-shadow(0.15rem 0.04rem rgb(231, 196, 23))',
          }}
        />
        <div
          className="hand second-hand"
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            width: '0.2vh',
            height: '8vh',
            backgroundColor: 'transparent',
            transformOrigin: 'bottom',
            borderRadius: '0.2vh',
            filter: 'drop-shadow(0.15rem 0.04rem rgb(231, 196, 23))',
          }}
        />
        <div
          style={{
            width: '2.6vh',
            height: '2.6vh',
            borderRadius: '50%',
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            opacity: 0.1,
            backgroundColor: '#000',
          }}
        ></div>
      </div>
      <style>{`
        @keyframes slow-rotate {
          0% { transform: translate(-50%, -50%) scale(-1, -1) rotate(0deg); }
          100% { transform: translate(-50%, -50%) scale(-1, -1) rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default FibonacciClock;

import React, { useEffect, useRef } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import rorFontUrl from '@/assets/fonts/2025/25-07-13-ror.ttf';

const RorschachClock: React.FC = () => {
  const clockRef = useRef();
  const mirrorRef = useRef();

  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'ror',
      fontUrl: rorFontUrl,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  const getRandomFontSize = (min = 5, max = 14) => {
    return (Math.random() * (max - min) + min).toFixed(2) + 'vh';
  };

  const getRandomAmpmSize = (min = 2, max = 4) => {
    return (Math.random() * (max - min) + min).toFixed(2) + 'vh';
  };

  const wrapDigits = (timeStr, ampm) => {
    const digitsHtml = timeStr
      .split('')
      .map(
        (char, i) =>
          `<span style="font-size: ${getRandomFontSize()};">${char}</span>`,
      )
      .join('');

    const ampmHtml = ampm
      .split('')
      .map(
        (char) =>
          `<span class="ampm" style="font-size: ${getRandomAmpmSize()};">${char}</span>`,
      )
      .join('');

    return digitsHtml + ampmHtml;
  };

  const formatTime = (date) => {
    let hours = date.getHours();
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12 || 12;
    return {
      timeString: `${hours}:${minutes}`,
      ampm,
    };
  };

  const fadeUpdateClock: React.FC = () => {
    if (!clockRef.current || !mirrorRef.current) return;

    clockRef.current.style.opacity = 0;
    mirrorRef.current.style.opacity = 0;

    setTimeout(() => {
      const now = new Date();
      const { timeString, ampm } = formatTime(now);
      const html = wrapDigits(timeString, ampm);

      clockRef.current.innerHTML = html;
      mirrorRef.current.innerHTML = html;

      clockRef.current.style.opacity = 1;
      mirrorRef.current.style.opacity = 1;
    }, 1500);
  };

  useEffect(() => {
    fadeUpdateClock();
    const interval = setInterval(fadeUpdateClock, 5000);
    return () => clearInterval(interval);
  }, []);

  const containerStyle = {
    margin: 0,
    height: '100dvh',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#f5f0f0',
    position: 'relative',
    fontFamily: 'ror, monospace, sans-serif',
  };

  const clockContainerStyle = {
    position: 'absolute',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
  };

  const clockStyle = (rotate, flip) => ({
    fontWeight: 'bold',
    color: '#333',
    whiteSpace: 'nowrap',
    display: 'flex',
    padding: 0,
    margin: 0,
    opacity: 1,
    transition: 'opacity 1.5s ease',
    transform: `rotate(${rotate}) ${flip ? 'scaleX(-1)' : ''}`,
  });

  return (
    <div style={containerStyle}>
      <div style={{ ...clockContainerStyle, left: 'calc(50% - 20vw)' }}>
        <div
          ref={mirrorRef}
          style={clockStyle('-90deg', true)}
          id="mirrorClock"
        ></div>
      </div>

      <div style={{ ...clockContainerStyle, right: 'calc(50% - 20vw)' }}>
        <div ref={clockRef} style={clockStyle('90deg', false)} id="clock"></div>
      </div>
    </div>
  );
};

export default RorschachClock;

