import xrayFontUrl from '@/assets/fonts/2025/25-07-18-xray.ttf';

const HospitalClock: React.FC = () => {
  const [time, setTime] = useState<any>('');

  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'xray',
      fontUrl: xrayFontUrl,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  useEffect(() => {
    const updateClock: React.FC = () => {
      const now = new Date();
      const h = String(now.getHours()).padStart(2, '0');
      const m = String(now.getMinutes()).padStart(2, '0');
      const s = String(now.getSeconds()).padStart(2, '0');
      const ms = String(now.getMilliseconds()).padStart(3, '0').slice(0, 2);
      setTime(`${h}:${m}:${s}.${ms}`);
    };

    const interval = setInterval(updateClock, 50);
    updateClock();
    return () => clearInterval(interval);
  }, []);

  return (
    <div style={styles.body}>
      <div style={styles.machine}>
        <div style={{ ...styles.screen, backgroundImage: `url(${bgImage})` }}>
          <div style={styles.flickerOverlay} />
          <div style={styles.clock}>
            {time.split('').map((char, i) => (
              <span key={i} style={styles.digit}>
                {char}
              </span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

