import React, { useEffect, useState } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import cunFont from '@/assets/fonts/2025/25-07-19-cun.ttf';
import bgOverlay from '@/assets/images/2025/25-07/25-07-19/cun1.webp';

const CuneiformClock: React.FC = () => {
  const [time, setTime] = useState<any>('');

  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'cunei-cun',
      fontUrl: cunFont,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  useEffect(() => {
    const updateClock: React.FC = () => {
      const now = new Date();
      let hours = now.getHours() % 12 || 12;
      const minutes = String(now.getMinutes()).padStart(2, '0');
      setTime(`${hours}:${minutes}`);
    };

    updateClock();
    const interval = setInterval(updateClock, 1000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div
      className="cunei-wrapper"
      style={{
        height: '100dvh',
        width: '100vw',
        backgroundColor: '#062bb4',
        margin: 0,
        overflow: 'hidden',
        fontFamily: 'cunei-cun, sans-serif',
        position: 'relative',
      }}
    >
      <style>{`
        /* Font loading handled by useMultipleFontLoader */

        .cunei-wrapper {
          font-size: 2vh;
        }

        .cunei-container {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%);
          z-index: 10;
          text-align: center;
          padding: 1rem;
        }

        .cunei-clock {
          font-size: clamp(3rem, 10vw, 12rem);
          background: linear-gradient(to bottom,
            #0b0b0a 1%,
            #f2b02c 4%,
            #0b0b0a 9%,
            #cfc09f 27%,
            #ffecb3 40%,
            #7c560a 81%,
            #e3d9c5 93%);
