          z-index: 13;
          transform: translate(-50%, -50%) rotate(calc(30deg * var(--i))) translateY(-42vmin) rotate(calc(-30deg * var(--i)));
        }




      `}</style>

      <div className="container">
        <div className="spin-wrapper">
          <div className="left half">
            <img
              decoding="async"
