import React, { useEffect, useRef, useState } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import bg1 from '@/assets/images/2025/25-07/25-07-26/tum.gif';
import bg2 from '@/assets/images/2025/25-07/25-07-26/tum2.gif';
import myFontUrl from '@/assets/fonts/2025/25-07-26-sec.ttf';

const COLORS = ['#CB0BEDFF', '#25E90CFF', '#F58E0FFF'];

const getRandomDifferentColor = (currentColor, palette) => {
  const newPalette = palette.filter((c) => c !== currentColor);
  return newPalette[Math.floor(Math.random() * newPalette.length)];
};

const PrimaryColorClock: React.FC = () => {
  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'MyFont',
      fontUrl: myFontUrl,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  const secondHandRef = useRef(null);
  const minHandRef = useRef(null);
  const hourHandRef = useRef(null);

  const [numberColors, setNumberColors] = useState(() =>
    Array.from(
      { length: 12 },
      () => COLORS[Math.floor(Math.random() * COLORS.length)],
    ),
  );

  const [handColors, setHandColors] = useState<any>({
    second: COLORS[0],
    minute: COLORS[1],
    hour: COLORS[2],
  });

  // Clock hand movement - smooth seconds
  useEffect(() => {
    const update: React.FC = () => {
      const now = new Date();

      const ms = now.getMilliseconds();
      const seconds = now.getSeconds() + ms / 1000;
      const minutes = now.getMinutes() + seconds / 60;
      const hours = now.getHours() + minutes / 60;

      const secondsDegrees = (seconds / 60) * 360 + 90;
      const minsDegrees = (minutes / 60) * 360 + 90;
      const hourDegrees = (hours / 12) * 360 + 90;

      if (secondHandRef.current)
        secondHandRef.current.style.transform = `rotate(${secondsDegrees}deg)`;
      if (minHandRef.current)
        minHandRef.current.style.transform = `rotate(${minsDegrees}deg)`;
      if (hourHandRef.current)
        hourHandRef.current.style.transform = `rotate(${hourDegrees}deg)`;

      requestAnimationFrame(update);
    };

    update();
  }, []);

  // Color changer
  useEffect(() => {
    const colorInterval = setInterval(() => {
      setNumberColors((prev) =>
        prev.map((c) => getRandomDifferentColor(c, COLORS)),
      );

      setHandColors((prev) => ({
        second: getRandomDifferentColor(prev.second, COLORS),
        minute: getRandomDifferentColor(prev.minute, COLORS),
        hour: getRandomDifferentColor(prev.hour, COLORS),
      }));
    }, 1000);

    return () => clearInterval(colorInterval);
  }, []);

  const fontFace = `
    /* Font loading handled by useMultipleFontLoader */
  `;

  const styleTag = <style>{fontFace}</style>;

  const containerStyle = {
    height: '100dvh',
    width: '100vw',
    margin: 0,
    overflow: 'hidden',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: 'rgb(234, 119, 10)',
    position: 'relative',
    fontFamily: 'MyFont, sans-serif',
  };

  const bgStyle1 = {
    position: 'fixed',
    top: 0,
    left: 0,
    width: '150vw',
    height: '150vh',
    backgroundImage: `url(${bg1})`,
    backgroundRepeat: 'repeat',
    backgroundSize: '59vh 12vw',
    backgroundAttachment: 'fixed',
    zIndex: 1,
    pointerEvents: 'none',
    opacity: 0.8,
    filter: 'hue-rotate(-320deg)',
    transform: 'rotate(179deg)',
  };

  const bgStyle2 = {
    ...bgStyle1,
    transform: 'rotate(181deg)',
  };

  const centerContainerStyle = {
    position: 'fixed',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    zIndex: 5,
  };

  const clockStyle = {
    width: '12rem',
    height: '12rem',
    borderRadius: '50%',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    position: 'relative',
  };

  const baseHandStyle = {
    position: 'absolute',
    top: '50%',
    right: '50%',
    transformOrigin: '100%',
    transition: 'background 0.5s ease',
  };

  const secondHandStyle = {
    ...baseHandStyle,
    height: '4vh',
    width: '400%',
    background: handColors.second,
    zIndex: 18,
  };

  const minHandStyle = {
    ...baseHandStyle,
    height: '9vh',
    width: '100%',
    background: handColors.minute,
    zIndex: 11,
  };

  const hourHandStyle = {
    ...baseHandStyle,
    height: '11vh',
    width: '72%',
    background: handColors.hour,
    zIndex: 18,
  };

  const numberStyle = (i) => {
    const angle = (i - 3) * (Math.PI / 6);
    const radius = 5.5;
    const x = radius * Math.cos(angle);
    const y = radius * Math.sin(angle);

    return {
      position: 'absolute',
      top: `calc(50% + ${y}rem)`,
      left: `calc(50% + ${x}rem)`,
      transform: 'translate(-50%, -50%)',
      fontSize: '3.2rem',
      fontWeight: 'bold',
      color: numberColors[i - 1],
      fontFamily: 'MyFont, sans-serif',
      zIndex: 19,
      transition: 'color 0.5s ease',
    };
  };

  return (
    <>
      {styleTag}
      <div style={containerStyle}>
        <div style={bgStyle1}></div>
        <div style={bgStyle2}></div>

        <div style={centerContainerStyle}>
          <div style={clockStyle}>
            {[...Array(12)].map((_, i) => (
              <div key={i + 1} style={numberStyle(i + 1)}>
