  return (
    <div style={wrapperStyle}>
      <div style={clockContainer}>
        {[...Array(12)].map((_, i) => (
          <div key={i} style={numberStyle(i + 1)}>
            {i + 1}
          </div>
        ))}
        <div style={hourHand}></div>
        <div style={minuteHand}></div>
        <div style={secondHand}></div>
        <div style={centerDot}></div>
      </div>
    </div>
  );
};

export default Clock;

