import { useState, useEffect, useMemo, useRef } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import { useClockTime } from '@/utils/hooks';
import bgImage from '@/assets/images/2025/25-08/25-08-04/shrub.jpeg'; // Your background image file
import myFont from '@/assets/fonts/2025/25-08-04-Tr.ttf'; // Your custom font file

const getRandomPosition = () => ({
  top: `${Math.random() * 80 + 10}%`,
  left: `${Math.random() * 80 + 10}%`,
});

const getRandomTilt = () => ({
  transform: `rotate(${Math.random() * 20 - 10}deg)`,
});

const DigitalClock: React.FC = () => {
  const time = useClockTime();
  const [fadeIndex, setFadeIndex] = useState<number>(0);
  const [fontLoaded, setFontLoaded] = useState(false);
  const componentId = useRef(`multi-clock-${Date.now()}`);

  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'Tr',
      fontUrl: myFont,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  // Update fontLoaded state when fontsLoaded changes
  useEffect(() => {
    setFontLoaded(fontsLoaded);
  }, [fontsLoaded]);

  // Font loading handled by useMultipleFontLoader

  const clocks = useMemo(
    () =>
      Array.from({ length: 10 }, () => ({
        position: getRandomPosition(),
        tilt: getRandomTilt(),
      })),
    [],
  );

  // Synchronize fade change with the centralized clock pulse
  useEffect(() => {
    // This ensures the transition happens exactly on the second tick
    setFadeIndex((i) => (i + 1) % clocks.length);
  }, [time, clocks.length]);

  const getOpacity = (i) => {
    const totalClocks = clocks.length;
    let diff = i - fadeIndex;
    if (diff < 0) diff += totalClocks;

    if (diff <= 5) {
      return diff / 5;
    } else {
      return 1 - (diff - 5) / 4;
    }
  };

  const hours = time.getHours() % 12 || 12;
  const minutes = time.getMinutes().toString().padStart(2, '0');

  return (
    <>
      {/* Font loading handled by useMultipleFontLoader */}

      <div
        style={{
          position: 'relative',
          width: '100vw',
          height: '100dvh',
          margin: 0,
          padding: 0,
          background: 'black',
          overflow: 'hidden',
        }}
      >
        <div
          style={{
            position: 'absolute',
            inset: 0,
            backgroundImage: `url(${bgImage})`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            filter: 'saturate(0.3) brightness(0.45) contrast(1.5)',
            zIndex: 0,
          }}
        />
      </div>

      {/* Clocks */}
      <div
        style={{
          position: 'absolute',
          inset: 0,
          overflow: 'hidden',
          zIndex: 10,
          pointerEvents: 'none',
          backgroundColor: 'transparent',
          fontFamily: fontLoaded ? 'Tr, Arial, sans-serif' : 'Arial, sans-serif',
        }}
      >
        {clocks.map(({ position, tilt }, index) => {
          const opacity = getOpacity(index);
          return (
            <time
              key={index}
              style={{
                position: 'absolute',
                display: 'flex',
                color: '#E9F2D7FF',
                fontSize: '1.0rem',
                transition: 'opacity 2s linear', // faster fade
                opacity,
                ...position,
                ...tilt,
                pointerEvents: 'none',
                textShadow: '0 0 5px rgba(0,0,0,0.7)',
                userSelect: 'none',
                whiteSpace: 'nowrap',
              }}
              aria-live="polite"
            >
              <span>{hours}</span>
              <span>{minutes}</span>
            </time>
          );
        })}
      </div>
    </>
  );
};

export default DigitalClock;

import React, { useEffect, useRef } from 'react';

const ClockGrid: React.FC = () => {
  const faceCanvasRef = useRef(null);
  const handsCanvasRef = useRef(null);
  const numRows = 10;
  const numCols = 10;

  const getClockSize: React.FC = () => {
    const maxWidthSize = window.innerWidth / numCols;
    const maxHeightSize = window.innerHeight / numRows;
    return Math.floor(Math.min(maxWidthSize, maxHeightSize)); // fits both directions
  };

  const drawClockFace = (ctx, x, y, radius) => {
    ctx.save();
    ctx.translate(x, y);
    ctx.beginPath();
    ctx.arc(0, 0, radius, 0, 2 * Math.PI);
    ctx.fillStyle = '#625A03FF';
    ctx.fill();
    ctx.strokeStyle = '#100101FF';
    ctx.lineWidth = 3;
    ctx.stroke();

    for (let num = 1; num <= 12; num++) {
      const angle = (num * Math.PI) / 6;
      ctx.rotate(angle);
      ctx.translate(0, -radius * 0.85);
      ctx.rotate(-angle);
      ctx.fillStyle = '#FAF8F8FF';
      ctx.font = `${radius * 0.7}px Georgia`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(num.toString(), 0, 0);
      ctx.rotate(angle);
      ctx.translate(0, radius * 0.85);
      ctx.rotate(-angle);
    }

    ctx.restore();
  };

  const drawHand = (ctx, pos, length, width, color) => {
    ctx.beginPath();
    ctx.lineWidth = width;
    ctx.lineCap = 'round';
    ctx.strokeStyle = color;
    ctx.rotate(pos);
    ctx.moveTo(0, 0);
    ctx.lineTo(0, -length);
    ctx.stroke();
    ctx.rotate(-pos);
  };

  useEffect(() => {
    const faceCanvas = faceCanvasRef.current;
    const handsCanvas = handsCanvasRef.current;
    const faceCtx = faceCanvas.getContext('2d');
    const handsCtx = handsCanvas.getContext('2d');

    let animationFrameId;
    let clockSize = getClockSize();
    let radius = clockSize / 2;
    let clocks = [];

    const drawFaces: React.FC = () => {
      faceCtx.clearRect(0, 0, faceCanvas.width, faceCanvas.height);

      const totalGridWidth = numCols * clockSize;
      const totalGridHeight = numRows * clockSize;
      const offsetX = (faceCanvas.width - totalGridWidth) / 2;
      const offsetY = (faceCanvas.height - totalGridHeight) / 2;

      clocks = [];
      for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
          const x = col * clockSize + radius + offsetX;
          const y = row * clockSize + radius + offsetY;
          clocks.push({ x, y, radius });
          drawClockFace(faceCtx, x, y, radius);
        }
      }
    };

    const draw: React.FC = () => {
      handsCtx.clearRect(0, 0, handsCanvas.width, handsCanvas.height);

      const currentTime = new Date();
      const hour = currentTime.getHours() % 12 || 12;
      const minute = currentTime.getMinutes();
      const second =
        currentTime.getSeconds() + currentTime.getMilliseconds() / 1000;

      const handLength = clockSize * 12; // proportional long hands

      clocks.forEach(({ x, y, radius }) => {
        handsCtx.save();
        handsCtx.translate(x, y);
        drawHand(
          handsCtx,
          (second * Math.PI) / 30,
          handLength,
          radius * 0.1,
          '#F90810FF',
        ); // Second
        drawHand(
          handsCtx,
          ((hour + minute / 60) * Math.PI) / 6,
          handLength,
          radius * 0.1,
          '#63FC11FF',
        ); // Hour
        drawHand(
          handsCtx,
          ((minute + second / 60) * Math.PI) / 30,
          handLength,
          radius * 0.1,
          '#893CF6FF',
        ); // Minute
        handsCtx.restore();
      });

      animationFrameId = requestAnimationFrame(draw);
    };

    const resizeCanvases: React.FC = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      faceCanvas.width = width;
      faceCanvas.height = height;
      handsCanvas.width = width;
      handsCanvas.height = height;

      clockSize = getClockSize();
      radius = clockSize / 2;

      drawFaces();
      draw();
    };

    window.addEventListener('resize', resizeCanvases);
    resizeCanvases();

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', resizeCanvases);
    };
  }, []);

  return (
    <div
      role="img"
      aria-label="Grid of analog clocks displaying the current time"
      style={{ position: 'relative', width: '100vw', height: '100vh' }}
    >
      <canvas
        ref={faceCanvasRef}
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100dvh',
          background: '#A9A5A5FF',
          zIndex: 1,
          display: 'block',
        }}
      />
      <canvas
        ref={handsCanvasRef}
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100d',
          pointerEvents: 'none',
          zIndex: 2,
          display: 'block',
        }}
      />
    </div>
  );
};

export default ClockGrid;

