import React, { useEffect, useRef } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import myFontUrl from '@/assets/fonts/2025/25-08-07-rope.ttf';
import backgroundImageUrl from '@/assets/images/2025/25-08/25-08-07/wes.webp';
import hourHandImageUrl from '@/assets/images/2025/25-08/25-08-07/ggg.gif';
import minuteHandImageUrl from '@/assets/images/2025/25-08/25-08-07/gun.gif';
import secondHandImageUrl from '@/assets/images/2025/25-08/25-08-07/gunn.gif';

const AnalogClock: React.FC = () => {
  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'MyClockFont',
      fontUrl: myFontUrl,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    // Load images
    const hourHandImage = new Image();
    hourHandImage.src = hourHandImageUrl;
    const minuteHandImage = new Image();
    minuteHandImage.src = minuteHandImageUrl;
    const secondHandImage = new Image();
    secondHandImage.src = secondHandImageUrl;

    // Font loading handled by useMultipleFontLoader
    const loadResources = Promise.all([
      new Promise((resolve) => {
        hourHandImage.onload = resolve;
      }),
      new Promise((resolve) => {
        minuteHandImage.onload = resolve;
      }),
      new Promise((resolve) => {
        secondHandImage.onload = resolve;
      }),
    ]);

    const pivots = { hour: 1, minute: 1, second: 1 };
    let dpr = window.devicePixelRatio || 1;

    const resizeCanvas: React.FC = () => {
      dpr = window.devicePixelRatio || 1;
      canvas.width = Math.round(window.innerWidth * dpr);
      canvas.height = Math.round(window.innerHeight * dpr);
      canvas.style.width = `${window.innerWidth}px`;
      canvas.style.height = `${window.innerHeight}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      drawClock();
    };

    const drawClock: React.FC = () => {
      if (!canvas) return;

      const now = new Date();
      const width = window.innerWidth;
      const height = window.innerHeight;
      const radius = Math.min(width, height) / 3.5;
      const centerX = width / 2;
      const centerY = height / 2;

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // --- Vignette overlay ---
      const vignette = ctx.createRadialGradient(
        centerX,
        centerY,
        radius * 1.1,
        centerX,
        centerY,
        Math.max(width, height) * 0.7,
      );
      vignette.addColorStop(0, 'rgba(0,0,0,0)');
      vignette.addColorStop(1, 'rgba(0,0,0,0.75)');
      ctx.fillStyle = vignette;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.save();
      ctx.translate(centerX, centerY);

      // --- Numbers with 3D bevel + inner gradient + tilt ---
      ctx.font = `${radius * 0.7}px MyClockFont`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      for (let num = 1; num <= 12; num++) {
        const angle = (num * Math.PI) / 6;
        const x = Math.cos(angle - Math.PI / 2) * (radius * 0.85);
        const y = Math.sin(angle - Math.PI / 2) * (radius * 0.85);

        ctx.save();
        ctx.translate(x, y);
        const tilt = ((num % 2 === 0 ? -1 : 1) * Math.PI) / 18;
        ctx.rotate(tilt);

        const depth = 6;

        // Beveled shadow + highlight layers
        for (let i = depth; i > 0; i--) {
          ctx.shadowColor = 'rgba(0,0,0,0.05)';
          ctx.shadowBlur = 2;
          ctx.fillStyle = `rgba(50,30,10,${0.3 / i})`;
          ctx.fillText(num.toString(), i, i);

          ctx.fillStyle = `rgba(255,255,255,${0.08 / i})`;
          ctx.fillText(num.toString(), -i, -i);
        }

        // Main front face with inner gradient
        const gradient = ctx.createLinearGradient(
          0,
          -radius * 0.35,
          0,
          radius * 0.35,
        );
        gradient.addColorStop(0, `rgba(255, 249, 230, 1)`);
        gradient.addColorStop(0.5, `rgba(220, 180, 120, 1)`);
        gradient.addColorStop(1, `rgba(150, 100, 50, 1)`);

        ctx.shadowColor = `rgba(0,0,0,0.2)`;
        ctx.shadowBlur = 12;
        ctx.fillStyle = gradient;
        ctx.fillText(num.toString(), 0, 0);

        ctx.restore();
      }

      // --- Hands ---
      const hour = now.getHours() % 12;
      const minute = now.getMinutes();
      const second = now.getSeconds();

      const hourAngle = (Math.PI / 6) * hour + (Math.PI / 360) * minute;
      const minuteAngle = (Math.PI / 30) * minute + (Math.PI / 1800) * second;
      const secondAngle = (Math.PI / 30) * second;

      const hourLength = radius * 0.5;
      const minuteLength = radius * 0.7;
      const secondLength = radius * 0.9;

      const drawHandImage = (img, scale, pivotYNormalized) => {
        const imgAspect = img.width / img.height || 1;
        const targetHeight = scale;
        const targetWidth = targetHeight * imgAspect;
        const pivotY = pivotYNormalized * targetHeight;
        ctx.drawImage(
          img,
          -targetWidth / 2,
          -pivotY,
          targetWidth,
          targetHeight,
        );
      };

      // HOUR hand
      ctx.save();
      ctx.rotate(hourAngle);
      ctx.shadowColor = '#2c1c0f';
      ctx.shadowBlur = 12;
      ctx.globalCompositeOperation = 'lighter';
      ctx.filter = `brightness(0.8) contrast(2) sepia(0.6)`;
      drawHandImage(hourHandImage, hourLength, pivots.hour);
      ctx.restore();

      // MINUTE hand
      ctx.save();
      ctx.rotate(minuteAngle);
      ctx.shadowColor = '#0B0A07FF';
      ctx.shadowBlur = 16;
      ctx.globalCompositeOperation = 'lighter';
      ctx.filter = `brightness(1.1) contrast(1.2) sepia(0.4)`;
      drawHandImage(minuteHandImage, minuteLength, pivots.minute);
      ctx.restore();

      // SECOND hand
      ctx.save();
      ctx.rotate(secondAngle);
      ctx.shadowColor = '#ff6347';
      ctx.shadowBlur = 20;
      ctx.globalCompositeOperation = 'lighter';
      ctx.filter = `brightness(1.4) contrast(1.5) sepia(0.5)`;
      drawHandImage(secondHandImage, secondLength, pivots.second);
      ctx.restore();

      ctx.restore();
    };

    loadResources.then(() => {
      resizeCanvas();
    });

    window.addEventListener('resize', resizeCanvas);
    const interval = setInterval(drawClock, 1000);

    return () => {
      clearInterval(interval);
      window.removeEventListener('resize', resizeCanvas);
    };
  }, []);

  return (
    <div
      className="relative w-full h-full overflow-hidden"
      style={{
        backgroundImage: `url(${backgroundImageUrl})`,
        backgroundSize: '100% 100%',
        backgroundPosition: 'center',
        backgroundRepeat: 'no-repeat',
      }}
    >
      <canvas
        ref={canvasRef}
        className="top-0 left-0 absolute w-full h-full"
        style={{ display: 'block', isolation: 'isolate' }}
      />
    </div>
  );
};

export default AnalogClock;

