import React, { useEffect } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import fontUrl from '@/assets/fonts/2025/25-08-19-cas.ttf';
import bgUrl from '@/assets/images/2025/25-08/25-08-19/ap.jpeg';

const Pendulum: React.FC = () => {
  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'CustomFont',
      fontUrl: fontUrl,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  useEffect(() => {
    // Font loading handled by useMultipleFontLoader
    const style = document.createElement('style');
    style.textContent = ``;
    document.head.appendChild(style);

    const updateTimeOnBalls: React.FC = () => {
      const now = new Date();
      let hours = now.getHours();
      hours = hours % 12 || 12;
      hours = String(hours).padStart(2, '0');
      const minutes = String(now.getMinutes()).padStart(2, '0');
      const seconds = String(now.getSeconds()).padStart(2, '0');
      const timeString = `${hours}${minutes}${seconds}`;
      const pieces = document.querySelectorAll('.piece');
      pieces.forEach((piece, index) => {
        piece.setAttribute('data-digit', timeString[index]);
      });
    };
    updateTimeOnBalls();
    const interval = setInterval(updateTimeOnBalls, 1000);
    return () => {
      clearInterval(interval);
      document.head.removeChild(style);
    };
  }, []);

  const styles = {
    pendulumApp: {
      height: '100dvh',
      margin: 0,
