        for (const id of window.__digitalClockIntervals) clearInterval(id);
        window.__digitalClockIntervals.clear();
      }
    };
  }, []);

  const styles = {
    root: {
      position: 'relative',
      height: '100dvh',
      width: '100vw',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontFamily: "'ClockFontScoped_18_09_25', sans-serif",
      overflow: 'hidden',
    },
    clock: {
      fontVariantNumeric: 'tabular-nums lining-nums',
      fontSize: '14vw',
      lineHeight: 1,
      letterSpacing: '-0.05em',
      color: '#BFBBAAFF',
      textShadow: `
        0.2rem 0.2rem 0 #373635FF,
        -0.2rem -0.1rem 0.4rem #6B5D48FF,
        0.1rem -0.2rem 0.4rem #403A30FF,
        -0.1rem 0.2rem 0.4rem #3C362FFF
      `,
      transform: 'rotate(-1deg) skewX(-2deg) skewY(1deg)',
      zIndex: 4,
      userSelect: 'none',
      filter: 'contrast(1.2) saturate(2.0)',
    },
    layer: ({
      img,
      opacity = 1,
      zIndex = 0,
      brightness = 1,
      saturation = 1,
      invert = 0,
      hueRotate = 0,
      transform = undefined,
      width = '100%',
      height = '100%',
      top = 0,
      left = 0,
      backgroundSize = 'cover',
      backgroundPosition = 'center',
    }) => ({
      position: 'absolute',
      top,
      left,
      width,
      height,
      backgroundImage: `url(${img})`,
      backgroundSize,
      backgroundPosition,
      backgroundRepeat: 'no-repeat',
      opacity,
      zIndex,
      pointerEvents: 'none',
      filter: `brightness(${brightness}) saturate(${saturation}) invert(${invert}%) hue-rotate(${hueRotate}deg)`,
      transform,
    }),
    styleTag: {
      fontFace: `/* Font loading handled by useMultipleFontLoader */`,
    },
  };

  const layers = [
    {
      img: bg0,
      opacity: 1,
      zIndex: 1,
      width: '120%',
      height: '110%',
      top: '-5%',
      left: '-10%',
    },
    {
      img: bg1,
      zIndex: 8,
      width: '100%',
      height: '120%',
      top: '-10%',
      left: '0%',
    },
    {
      img: bg3,
      opacity: 0.8,
      zIndex: 6,
      invert: 90,
      brightness: 0.9,
      saturation: 0.4,
      width: '100%',
      height: '170%',
      top: '0%',
      left: '0%',
    },
  ];

  return (
    <div style={styles.root}>
      {layers.map((layerProps, i) => {
        if (i === 1) {
          return (
            <React.Fragment key={i}>
              <div style={styles.layer(layerProps)} />
              <div
                style={styles.layer({ ...layerProps, transform: 'scaleX(-1)' })}
              />
            </React.Fragment>
          );
        }
        return <div key={i} style={styles.layer(layerProps)} />;
      })}

      <div style={styles.clock}>
        {time.hh}
        {time.mm}
        {time.period}
      </div>
    </div>
  );
}

function getTimeParts() {
  const now = new Date();
  let h = now.getHours();
  const m = now.getMinutes();
  const period = h < 12 ? 'AM' : 'PM';
  h = h % 12 || 12;
  return { hh: String(h), mm: String(m).padStart(2, '0'), period };
}

