        {/* Minute hand */}
        <div style={handStyle(minuteDeg, '0.7vw', '#EADCB3FF', 7, '50%')} />

        {/* Second hand */}
        <div style={handStyle(secondDeg, '0.3vw', '#EDE4C7FF', 8, '70%')} />
        <div style={counterweightStyle} />

        {/* Center image */}
        <img
          decoding="async"
          loading="lazy"
