import React, { useState, useEffect } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';
import * as DigitalClock from './ChinaClock.module.css';
import bgImage from '@/assets/images/2025/25-09/25-09-01/clo.webp';
import cornerImage from '@/assets/images/2025/25-09/25-09-01/seal.png';

const chineseDigits = {
  0: '零',
  1: '一',
  2: '二',
  3: '三',
  4: '四',
  5: '五',
  6: '六',
  7: '七',
  8: '八',
  9: '九',
};

const ChinaClock: React.FC = () => {
  const [time, setTime] = useState(new Date());
  const [isMobile, setIsMobile] = useState<any>(window.innerWidth < 768);

  // Update time every second
  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Handle resize
  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const formatTimeToChinese = (date) => {
    const hours = date.getHours().toString().padStart(2, '0').split('');
    const minutes = date.getMinutes().toString().padStart(2, '0').split('');
    const seconds = date.getSeconds().toString().padStart(2, '0').split('');

    const toChinese = (digits) => digits.map((d) => chineseDigits[d]).join('');

    return isMobile
      ? [toChinese(hours), toChinese(minutes), toChinese(seconds)]
      : `${toChinese(hours)}:${toChinese(minutes)}.${toChinese(seconds)}`;
  };

  const timeParts = formatTimeToChinese(time);

  const clockStyle = {
    fontSize: '4rem',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    flexDirection: isMobile ? 'column' : 'row',
    textAlign: 'center',
    background: 'linear-gradient(45deg, #FFD700, #FFA500, #FFE135)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    textShadow: `
      0 0 5px #FFD700,
      0 0 10px #FFA500,
      0 0 15px #FFB900,
      0 2px 2px rgba(0,0,0,0.3),
      0 4px 10px rgba(0,0,0,0.5)
    `,
    fontWeight: 'bold',
    letterSpacing: '0.1rem',
    position: 'relative',
    zIndex: 1,
  };

  const partStyle = { textAlign: 'center' };

  return (
    <div
      style={{
        position: 'relative',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        height: '100dvh',
        width: '100vw',
        margin: 0,
        padding: 0,
        overflow: 'hidden',
      }}
    >
      {/* Background */}
      <div
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          backgroundImage: `url(${bgImage})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          backgroundRepeat: 'no-repeat',
          filter:
            'invert(100%) hue-rotate(180deg) brightness(0.5) contrast(1.3) saturate(1.2)',
          zIndex: 0,
        }}
      >
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            background:
              'radial-gradient(circle, rgba(0,0,0,0) 70%, rgba(0,0,0,0.6) 100%)',
          }}
        />
      </div>

      {/* Clock */}
      <div style={clockStyle} className={DigitalClock.clock}>
        {isMobile ? (
          timeParts.map((part, idx) => (
            <div key={idx} style={partStyle}>
              {part}
            </div>
          ))
        ) : (
          <span style={partStyle}>{timeParts}</span>
        )}
      </div>

      {/* Upper Right Corner Image */}
      <img
        decoding="async"
        loading="lazy"
        src={cornerImage}
        alt="Corner"
        style={{
          position: 'absolute',
          top: '1rem',
          right: '1rem',
          width: '10vw',
          height: 'auto',
          zIndex: 2,
          opacity: 0.9,
        }}
      />
    </div>
  );
};

export default ChinaClock;

