import { useState, useEffect } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import cus250903font from '@/assets/fonts/2025/25-09-03-mau.ttf';
import cornerImage from '@/assets/images/2025/25-09/25-09-03/corner.gif';
import backgroundImage from '@/assets/images/2025/25-09/25-09-03/mau.gif'; // <-- your background image

function DigitalClock() {
  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'Digital7',
      fontUrl: cus250903font,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  const [time, setTime] = useState(new Date());
  const [loaded, setLoaded] = useState<boolean>(false);

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const t = setTimeout(() => setLoaded(true), 100);
    return () => clearTimeout(t);
  }, []);

  const getTimeParts = (date) => {
    let hours = date.getHours();
    const minutes = date.getMinutes();
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12 || 12;
    const formattedMinutes = minutes < 10 ? `0${minutes}` : minutes;
    return { hours, minutes: formattedMinutes, ampm };
  };

  const { hours, minutes, ampm } = getTimeParts(time);

  const containerStyle = {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    height: '100dvh',
    width: '100vw',
    margin: 0,
    padding: 0,
    backgroundColor: '#b784a7',
    backgroundImage: `url(${backgroundImage})`,
    backgroundAttachment: 'fixed',
    backgroundSize: 'cover',
    backgroundRepeat: 'no-repeat',
    backgroundPosition: 'center',
    position: 'relative',
    overflow: 'hidden',
    opacity: loaded ? 1 : 0,
    transition: 'opacity 0.5s ease-in-out',
  };

  const clockStyle = {
    fontFamily: 'Digital7, sans-serif',
    fontSize: '18vw', // default for phones
    color: '#E1B6FEFF',
    textAlign: 'center',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    alignItems: 'center',
    lineHeight: 1.25,
    letterSpacing: '0.05em',
    textShadow: '1px 1px 2px rgba(0,0,0,0.4)',
  };

  const ampmStyle = {
    fontSize: '16vw',
  };

  const cornerStyle = (position) => {
    switch (position) {
      case 'top-left':
        return {
          position: 'absolute',
          top: 0,
          left: 0,
          width: '12rem',
          transform: 'rotate(0deg)',
        };
      case 'top-right':
        return {
          position: 'absolute',
          top: 0,
          right: 0,
          width: '12rem',
          transform: 'rotate(90deg)',
        };
      case 'bottom-left':
        return {
          position: 'absolute',
          bottom: 0,
          left: 0,
          width: '12rem',
          transform: 'rotate(-90deg)',
        };
      case 'bottom-right':
        return {
          position: 'absolute',
          bottom: 0,
          right: 0,
          width: '12rem',
          transform: 'rotate(180deg)',
        };
      default:
        return {};
    }
  };

  return (
    <>
      <style>
        {`
          /* Font loading handled by useMultipleFontLoader */

          /* On larger screens, reduce font size */
          @media (min-width: 700px) {
            .clock-text {
              font-size: 18vh !important;
            }
            .clock-ampm {
              font-size: 16vh !important;
            }
          }
        `}
      </style>
      <div style={containerStyle}>
        <img
          decoding="async"
          loading="lazy"
          src={cornerImage}
          alt="Corner"
          style={cornerStyle('top-left')}
        />
        <img
          decoding="async"
          loading="lazy"
          src={cornerImage}
          alt="Corner"
          style={cornerStyle('top-right')}
        />
        <img
          decoding="async"
          loading="lazy"
          src={cornerImage}
          alt="Corner"
          style={cornerStyle('bottom-left')}
        />
        <img
          decoding="async"
          loading="lazy"
          src={cornerImage}
          alt="Corner"
          style={cornerStyle('bottom-right')}
        />

        <div style={clockStyle} className="clock-text">
          <div>{hours}</div>
          <div>{minutes}</div>
          <div style={ampmStyle} className="clock-ampm">
            {ampm}
          </div>
        </div>
      </div>
    </>
  );
}

export default DigitalClock;

