          { x: 20, y: 58 },
          { x: 40, y: 79 },
          { x: 60, y: 17 },
          { x: 89, y: 30 },
        ];
        let z = i < 2 ? 4 : i < 4 ? 3 : 2;
        return (
          <div
            key={`d${i}`}
            style={digitStyle(positions[i].x, positions[i].y, '62vw', z)}
          >
            {d}
          </div>
        );
      })}

      {allAMPM.map((c, i) => {
        const positions = [
          { x: 70, y: 70 },
          { x: 805, y: 80 },
          { x: 90, y: 90 },
          { x: 950, y: 80 },
        ];
        return (
          <div
            key={`a${i}`}
            style={digitStyle(positions[i].x, positions[i].y, '62vw', 5)}
          >
            {c}
          </div>
        );
      })}

      <img
        decoding="async"
        loading="lazy"
        src={MovingImg}
        alt="moving"
        style={movingStyle}
      />
    </div>
  );
}

