import React, { useEffect, useState } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';
import bgImage from '@/assets/images/2025/25-09/25-09-08/orange.webp';
import img1 from '@/assets/images/2025/25-09/25-09-08/1.webp';
import img2 from '@/assets/images/2025/25-09/25-09-08/2.jpg';
import img3 from '@/assets/images/2025/25-09/25-09-08/3.jpg';
import img4 from '@/assets/images/2025/25-09/25-09-08/4.jpg';
import img5 from '@/assets/images/2025/25-09/25-09-08/5.jpg';
import img6 from '@/assets/images/2025/25-09/25-09-08/6.jpg';
import img7 from '@/assets/images/2025/25-09/25-09-08/7.jpg';
import img8 from '@/assets/images/2025/25-09/25-09-08/8.jpg';
import img9 from '@/assets/images/2025/25-09/25-09-08/9.jpg';
import img10 from '@/assets/images/2025/25-09/25-09-08/10.jpg';
import img11 from '@/assets/images/2025/25-09/25-09-08/11.jpg';
import img12 from '@/assets/images/2025/25-09/25-09-08/12.webp';

export default function ImageAnalogClock() {
  const [time, setTime] = useState(new Date());
  const [loaded, setLoaded] = useState<boolean>(false);

  const images = [
    bgImage,
    img12,
    img1,
    img2,
    img3,
    img4,
    img5,
    img6,
    img7,
    img8,
    img9,
    img10,
    img11,
  ];
  const CLOCK_SIZE = 90;
  const CENTER = CLOCK_SIZE / 2;
  const IMG_RADIUS = CLOCK_SIZE * 0.42;
  const IMG_SIZE = CLOCK_SIZE * 0.2;
  const intenseShadow =
    '0 1.5vmin 3vmin rgba(0,0,0,1), 0 0 2vmin rgba(0,0,0,0.8)';

  // Preload images
  useEffect(() => {
    let loadedCount = 0;
    images.forEach((src) => {
      const img = new Image();
      img.src = src;
      img.onload = () => {
        loadedCount += 1;
        if (loadedCount === images.length) setLoaded(true);
      };
      img.onerror = () => {
        loadedCount += 1;
        if (loadedCount === images.length) setLoaded(true);
      };
    });
  }, []);

  // Tick every second
  useEffect(() => {
    const interval = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(interval);
  }, []);

  if (!loaded) {
    return (
      <div
        style={{
          color: 'white',
          fontSize: '2rem',
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
        }}
      >
        Loading...
      </div>
    );
  }

  const hourImages = [
    img12,
    img1,
    img2,
    img3,
    img4,
    img5,
    img6,
    img7,
    img8,
    img9,
    img10,
    img11,
  ];
  const hours = time.getHours() % 12;
  const minutes = time.getMinutes();
  const seconds = time.getSeconds();

  const hourAngle = (hours + minutes / 60) * 30;
  const minuteAngle = (minutes + seconds / 60) * 6;
  const secondAngle = seconds * 6;

  return (
    <div
      style={{
        width: '100vw',
        height: '100dvh',
        position: 'fixed',
        top: 0,
        left: 0,
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        overflow: 'hidden',
        margin: 0,
        padding: 0,
      }}
      aria-label={`Analog clock showing ${hours}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`}
    >
      <div
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          backgroundImage: `url(${bgImage})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          backgroundRepeat: 'no-repeat',
          filter: 'brightness(0.6) contrast(2.2)',
          zIndex: 0,
        }}
      />
      <div
        style={{
          width: `${CLOCK_SIZE}vmin`,
          height: `${CLOCK_SIZE}vmin`,
          maxWidth: '800px',
          maxHeight: '800px',
          borderRadius: '50%',
          position: 'relative',
          zIndex: 1,
        }}
      >
        {hourImages.map((img, i) => {
          const angle = i * 30 * (Math.PI / 180);
          const x = CENTER + IMG_RADIUS * Math.sin(angle);
          const y = CENTER - IMG_RADIUS * Math.cos(angle);
          return (
            <div
              key={i}
              style={{
                width: `${IMG_SIZE}vmin`,
                height: `${IMG_SIZE}vmin`,
                position: 'absolute',
                left: `${x - IMG_SIZE / 2}vmin`,
                top: `${y - IMG_SIZE / 2}vmin`,
                borderRadius: '50%',
