          transform: 'translate(-50%, -50%)',
          width: '95vmin',
          height: '95vmin',
          borderRadius: '50%',
          background: 'rgba(255,255,255,0.05)',
          zIndex: 2,
        }}
      >
        {[...Array(12)].map((_, i) => {
          const angle = (i + 1) * 30;
          const radius = 40;
          const x = 50 + radius * Math.sin((angle * Math.PI) / 180);
          const y = 50 - radius * Math.cos((angle * Math.PI) / 180);
          return (
            <div
