                zIndex: 3,
              }}
            >
              {i + 1}
            </div>
          );
        })}
      </div>

      {/* Clock hands */}
      <img
        decoding="async"
        loading="lazy"
        ref={hourRef}
        src={hourHand}
        alt="hour hand"
        style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
