        speed,
        twinklePhase: Math.random() * Math.PI * 2, // for twinkling
      }));

    const createCanvasContext = (ref, size, dpr) => {
      const canvas = ref.current;
      canvas.width = size * dpr;
      canvas.height = size * dpr;
      canvas.style.width = `${size}px`;
      canvas.style.height = `${size}px`;
      const ctx = canvas.getContext('2d');
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      return ctx;
    };

    const drawClockFace = (ctx, radius, fontSize) => {
      ctx.save();
      ctx.translate(radius, radius);
      ctx.imageSmoothingEnabled = false;

      for (let i = 0; i < 12; i++) {
        const angle = (i * 30 * Math.PI) / 180;
        ctx.save();
        ctx.rotate(angle);
        ctx.translate(0, -radius * 0.65);
        ctx.rotate(-angle);

        ctx.font = `${fontSize} Times New Roman`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.shadowColor = CONFIG.SHADOW_COLOR;
        ctx.shadowBlur = CONFIG.SHADOW_BLUR;

        if (i === 8) {
          ctx.save();
          ctx.scale(-1, 1);
          ctx.fillText(CONFIG.HOUR_NUMBERS[i], 0, 0);
          ctx.restore();
        } else {
          ctx.fillText(CONFIG.HOUR_NUMBERS[i], 0, 0);
        }
        ctx.restore();
      }
      ctx.restore();
    };

    const drawHand = (ctx, value, max, length, width, radius) => {
      ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);
      ctx.save();
      ctx.globalAlpha = 0.4;
      ctx.translate(radius, radius);
      ctx.rotate((value / max) * 2 * Math.PI);

      const grad = ctx.createLinearGradient(0, 0, 0, -radius * length);
      CONFIG.HAND_GRADIENT.forEach(({ stop, color }) =>
        grad.addColorStop(stop, color),
      );

      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(0, -radius * length);
      ctx.lineWidth = width;
      ctx.strokeStyle = grad;
      ctx.lineCap = 'round';
      ctx.shadowColor = CONFIG.HAND_SHADOW_COLOR;
      ctx.shadowBlur = CONFIG.HAND_SHADOW_BLUR;
      ctx.stroke();
      ctx.restore();
    };

    const drawSheen = (ctx, radius, sheenAngle) => {
      ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);
      ctx.save();
      ctx.translate(radius, radius);
      ctx.rotate(sheenAngle);

      const grad = ctx.createRadialGradient(0, 0, radius * 0.2, 0, 0, radius);
      CONFIG.SHEEN_GRADIENT.forEach(({ stop, color }) =>
        grad.addColorStop(stop, color),
      );

      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, 2 * Math.PI);
      ctx.fill();
      ctx.restore();
    };

    const resize: React.FC = () => {
      starCanvas.width = window.innerWidth;
      starCanvas.height = window.innerHeight;

      stars = STAR_LAYERS.map((layer) =>
        generateStars(layer.count, layer.sizeMin, layer.sizeMax, layer.speed),
      );

      const isLaptop = window.innerWidth >= CONFIG.BREAKPOINT;
      const size =
        Math.min(window.innerWidth, window.innerHeight) *
        CONFIG.SIZE_MULTIPLIER;
      fontSize = isLaptop ? CONFIG.FONT_SIZES.laptop : CONFIG.FONT_SIZES.phone;
      const dpr = window.devicePixelRatio || 1;

      contexts = {
        face: createCanvasContext(faceRef, size, dpr),
        sheen: createCanvasContext(sheenRef, size, dpr),
        hour: createCanvasContext(hourRef, size, dpr),
        minute: createCanvasContext(minuteRef, size, dpr),
        second: createCanvasContext(secondRef, size, dpr),
      };
      radius = size / 2;

      drawClockFace(contexts.face, radius, fontSize);
    };

    const animate: React.FC = () => {
      // ---- Stars ----
      starCtx.clearRect(0, 0, starCanvas.width, starCanvas.height);

      // vertical gradient
      const verticalGradient = starCtx.createLinearGradient(
        0,
        0,
        0,
        starCanvas.height,
      );
      verticalGradient.addColorStop(0, '#0E0133FF');
      verticalGradient.addColorStop(1, '#072702FF');
      starCtx.fillStyle = verticalGradient;
      starCtx.fillRect(0, 0, starCanvas.width, starCanvas.height);

      // stars
      stars.forEach((layer, index) => {
        layer.forEach((star) => {
          const twinkle =
            0.5 + 0.5 * Math.sin(Date.now() * 0.002 + star.twinklePhase);
          starCtx.globalAlpha = STAR_LAYERS[index].opacity * twinkle;
          starCtx.fillStyle = STAR_LAYERS[index].color;
          starCtx.beginPath();
          starCtx.arc(star.x, star.y, star.size, 0, Math.PI * 2);
          starCtx.fill();

          star.y -= star.speed;
          if (star.y < 0) {
            star.y = starCanvas.height;
            star.x = Math.random() * starCanvas.width;
          }
        });
      });
      starCtx.globalAlpha = 1.0;

      // ---- Clock ----
      const now = new Date();
      const hours =
        (now.getHours() % 12) + now.getMinutes() / 60 + now.getSeconds() / 3600;
      const minutes =
        now.getMinutes() +
        now.getSeconds() / 60 +
        now.getMilliseconds() / 60000;
      const seconds = now.getSeconds() + now.getMilliseconds() / 1000;

      drawHand(
        contexts.hour,
        hours,
        CONFIG.HAND_CONFIG[0].max,
        CONFIG.HAND_CONFIG[0].length,
        CONFIG.HAND_CONFIG[0].width,
        radius,
      );
      drawHand(
        contexts.minute,
        minutes,
        CONFIG.HAND_CONFIG[1].max,
        CONFIG.HAND_CONFIG[1].length,
        CONFIG.HAND_CONFIG[1].width,
        radius,
      );
      drawHand(
        contexts.second,
        seconds,
        CONFIG.HAND_CONFIG[2].max,
        CONFIG.HAND_CONFIG[2].length,
        CONFIG.HAND_CONFIG[2].width,
        radius,
      );

      sheenAngle += 0.002;
      drawSheen(contexts.sheen, radius, sheenAngle);

      requestAnimationFrame(animate);
    };

    resize();
    animate();
    window.addEventListener('resize', resize);

    return () => window.removeEventListener('resize', resize);
  }, []);

  return (
    <div
      style={{
        width: '100vw',
        height: '100dvh',
        position: 'relative',
        overflow: 'hidden',
      }}
    >
      <canvas
        ref={starCanvasRef}
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          zIndex: 0,
        }}
      />
      <div
        style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          zIndex: 2,
        }}
      >
        <canvas
          ref={faceRef}
          style={{
            position: 'absolute',
            borderRadius: '50%',
            filter: 'grayscale(90%)',
          }}
        />
        <canvas
          ref={sheenRef}
          style={{
            position: 'absolute',
            borderRadius: '50%',
            pointerEvents: 'none',
          }}
        />
        <canvas
          ref={hourRef}
          style={{ position: 'absolute', borderRadius: '50%' }}
        />
        <canvas
          ref={minuteRef}
          style={{ position: 'absolute', borderRadius: '50%' }}
        />
        <canvas
          ref={secondRef}
          style={{ position: 'absolute', borderRadius: '50%' }}
        />
      </div>
    </div>
  );
};

export default App;

