import React, { useState, useEffect, useMemo } from 'react';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import customFontpawww from '@/assets/fonts/2025/25-09-13-anim.ttf?url';
import bgImage from '@/assets/images/2025/25-09/25-09-13/anim.jpg';

const DigitalClock: React.FC = () => {
  const [time, setTime] = useState(new Date());
  const [prevTime, setPrevTime] = useState(new Date());
  const [isHorizontal, setIsHorizontal] = useState<any>(window.innerWidth >= 768);

  const fontConfigs = useMemo(() => [
    {
      fontFamily: 'CustomClockFont',
      fontUrl: customFontpawww,
      options: { weight: 'normal', style: 'normal' }
    }
  ], []);
  useSuspenseFontLoader(fontConfigs);

  useEffect(() => {
    const interval = setInterval(() => {
      setPrevTime(time);
      setTime(new Date());
    }, 1000);
    return () => clearInterval(interval);
  }, [time]);

  useEffect(() => {
    const handleResize = () => setIsHorizontal(window.innerWidth >= 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const formatTime = (date) => {
    const hours = date.getHours();
    const minutes = date.getMinutes();
    const seconds = date.getSeconds();
    const pad = (num) => String(num).padStart(2, '0');
    return { hours: pad(hours), minutes: pad(minutes), seconds: pad(seconds) };
  };

  const current = formatTime(time);
  const previous = formatTime(prevTime);
  const replaceNine = (str) => str.replace(/9/g, 'q');

  const containerStyle = {
    width: '100vw',
    height: '100dvh',
    display: 'flex',
    flexDirection: isHorizontal ? 'row' : 'column',
    justifyContent: 'center',
    alignItems: 'center',
    backgroundImage: `url(${bgImage})`,
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    fontFamily: 'CustomClockFont, sans-serif',
    visibility: 'visible',
  };

  const rowStyle = { display: 'flex' };
  const digitBoxStyle = {
    padding: '1rem 1.2rem',
    fontSize: '6rem',
    minWidth: '4rem',
    minHeight: '4rem',
    textAlign: 'center',
    position: 'relative',
    overflow: 'hidden',
  };
  const digitStyle = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    background: `
      linear-gradient(
        to bottom,
        rgba(20,20,20,0.9) 15%,  
        rgba(128,128,128,0.9) 40%,     
        rgba(128,128,128,0.9) 50%, 
        rgba(225,225,255,0.9) 85%,
        white 90%, 
        white 100%
      )
    `,
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    backgroundClip: 'text',
    textFillColor: 'transparent',
    opacity: 0.8,
  };

  const renderRow = (currentStr, previousStr, boxStyle) =>
    replaceNine(currentStr)
      .split('')
      .map((digit, idx) => (
        <div key={idx} style={{ ...boxStyle, position: 'relative' }}>
          <div style={digitStyle}>{digit}</div>
        </div>
      ));

  return (
    <div style={containerStyle}>
      {/* Hours */}
      <div style={rowStyle}>
        {renderRow(current.hours, previous.hours, digitBoxStyle)}
      </div>

      {/* Minutes */}
      <div style={rowStyle}>
        {renderRow(current.minutes, previous.minutes, digitBoxStyle)}
      </div>

      {/* Seconds */}
      <div style={rowStyle}>
        {renderRow(current.seconds, previous.seconds, digitBoxStyle)}
      </div>
    </div>
  );
};

export default DigitalClock;

import React, { useEffect, useRef } from 'react';
import bgImageSrc from '@/assets/images/2025/25-09/25-09-14/bg.gif';

const GoldenChordsClock: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const R = 180;
  const chordLength = 1.9 * R;
  const numChords = 12;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Load background image
    const bgImage = new Image();
    bgImage.src = bgImageSrc;

    const draw = () => {
      const now = new Date();
      const seconds = now.getSeconds() + now.getMilliseconds() / 1000;
      const minutes = now.getMinutes() + seconds / 60;
      const hours = (now.getHours() % 12) + minutes / 60;

      const centerX = canvas.width / 2;
      const centerY = canvas.height / 2;
      const scale = Math.min(canvas.width, canvas.height) / 400;

      // --- STATIC GOLD BACKGROUND ---
      ctx.fillStyle = 'hsl(50, 100%, 40%)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // --- ROTATING BACKGROUND IMAGE ---
      if (bgImage.complete) {
        const bgRotation = ((seconds % 60) / 60) * 2 * Math.PI;
        ctx.save();
        ctx.translate(centerX, centerY);
        ctx.rotate(bgRotation);
        ctx.filter = 'contrast(1.1) brightness(1.2) saturate(1.6)';
        const imgScale =
          0.8 *
          Math.max(
            canvas.width / bgImage.width,
            canvas.height / bgImage.height,
          );
        ctx.drawImage(
          bgImage,
          (-bgImage.width / 2) * imgScale,
          (-bgImage.height / 2) * imgScale,
          bgImage.width * imgScale,
          bgImage.height * imgScale,
        );
        ctx.restore();
        ctx.filter = 'none';
      }

      // --- CLOCK HANDS ---
      const clockRadius = R * 0.6 * scale;
      const drawHand = (
        angle: number,
        length: number,
        width: number,
        color: string,
      ) => {
        ctx.save();
        ctx.globalAlpha = 0.9;
        ctx.shadowColor = 'rgba(24, 28, 26, 0.8)';
        ctx.shadowBlur = 4 * scale;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(
          centerX + Math.sin(angle) * length,
          centerY - Math.cos(angle) * length,
        );
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.lineCap = 'round';
        ctx.stroke();
        ctx.restore();
      };

      drawHand(
        (hours * 2 * Math.PI) / 12,
        clockRadius * 1.0,
        8 * scale,
        '#F1EB6BFF',
      );
      drawHand(
        (minutes * 2 * Math.PI) / 60,
        clockRadius * 1.5,
        4.5 * scale,
        '#F1EB6BFF',
      );

      // --- GOLDEN CHORDS PULLED TOWARD CENTER ---
      const chordRotation = -(seconds * 2 * Math.PI) / 60;
      const halfChordAngle = Math.asin(Math.min(1, chordLength / (2 * R)));
      const extension = Math.max(canvas.width, canvas.height) * 1.5;

      // offsetFactor: 0 = exact center, 1 = original starting point (further out)
      const offsetFactor = 0.28; // smaller = closer to center

      for (let i = 0; i < numChords; i++) {
        const angleOffset = chordRotation + (i * 2 * Math.PI) / numChords;

        const startX =
          centerX +
          Math.cos(angleOffset - halfChordAngle) * extension * offsetFactor;
        const startY =
          centerY +
          Math.sin(angleOffset - halfChordAngle) * extension * offsetFactor;
        const endX =
          centerX + Math.cos(angleOffset + halfChordAngle) * extension;
        const endY =
          centerY + Math.sin(angleOffset + halfChordAngle) * extension;

        const grad = ctx.createLinearGradient(startX, startY, endX, endY);
        grad.addColorStop(0, 'rgba(255, 215, 0, 1)');
        grad.addColorStop(0.25, 'rgba(255, 224, 102, 0.9)');
        grad.addColorStop(0.5, 'rgba(255, 248, 176, 0.7)');
        grad.addColorStop(0.75, 'rgba(255, 224, 10, 0.9)');
        grad.addColorStop(1, 'rgba(255, 215, 0, 1)');

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.strokeStyle = grad;
        ctx.lineWidth = 4 * scale;
        ctx.shadowColor = 'rgba(255, 215, 0, 0.9)';
        ctx.shadowBlur = 60 * scale;
        ctx.stroke();
        ctx.restore();

        // Reflection
        const reflectionGrad = ctx.createLinearGradient(
          startX,
          startY,
          endX,
          endY,
        );
        reflectionGrad.addColorStop(0, 'rgba(255,255,255,0.6)');
        reflectionGrad.addColorStop(0.5, 'rgba(255,255,255,0.2)');
        reflectionGrad.addColorStop(1, 'rgba(255,255,255,0)');
        ctx.save();
        ctx.globalAlpha = 0.9;
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.strokeStyle = reflectionGrad;
        ctx.lineWidth = 1.5 * scale;
        ctx.stroke();
        ctx.restore();
      }

      requestAnimationFrame(draw);
    };

    const handleResize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', handleResize);
    handleResize();
    requestAnimationFrame(draw);

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <canvas
      ref={canvasRef}
      style={{ width: '100vw', height: '100dvh', display: 'block' }}
    />
  );
};

export default GoldenChordsClock;

