import React, { useEffect, useState, useMemo } from 'react';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import type { FontConfig } from '@/types/clock';
import cust250921font from '@/assets/fonts/2025/25-09-21-ele.ttf?url';
import stripe1 from '@/assets/images/2025/25-09/25-09-21/fire.gif?url';
import stripe2 from '@/assets/images/2025/25-09/25-09-21/air.webp?url';
import stripe3 from '@/assets/images/2025/25-09/25-09-21/h2o.webp?url';
import stripe4 from '@/assets/images/2025/25-09/25-09-21/earth.webp?url';

export default function AnalogClock() {
  const [time, setTime] = useState(new Date());
  const fontVar = 'ElementalFont';

  const fontConfigs = useMemo<FontConfig[]>(() => [
    { fontFamily: fontVar, fontUrl: cust250921font }
  ], []);

  useSuspenseFontLoader(fontConfigs);

  useEffect(() => {
    const interval = setInterval(() => setTime(new Date()), 16);
    return () => clearInterval(interval);
  }, []);

  const hour = time.getHours() % 12;
  const minute = time.getMinutes();
  const second = time.getSeconds();
  const millisecond = time.getMilliseconds();

  const hourDeg = (hour + minute / 60 + second / 3600) * 30;
  const minuteDeg = (minute + second / 60 + millisecond / 60000) * 6;
  const secondDeg = (second + millisecond / 1000) * 6;

  const stripes = [stripe1, stripe2, stripe3, stripe4];

  // Hand style helper
  const handStyle = (width, height, top, rotateDeg) => ({
    position: 'absolute',
    width: width,
    height: height,
    top: top,
    left: '50%',
    transformOrigin: '50% 100%',
    transform: `rotate(${rotateDeg}deg)`,
    backgroundColor: 'transparent',
    borderRadius: '0.25rem',
    zIndex: 5, // lower than numbers
    boxShadow: `
      0.05rem 0.05rem 0 rgba(255, 250, 230, 0.8),
      -0.05rem -0.05rem 0 rgba(0,0,0,0.8)
    `,
  });

  const numberStyle = {
    position: 'absolute',
    fontSize: '4rem',
    fontFamily: fontVar,
    color: 'transparent',
    WebkitTextFillColor: 'transparent',
    textShadow: `
      0.05rem 0.05rem 0 rgba(255, 250, 230),
      -0.05rem -0.05rem 0 rgba(0,0,0)
    `,
    zIndex: 10,
    display: 'flex',
    opacity: 0.3,
    alignItems: 'center',
    justifyContent: 'center',
  };

  return (
    <div
      style={{
        width: '100vw',
        height: '100dvh',
        position: 'relative',
        overflow: 'hidden',
        backgroundColor: '#EFE9E9FF',
        fontFamily: fontVar,
      }}
    >
      {/* Clock layers container (pointer-events disabled) */}
      <div style={{ width: '100%', height: '100%', pointerEvents: 'none' }}>
        {/* Stripes */}
        {stripes.map((src, idx) => {
          let mask = '';
          if (idx === 0)
            mask =
              'linear-gradient(to bottom, rgba(0,0,0,1) 80%, rgba(0,0,0,0) 100%)';
          else if (idx === 3)
            mask =
              'linear-gradient(to bottom, rgba(0,0,0,0) 0%, rgba(0,0,0,1) 20%)';
          else
            mask =
              'linear-gradient(to bottom, rgba(0,0,0,0) 0%, rgba(0,0,0,1) 20%, rgba(0,0,0,1) 80%, rgba(0,0,0,0) 100%)';

          let filter =
            'hue-rotate(0deg) saturate(1) brightness(1) contrast(0.8)';
          if (idx === 0)
            filter =
              'hue-rotate(-40deg) saturate(2.2) brightness(1.1) contrast(1.1)';
          if (idx === 1)
            filter =
              'hue-rotate(220deg) saturate(1.9) brightness(1.0) contrast(1.9)';
          if (idx === 2)
            filter =
              'hue-rotate(-19deg) saturate(1.1) brightness(1.05) contrast(1.3)';
          if (idx === 3)
            filter =
              'sepia(1) hue-rotate(20deg) saturate(1.2) brightness(1.1) contrast(0.7)';

          return (
            <div
              key={idx}
              style={{
                position: 'absolute',
                top:
                  idx === 0
                    ? '0'
                    : idx === 1
                      ? '15dvh'
                      : idx === 2
                        ? '49dvh'
                        : 'calc(100dvh - 28dvh)',
                left: 0,
                width: '100vw',
                height: idx === 1 ? '50dvh' : idx === 2 ? '40dvh' : '28dvh',
                zIndex: idx,
              }}
            >
              {[false, true].map((flipped, i) => (
                <div
                  key={`${idx}-${i}`}
                  style={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                    height: '100%',
                    backgroundImage: `url(${src})`,
                    backgroundSize: 'cover',
                    backgroundPosition: 'center',
                    backgroundRepeat: 'no-repeat',
                    WebkitMaskImage: mask,
                    maskImage: mask,
                    filter: filter,
                    opacity: 0.5,
                    transform: flipped ? 'scaleX(-1)' : 'none',
                  }}
                />
              ))}
            </div>
          );
        })}

        {/* Numbers */}
        <div
          style={{
            ...numberStyle,
            top: '2vh',
            left: '50%',
            transform: 'translateX(-50%) scaleX(-1)',
          }}
        >
          8
        </div>
        <div
          style={{
            ...numberStyle,
            bottom: '2vh',
            left: '50%',
            transform: 'translateX(-50%)',
          }}
        >
          6
        </div>
        <div
          style={{
            ...numberStyle,
            top: '50%',
            right: '2vw',
            transform: 'translateY(-50%)',
          }}
        >
          3
        </div>
        <div
          style={{
            ...numberStyle,
            top: '50%',
            left: '2vw',
            transform: 'translateY(-50%)',
          }}
        >
          9
        </div>

        {/* Clock face + hands */}
        <div
          style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            width: '70vw',
            height: '70vw',
            borderRadius: '50%',
            opacity: '0.8',
            background: 'transparent',
            zIndex: 5,
          }}
        >
          {/* Full viewport second hand */}
          <div
            style={{
              position: 'absolute',
              width: '0.2rem',
              height: '50dvh',
              top: '50%',
              left: '50%',
              transformOrigin: '50% 0%',
              transform: `rotate(${secondDeg}deg)`,
              backgroundColor: 'transparent',
              boxShadow: `
                0.05rem 0.05rem 0 rgba(255, 250, 230, 0.8),
                -0.05rem -0.05rem 0 rgba(0,0,0,0.8)
              `,
            }}
          />

          {/* Hour hand */}
          <div style={handStyle('0.5rem', '25%', '25%', hourDeg)} />

          {/* Minute hand */}
          <div style={handStyle('0.35rem', '35%', '15%', minuteDeg)} />

          {/* Second hand */}
          <div style={handStyle('0.2rem', '40%', '10%', secondDeg)} />
        </div>
      </div>
    </div>
  );
}

