import React, { useEffect, useState, useMemo, useRef } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';

// digits
import digit1 from '@/assets/images/2025/25-09/25-09-23/z.gif';
import digit2 from '@/assets/images/2025/25-09/25-09-23/z2.gif';
import digit10 from '@/assets/images/2025/25-09/25-09-23/z3.gif';
import digit12 from '@/assets/images/2025/25-09/25-09-23/z4.gif';
import digit5 from '@/assets/images/2025/25-09/25-09-23/z5.gif';
import digit6 from '@/assets/images/2025/25-09/25-09-23/z6.gif';
import digit7 from '@/assets/images/2025/25-09/25-09-23/z7.gif';
import digit8 from '@/assets/images/2025/25-09/25-09-23/z8.webp';
import digit9 from '@/assets/images/2025/25-09/25-09-23/z9.webp';
import digit11 from '@/assets/images/2025/25-09/25-09-23/z10.gif';
import digit3 from '@/assets/images/2025/25-09/25-09-23/z11.gif';
import digit4 from '@/assets/images/2025/25-09/25-09-23/z12.gif';

// hands
import hourHandImg from '@/assets/images/2025/25-09/25-09-23/steth.png';
import minuteHandImg from '@/assets/images/2025/25-09/25-09-23/sss.webp';
import secondHandImg from '@/assets/images/2025/25-09/25-09-23/ste.gif';

export default function AnalogClock() {
  const hourRef = useRef(null);
  const minuteRef = useRef(null);
  const secondRef = useRef(null);
  const animationFrameRef = useRef(null);
  const [ready, setReady] = useState<boolean>(false);

  // Digits array
  const digits = useMemo(
    () => [
      digit12,
      digit1,
      digit2,
      digit3,
      digit4,
      digit5,
      digit6,
      digit7,
      digit8,
      digit9,
      digit10,
      digit11,
    ],
    [],
  );

  // Preload images once
  useEffect(() => {
    const allImages = [...digits, hourHandImg, minuteHandImg, secondHandImg];
    Promise.all(
      allImages.map(
        (src) =>
          new Promise((resolve) => {
            const img = new Image();
            img.onload = img.onerror = resolve;
            img.src = src;
          }),
      ),
    ).then(() => setReady(true));
  }, [digits]);

  // Digit positions (static)
  const digitElements = useMemo(() => {
    return digits.map((src, i) => {
      const angle = (i / 12) * 2 * Math.PI;
      const radius = 42;
      const x = 50 + radius * Math.sin(angle);
      const y = 50 - radius * Math.cos(angle);

      return (
        <img
          decoding="async"
          loading="lazy"
          key={i}
          src={src}
          alt={`digit-${i}`}
          className="clock-digit"
          style={{
            position: 'absolute',
            top: `${y}%`,
            left: `${x}%`,
            transform: 'translate(-50%, -50%)',
            width: 'auto',
          }}
        />
      );
    });
  }, [digits]);

  // Animate hands efficiently
  useEffect(() => {
    if (!ready) return;

    const update: React.FC = () => {
      const now = new Date();
      const ms = now.getMilliseconds() / 1000;
      const seconds = now.getSeconds() + ms;
      const minutes = now.getMinutes() + seconds / 60;
      const hours = (now.getHours() % 12) + minutes / 60;

      if (secondRef.current) {
        secondRef.current.style.transform = `translateX(-50%) rotate(${(seconds / 60) * 360}deg)`;
      }
      if (minuteRef.current) {
        minuteRef.current.style.transform = `translateX(-50%) rotate(${(minutes / 60) * 360}deg)`;
      }
      if (hourRef.current) {
        hourRef.current.style.transform = `translateX(-50%) rotate(${(hours / 12) * 360}deg)`;
      }

      animationFrameRef.current = requestAnimationFrame(update);
    };

    animationFrameRef.current = requestAnimationFrame(update);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, [ready]);

  if (!ready) return null;

  return (
    <div
      style={{
        height: '100dvh',
        width: '100vw',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        background:
          'radial-gradient(circle, rgba(123,120,120,0.8) 0%, rgba(159,116,10,0.3) 80%)',
      }}
    >
      <div className="clock-face">
        {digitElements}

        <img
          decoding="async"
          loading="lazy"
          ref={hourRef}
          src={hourHandImg}
          alt="hour-hand"
          className="hour-hand"
        />
        <img
          decoding="async"
          loading="lazy"
          ref={minuteRef}
          src={minuteHandImg}
          alt="minute-hand"
          className="minute-hand"
        />
        <img
          decoding="async"
          loading="lazy"
          ref={secondRef}
          src={secondHandImg}
          alt="second-hand"
          className="second-hand"
        />
      </div>

      <style>{`
        /* Clock Face */
        .clock-face {
          position: relative;
          border-radius: 50%;
          box-shadow: inset -1.2rem -1.2rem 2.4rem rgba(0,0,0,0.15),
                      inset 1.2rem 1.2rem 2.4rem rgba(220,235,255,0.15),
                      0 1.5rem 3rem rgba(90,0,0,0.15);
          background: radial-gradient(circle at center,
                      rgba(210,260,10,0.15) 10%,
                      rgba(260,280,60,0.15) 90%);
          width: 100vw;
          height: 100vw;
        }

        /* Digits */
        .clock-digit {
          height:16vh; /* phones */
        }
        @media (min-width: 768px) {
          .clock-face {
            width: 90vh;
            height: 90vh;
          }
          .clock-digit {
            height: 12vw; /* laptops/desktops */
          }
        }

        /* Hands */
        .hour-hand, .minute-hand, .second-hand {
          position: absolute;
          bottom: 50%;
          left: 50%;
          transform-origin: bottom center;
          will-change: transform;
        }

        .hour-hand {
          opacity: 0.9;
          width: 9vmin;
          height: 22vmin;
        }
        .minute-hand {
          opacity: 0.8;
          width: 12vmin;
          height: 35vmin;
        }
        .second-hand {
          width: 32vmin;
          height: 40vmin;
        }

        @media (min-width: 768px) {
          .hour-hand {
            width: 16vh;
            height: 17vh;
          }
          .minute-hand {
            width: 12vh;
            height: 33vh;
          }
          .second-hand {
            width: 32vh;
            height: 38vh;
          }
        }
      `}</style>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import font20250924 from '@/assets/fonts/2025/25-09-24-cora.ttf?url';

const HorizontalProportionalGradientClock: React.FC = () => {
  const [time, setTime] = useState(new Date());

  // Load font via Suspense
  useSuspenseFontLoader([{ fontFamily: 'CustomFont', fontUrl: font20250924 }]);

  // Clock tick animation
  useEffect(() => {
    let frame;
    const tick = () => {
      setTime(new Date());
      frame = requestAnimationFrame(tick);
    };

    tick();
    return () => cancelAnimationFrame(frame);
  }, []);

  let hours = time.getHours() % 12;
  if (hours === 0) hours = 12;

  const minutes = time.getMinutes();
  const seconds = time.getSeconds();

  const numbers = [
    { value: hours, max: 12, isHour: true },
    { value: Math.floor(minutes / 10), max: 5 },
    { value: minutes % 10, max: 9 },
    { value: Math.floor(seconds / 10), max: 5 },
    { value: seconds % 10, max: 9 },
  ];

  const scaleFactor = 29;
  const adder = 2;

  const scaleDigit = (num) => {
    const normalized = num.isHour ? (num.value - 1) / 11 : num.value / num.max;
    return normalized * scaleFactor + adder;
  };

  const getGray = (value, max) => {
    const gray = Math.floor((value / max) * 255);
    return `rgb(${gray}, ${gray}, ${gray})`;
  };

  const containerStyle = {
    width: '100vw',
    height: '100vh',
    display: 'flex',
    flexDirection: 'row',
  };

  const styles = `
    .clock-digit {
      font-family: 'CustomFont', sans-serif;
      text-shadow: -4px 0px 0px black, 2px 0px 0px white;
      display: flex;
      justify-content: center;
      align-items: center;
      transition: flex 0.6s ease-in-out, font-size 0.6s ease-in-out,
                  background-color 0.6s ease-in-out, color 0.6s ease-in-out;
      border-right: 1px solid black;
      animation: borderFade 12s infinite linear;
      filter: saturate(300%);
    }
    .clock-digit:last-child {
      border-right: none;
    }
    @keyframes borderFade {
      0% { border-color: black; }
      50% { border-color: white; }
      100% { border-color: black; }
    }
  `;

  return (
    <>
      <style>{styles}</style>
      <div style={containerStyle}>
        {numbers.map((num, idx) => {
          const size = scaleDigit(num);
          const bgColor = getGray(num.value, num.max);

          return (
            <div
              key={idx}
              className="clock-digit"
              style={{
                flex: `${size} 1 0`,
                fontSize: `${size}vw`,
                backgroundColor: bgColor,
              }}
            >
              {num.value}
            </div>
          );
        })}
      </div>
    </>
  );
};

export default HorizontalProportionalGradientClock;

