  ];

  return (
    <article style={comicStyle}>
      {panels.map((panel, idx) => (
        <div
          key={idx}
          style={{
            ...panelBaseStyle,
            flexBasis: panel.flexBasis,
            backgroundColor: panel.background.backgroundColor,
