import React, { useState, useEffect } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';

// Import number images
import one from '@/assets/images/2025/25-10/25-10-01/1.png';
import two from '@/assets/images/2025/25-10/25-10-01/12.png';
import three from '@/assets/images/2025/25-10/25-10-01/11.png';
import four from '@/assets/images/2025/25-10/25-10-01/10.png';
import five from '@/assets/images/2025/25-10/25-10-01/9.png';
import six from '@/assets/images/2025/25-10/25-10-01/8.png';
import seven from '@/assets/images/2025/25-10/25-10-01/7.png';
import eight from '@/assets/images/2025/25-10/25-10-01/6.png';
import nine from '@/assets/images/2025/25-10/25-10-01/5.png';
import ten from '@/assets/images/2025/25-10/25-10-01/4.png';
import eleven from '@/assets/images/2025/25-10/25-10-01/3.png';
import twelve from '@/assets/images/2025/25-10/25-10-01/2.png';

// Clock face
import clockFace from '@/assets/images/2025/25-10/25-10-01/gears.webp';

// Background video and fallback
import backgroundVideo from '@/assets/images/2025/25-10/25-10-01/small.mp4';
import fallbackGif from '@/assets/images/2025/25-10/25-10-01/small.webp';

export default function ImageAnalogClock() {
  const [time, setTime] = useState(new Date());
  const [rotation, setRotation] = useState<number>(0);

  // Update time smoothly
  useEffect(() => {
    const interval = setInterval(() => setTime(new Date()), 16);
    return () => clearInterval(interval);
  }, []);

  // Rotate face slowly
  useEffect(() => {
    const rotateInterval = setInterval(() => {
      setRotation((prev) => (prev - 0.1) % 360);
    }, 16);
    return () => clearInterval(rotateInterval);
  }, []);

  const clockSize = 'min(80vw, 80vh)';
  const center = { x: 50, y: 50 };
  const radius = 38;

  const numberImages = [
    { src: one, angle: 0, width: '30%', height: '30%' },
    { src: two, angle: 30, width: '20%', height: '20%' },
    { src: three, angle: 60, width: '20%', height: '20%' },
    { src: four, angle: 90, width: '20%', height: '20%' },
    { src: five, angle: 120, width: '25%', height: '25%' },
    { src: six, angle: 150, width: '24%', height: '24%' },
    { src: seven, angle: 180, width: '24%', height: '24%' },
    { src: eight, angle: 210, width: '20%', height: '20%' },
    { src: nine, angle: 240, width: '22%', height: '22%' },
    { src: ten, angle: 270, width: '24%', height: '24%' },
    { src: eleven, angle: 300, width: '21%', height: '21%' },
    { src: twelve, angle: 330, width: '21%', height: '21%' },
  ];

  const hours = time.getHours() % 12;
  const minutes = time.getMinutes();
  const seconds = time.getSeconds() + time.getMilliseconds() / 1000;

  const hourAngle = (hours + minutes / 60) * 30;
  const minuteAngle = (minutes + seconds / 60) * 6;
  const secondAngle = seconds * 6;

  const metallicHandStyle = (width, length, angle) => ({
    position: 'absolute',
    width: width,
    height: length,
    top: '50%',
    left: '50%',
    transformOrigin: '50% 100%',
    transform: `translate(-50%, -100%) rotate(${angle}deg)`,
    background: `linear-gradient(
      135deg,
      #FDF8F8 0%,
      #B3B0B0 25%,
      #fff 50%,
      #939292 75%,
      #FAF7F7 100%
    )`,
    borderRadius: '0.5rem',
    boxShadow: `
      -2px -2px 0 #E2E2E1,
      2px 2px 0 #1E1E1E,
      0 0.3rem 0.5rem rgba(0,0,0,0.6),
      inset 0 0.15rem 0.3rem rgba(255,255,255,0.8),
      inset 0 -0.15rem 0.3rem rgba(0,0,0,0.4),
      0 0 8px #fff,
      0 0 12px #bbb
    `,
    pointerEvents: 'none',
    border: '0.05rem solid #999',
    opacity: 1.0,
  });

  const metallicNumberStyle = (width, height) => ({
    position: 'absolute',
    width: width,
    height: height,
    left: '50%',
    top: '50%',
    transform: 'translate(-50%, -50%)',
    objectFit: 'contain',
    filter: `
      grayscale(80%) 
      contrast(80%) 
      brightness(1.1)
      drop-shadow(2px 2px 0 #1E1E1E)
      drop-shadow(-2px -2px 0 #E2E2E1)
    `,
    opacity: 0.95,
  });

  return (
    <div
      style={{
        position: 'relative',
        width: '100vw',
        height: '100dvh',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        overflow: 'hidden',
        isolation: 'isolate',
        backgroundColor: '#111',
      }}
    >
      {/* Video background */}
      <video
        autoPlay
        loop
        muted
        playsInline
        style={{
          position: 'absolute',
          width: '100vw',
          height: '100dvh',
          objectFit: 'cover',
          filter: 'saturate(0.3) contrast(1.1) brightness(1.3)',
          zIndex: -2,
        }}
      >
        <source src={backgroundVideo} type="video/mp4" />
      </video>

      {/* Fallback */}
      <img
        decoding="async"
        loading="lazy"
        src={fallbackGif}
        alt="Fallback background"
        style={{
          position: 'absolute',
          width: '100vw',
          height: '100dvh',
          objectFit: 'cover',
          zIndex: -3,
        }}
      />

      {/* Clock container */}
      <div
        style={{
          position: 'relative',
          width: 'min(90vw, 90vh)',
          height: 'min(90vw, 90vh)',
          borderRadius: '50%',
          overflow: 'visible',
          isolation: 'isolate',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
        }}
      >
        {/* Rotating clock face */}
        <div
          style={{
            position: 'absolute',
            width: clockSize,
            height: clockSize,
            backgroundImage: `url(${clockFace})`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            filter: 'grayscale(95%)',
            opacity: 0.9,
            zIndex: -1,
            transform: `rotate(${rotation}deg)`,
            transformOrigin: '50% 50%',
            transition: 'transform 0.016s linear',
          }}
        />

        {/* Numbers */}
        {numberImages.map((num, idx) => {
          const angleRad = (num.angle - 90) * (Math.PI / 180);
          const x = center.x + radius * Math.cos(angleRad);
          const y = center.y + radius * Math.sin(angleRad);

          return (
            <img
              decoding="async"
              loading="lazy"
              key={idx}
              src={num.src}
              alt={`number ${idx + 1}`}
              style={{
                ...metallicNumberStyle(num.width, num.height),
                left: `${x}%`,
                top: `${y}%`,
              }}
            />
          );
        })}

        {/* Hands */}
        <div style={metallicHandStyle('0.8rem', '24dvh', hourAngle)} />
        <div style={metallicHandStyle('0.5rem', '36dvh', minuteAngle)} />
        <div style={metallicHandStyle('0.15rem', '40dvh', secondAngle)} />
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import gridImage from '@/assets/images/2025/25-10/25-10-02/lan.gif';

// Counting rod digit map
const digitMap = {
  0: '▫',
  1: '\u{1D360}',
  2: '\u{1D361}',
  3: '\u{1D362}',
  4: '\u{1D363}',
  5: '\u{1D364}',
  6: '\u{1D365}',
  7: '\u{1D366}',
  8: '\u{1D367}',
  9: '\u{1D369}',
};

const toCountingRod = (number) =>
  String(number)
    .padStart(2, '0')
    .split('')
    .map((digit) => digitMap[digit]);

const DigitalClock: React.FC = () => {
  const [time, setTime] = useState(new Date());
  const [digitOpacities, setDigitOpacities] = useState<any>({
    hours: [1, 1],
    minutes: [1, 1],
    seconds: [1, 1],
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const newTime = new Date();
      const newHours = toCountingRod(newTime.getHours());
      const newMinutes = toCountingRod(newTime.getMinutes());
      const newSeconds = toCountingRod(newTime.getSeconds());
      const prevHours = toCountingRod(time.getHours());
      const prevMinutes = toCountingRod(time.getMinutes());
      const prevSeconds = toCountingRod(time.getSeconds());

      // Fade digits that changed
      setDigitOpacities({
        hours: prevHours.map((d, i) => (d !== newHours[i] ? 0 : 1)),
        minutes: prevMinutes.map((d, i) => (d !== newMinutes[i] ? 0 : 1)),
        seconds: prevSeconds.map((d, i) => (d !== newSeconds[i] ? 0 : 1)),
      });

      setTime(newTime);

      // Fade digits back in after transition
      setTimeout(() => {
        setDigitOpacities({
          hours: [1, 1],
          minutes: [1, 1],
          seconds: [1, 1],
        });
      }, 300);
    }, 1000);

    return () => clearInterval(timer);
  }, [time]);

  const hours = toCountingRod(time.getHours());
  const minutes = toCountingRod(time.getMinutes());
  const seconds = toCountingRod(time.getSeconds());

  // Stable red background for all digits
  const digitBackgroundStyle = {
    display: 'inline-flex',
    justifyContent: 'center',
    alignItems: 'center',
    width: '12vw',
    height: '20vw',
    background: 'rgba(178,34,34,0.5)', // stable red
    boxShadow: '0 0 7vw #CB4F3FFF',
    margin: '-0.4vw',
  };

  const digitTextStyle = {
    fontSize: '20vw',
    fontFamily: "'KaiTi', 'STKaiti', serif",
    color: '#D1EEC9FF',
    textShadow: '2px 2px 0 #000000, -2px -2px 0 #000000',
    transition: 'opacity 0.3s ease',
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        height: '100dvh',
        width: '100vw',
        background: `
          radial-gradient(circle at 30% 20%, rgba(255,15,0,0.9) 0%, transparent 50%),
          radial-gradient(circle at 70% 80%, rgba(278,34,34,0.8) 0%, transparent 50%),
          linear-gradient(135deg, #8B1E00FF 0%, #E64106FF 50%, #CE0808FF 100%)
        `,
        overflow: 'hidden',
        position: 'relative',
        fontFamily: "'KaiTi', 'STKaiti', serif",
      }}
    >
      <div
        style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%) scaleX(-1)',
          width: '100vw',
          height: '120dvh',
          backgroundImage: `url(${gridImage})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          backgroundRepeat: 'no-repeat',
          opacity: 0.4,
          zIndex: 1,
        }}
      />

      <div
        style={{
          display: 'flex',
          gap: '1vw',
          padding: '2vw',
          background: 'rgba(0,0,0,0.3)',
          zIndex: 10,
          boxShadow: '0 0 5rem rgba(255,215,0,0.3)',
        }}
      >
        {hours.map((d, i) => (
          <div key={`h${i}`} style={digitBackgroundStyle}>
            <span
              style={{ ...digitTextStyle, opacity: digitOpacities.hours[i] }}
            >
              {d}
            </span>
          </div>
        ))}
        {minutes.map((d, i) => (
          <div key={`m${i}`} style={digitBackgroundStyle}>
            <span
              style={{ ...digitTextStyle, opacity: digitOpacities.minutes[i] }}
            >
              {d}
            </span>
          </div>
        ))}
        {seconds.map((d, i) => (
          <div key={`s${i}`} style={digitBackgroundStyle}>
            <span
              style={{ ...digitTextStyle, opacity: digitOpacities.seconds[i] }}
            >
              {d}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default DigitalClock;

