  }, [languages.length]);

  // --- Time to words conversion ---
  type LangCode = keyof typeof translations;
  const timeToWords = (date: Date, lang: LangCode) => {
    const t = translations[lang]!;
    let hours = date.getHours(),
      minutes = date.getMinutes(),
      seconds = date.getSeconds();

    let relation = t.after;
    let displayMinutes = minutes;
    let displaySeconds = seconds;

    let displayHour = hours % 12 === 0 ? 12 : hours % 12;

    if (minutes > 30 || (minutes === 30 && seconds > 0)) {
      relation = t.before;
      displayMinutes = 60 - minutes;
      displaySeconds = seconds > 0 ? 60 - seconds : 0;
      const nextHour = (hours + 1) % 24;
      displayHour = nextHour % 12 === 0 ? 12 : nextHour % 12;
    }

    const lines = [];
    if (displayMinutes > 0)
      lines.push(
        `${t.nowItIs} ${displayMinutes} ${pluralize(
          displayMinutes,
          t.minute[0],
          t.minute[1],
        )}`,
      );
    if (displaySeconds > 0)
      lines.push(
        displayMinutes > 0
          ? `${t.and} ${displaySeconds} ${pluralize(
              displaySeconds,
              t.second[0],
              t.second[1],
            )}`
          : `${t.itIs} ${displaySeconds} ${pluralize(
              displaySeconds,
              t.second[0],
              t.second[1],
            )}`,
      );
    lines.push(`${relation} ${displayHour} ${t.oclock}`);
    return lines;
  };

  const lang = (languages[langIndex] || 'en') as LangCode;
  const dir = translations[lang]?.dir || 'ltr';
  const lines = timeToWords(now, lang);

  const containerStyle: React.CSSProperties = {
    width: '100vw',
    height: '100dvh',
    position: 'relative',
    overflow: 'hidden',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    direction: dir as 'ltr' | 'rtl',
  };

  const backgroundStyle: React.CSSProperties = {
    position: 'absolute',
    inset: 0,
    width: '100%',
    height: '100%',
    backgroundImage: `url(${backgroundImage})`,
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    zIndex: 0,
  };

  const textStyle: React.CSSProperties = {
    position: 'relative',
    zIndex: 1,
    fontFamily: "'LatinFont', sans-serif",
    fontSize: '2rem',
    color: '#fff',
    textAlign: 'center',
    textShadow: '0 2px 4px rgba(0, 0, 0, 0.8)',
    padding: '1rem',
    lineHeight: 1.5,
  };

  return (
    <div style={containerStyle} aria-live="polite">
      <div style={backgroundStyle} />
      <div style={textStyle}>
        {lines.map((line, i) => (
          <div key={i}>{line}</div>
        ))}
      </div>
    </div>
  );
}

