// MediaClock.jsx
import React, { useEffect, useRef, useState, useMemo } from 'react';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import bgVideo from '@/assets/images/2025/25-10/25-10-18/total.mp4';
import fallbackImg from '@/assets/images/2025/25-10/25-10-18/tot.webp';
import font_20251018 from '@/assets/fonts/2025/25-10-18-tot.ttf?url';

export default function MediaClock() {
  const [mediaReady, setMediaReady] = useState<boolean>(false);
  const [videoFailed, setVideoFailed] = useState<boolean>(false);
  const [time, setTime] = useState<string>('--:--');
  const videoRef = useRef(null);

  const backgroundShiftX = '49%';
  const backgroundShiftY = 'center';

  const fontConfigs = useMemo(() => [
    { fontFamily: 'SereneFont', fontUrl: font_20251018 }
  ], []);

  useSuspenseFontLoader(fontConfigs);

  // Update time
  useEffect(() => {
    function updateTime() {
      const d = new Date();
      const hh = String(d.getHours()).padStart(2, '0');
      const mm = String(d.getMinutes()).padStart(2, '0');
      setTime(`${hh}${mm}`);
    }
    updateTime();
    const id = setInterval(updateTime, 60 * 1000);
    return () => clearInterval(id);
  }, []);

  const handleVideoLoaded = () => setMediaReady(true);
  const handleVideoError = () => {
    console.warn('Video failed to load, switching to fallback image.');
    setVideoFailed(true);
  };
  const handleImageLoad = () => setMediaReady(true);

  return (
    <div
      style={{
        height: '100dvh',
        width: '100vw',
        overflow: 'hidden',
        position: 'relative',
        backgroundColor: '#F9F985FF',
      }}
    >
      {/* BACKGROUND MEDIA */}
      {!videoFailed ? (
        <video
          ref={videoRef}
          src={bgVideo}
          muted
          autoPlay
          loop
          playsInline
          onLoadedData={handleVideoLoaded}
          onError={handleVideoError}
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            height: '100dvh',
            width: '100vw',
            objectFit: 'cover',
            objectPosition: `${backgroundShiftX} ${backgroundShiftY}`,
            zIndex: 0,
          }}
        />
      ) : (
        <img
          decoding="async"
          loading="lazy"
          src={fallbackImg}
          alt=""
          onLoad={handleImageLoad}
          onError={() => setMediaReady(true)}
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            height: '100dvh',
            width: '100vw',
            objectFit: 'cover',
