  width: '100%',
  height: '100%',
  objectFit: 'cover',
  zIndex: 0,
  pointerEvents: 'none',
};

const clockContainerStyle: React.CSSProperties = {
  position: 'absolute',
  bottom: '20px',
  width: '100%',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  zIndex: 1,
  animation: `${FLOAT_NAME} 26.3s linear infinite`,
  willChange: 'transform',
};

