  const [skyGradient, setSkyGradient] = useState<any>('');
  const [skyPhrase, setSkyPhrase] = useState<any>('');
  const [fade, setFade] = useState<boolean>(false); // fade controlled after fonts load
  const [inverseGradient, setInverseGradient] = useState(
    'linear-gradient(to bottom, #fff 0%, #fff 100%)',
  );
  const [fontsLoaded, setFontsLoaded] = useState<boolean>(false);

  const index1 = useRef(0);
  const index2 = useRef(0);
  const index3 = useRef(0);

  // Alphabetically sorted arrays (same as your original)
  const adjectives1 = [
    'a whimsically',
    'a softly-harmonious',
    'a joyfully',
    'a gracefully',
    'a miraculously',
    'a blissfully',
    'a enchantingly',
