              backgroundImage: inverseGradient,
              WebkitBackgroundClip: 'text',
              backgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              position: 'relative',
            }}
          >
            {localTime}
          </div>
        </div>

        {/* Phrase */}
        <div style={{ position: 'relative', display: 'inline-block' }}>
          <div
