import React, { useEffect, useRef, useState } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import bgVideo from '@/assets/images/2025/25-11/25-11-02/swim.mp4';
import fallbackImg from '@/assets/images/2025/25-11/25-11-02/swim.webp';
import fontFile2025_11_04 from '@/assets/fonts/2025/25-11-02-sperm.ttf'; // Custom scientific font

export default function MonarchScene() {
  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'MedTech2025_11_04',
      fontUrl: fontFile2025_11_04,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  const videoRef = useRef(null);
  const [videoFailed, setVideoFailed] = useState<boolean>(false);
  const [videoStyle, setVideoStyle] = useState<Record<string, any>>({});
  const [time, setTime] = useState(new Date());
  const [fontLoaded, setFontLoaded] = useState<boolean>(fontsLoaded);

  // Font loading handled by useMultipleFontLoader

  // Adjust background video scaling to ensure full coverage
  const adjustVideoPosition = () => {
    const video = videoRef.current;
    if (!video) return;

    const filterSettings = `
      hue-rotate(105deg)
      saturate(1.6)
      brightness(0.9)
      contrast(1.2)
    `;

    // Always cover the entire viewport
    setVideoStyle({
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      objectFit: 'cover',
      zIndex: 0,
      filter: filterSettings,
      transition: 'filter 0.5s ease',
      minWidth: '100%',
      minHeight: '100%',
    });
  };

  const handleVideoLoaded = () => adjustVideoPosition();
  const handleVideoError = () => setVideoFailed(true);

  useEffect(() => {
    window.addEventListener('resize', adjustVideoPosition);
    return () => window.removeEventListener('resize', adjustVideoPosition);
  }, []);

  // Update time every 25ms
  useEffect(() => {
    const interval = setInterval(() => setTime(new Date()), 25);
    return () => clearInterval(interval);
  }, []);

  const h = String(time.getHours()).padStart(2, '0');
  const m = String(time.getMinutes()).padStart(2, '0');
  const s = String(time.getSeconds()).padStart(2, '0');
  const ms = String(time.getMilliseconds()).padStart(3, '0');

  return (
    <div
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100vw',
        height: '100vh',
        overflow: 'hidden',
        backgroundColor: '#000',
        fontFamily: "'MedTech2025_11_04', monospace",
      }}
    >
      {/* Background Video or Fallback Image */}
      {!videoFailed ? (
        <video
          ref={videoRef}
          src={bgVideo}
          muted
          autoPlay
          loop
          playsInline
          onLoadedData={handleVideoLoaded}
          onError={handleVideoError}
          style={videoStyle}
        />
      ) : (
        <img
          decoding="async"
          loading="lazy"
          src={fallbackImg}
          alt=""
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            zIndex: 0,
            filter: `
              hue-rotate(125deg)
              saturate(1.6)
              brightness(1.1)
              contrast(1.2)
            `,
            minWidth: '100%',
            minHeight: '100%',
          }}
        />
      )}

      {/* Centered Vertical Clock */}
      <div
        style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          color: '#00FFFF',
          textShadow: '0 0 1vh #00FFFF',
          userSelect: 'none',
          zIndex: 10,
          width: '90vw',
          opacity: fontLoaded ? 1 : 0,
          transition: 'opacity 0.6s ease',
        }}
      >
        <div style={timeRowStyle('15vh')}>{h}</div>
        <div style={timeRowStyle('15vh')}>{m}</div>
        <div style={timeRowStyle('15vh')}>{s}</div>
        <div style={timeRowStyle('15vh')}>{ms}</div>
      </div>
    </div>
  );
}

const timeRowStyle = (fontSize, opacity = 1) => ({
  fontSize,
  fontWeight: 'bold',
  letterSpacing: '0.3rem',
  textAlign: 'center',
  minWidth: '10rem',
  opacity,
});

