          zIndex: 2,
          width: clockSize,
          height: clockSize,
          opacity: 0.7,
          borderRadius: '50%',
          animation: 'hurricaneRock 5s ease-in-out infinite',
          transformStyle: 'preserve-3d',
        }}
      >
        {fontsLoaded && <ClockFace />}
      </div>

      {/* Styles */}
      <style>{`
        @keyframes hurricaneRock {
          0% { transform: translate(-50%, -50%) rotateZ(-35deg) rotateX(10deg) rotateY(8deg) scale(0.9); }
          10% { transform: translate(-50%, -50%) rotateZ(30deg) rotateX(-8deg) rotateY(-10deg) scale(1.1); }
          20% { transform: translate(-50%, -50%) rotateZ(-28deg) rotateX(12deg) rotateY(9deg) scale(0.95); }
          30% { transform: translate(-50%, -50%) rotateZ(32deg) rotateX(-10deg) rotateY(-12deg) scale(1.08); }
          40% { transform: translate(-50%, -50%) rotateZ(-30deg) rotateX(8deg) rotateY(10deg) scale(0.97); }
          50% { transform: translate(-50%, -50%) rotateZ(28deg) rotateX(-12deg) rotateY(-8deg) scale(1.05); }
          60% { transform: translate(-50%, -50%) rotateZ(-32deg) rotateX(10deg) rotateY(12deg) scale(0.94); }
          70% { transform: translate(-50%, -50%) rotateZ(35deg) rotateX(-8deg) rotateY(-10deg) scale(1.1); }
          80% { transform: translate(-50%, -50%) rotateZ(-30deg) rotateX(12deg) rotateY(8deg) scale(0.95); }
          90% { transform: translate(-50%, -50%) rotateZ(32deg) rotateX(-10deg) rotateY(-12deg) scale(1.08); }
          100% { transform: translate(-50%, -50%) rotateZ(-35deg) rotateX(10deg) rotateY(8deg) scale(0.9); }
        }

        .brass-text {
          background: linear-gradient(
            135deg,
            #b58e33 0%,
            #DEC05BFF 30%,
            #FFFACD 50%,
            #996515 70%,
            #b58e33 100%
          );
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          text-shadow: 0 0 2px rgba(255, 220, 120, 0.5);
        }

      `}</style>
    </div>
  );
}

// --- ClockFace Component ---
function ClockFace() {
  const hourRef = useRef(null);
  const minuteRef = useRef(null);
  const secondRef = useRef(null);

  useEffect(() => {
    const updateClock = () => {
      const now = new Date();
      const seconds = now.getSeconds();
      const minutes = now.getMinutes();
      const hours = now.getHours() % 12;

      const secDeg = seconds * 6;
      const minDeg = minutes * 6 + seconds * 0.1;
      const hourDeg = hours * 30 + minutes * 0.5;

      if (hourRef.current)
        hourRef.current.style.transform = `rotate(${hourDeg}deg)`;
      if (minuteRef.current)
        minuteRef.current.style.transform = `rotate(${minDeg}deg)`;
      if (secondRef.current)
        secondRef.current.style.transform = `rotate(${secDeg}deg)`;
    };

    updateClock();
    const interval = setInterval(updateClock, 1000);
    return () => clearInterval(interval);
  }, []);

  const brassHand = (widthVmin, heightVmin, shadow) => ({
    position: 'absolute',
    bottom: '50%',
    left: '50%',
    transformOrigin: 'bottom center',
    width: `${widthVmin}vmin`,
    height: `${heightVmin}vmin`,
    background:
      'linear-gradient(180deg, #E7C970FF 0%, #b8860b 50%, #5a3e0a 100%)',
    borderRadius: '0.5vmin',
    boxShadow: shadow,
  });

  const mainNumbers = [
    { num: 12, angle: 0 },
    { num: 3, angle: 90 },
    { num: 6, angle: 180 },
    { num: 9, angle: 270 },
  ];

  return (
    <div
      className="clock-glow"
      style={{
        fontFamily: 'Nautical, sans-serif',
        width: '100%',
        height: '100%',
        position: 'relative',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      {mainNumbers.map(({ num, angle }) => {
        const x = 40 * Math.sin((angle * Math.PI) / 180);
        const y = -40 * Math.cos((angle * Math.PI) / 180);
        return (
          <div
            key={num}
            className="brass-text"
            style={{
              position: 'absolute',
              left: `calc(50% + ${x}%)`,
              top: `calc(50% + ${y}%)`,
              transform: 'translate(-50%, -50%)',
              fontSize: 'clamp(6vmin, 10vmin, 12vmin)',
            }}
          >
            {num}
          </div>
        );
      })}

      <div
        ref={hourRef}
        style={brassHand(
          1.5,
          20,
          'inset 0 0 0.5rem #2a1b00, 0 0 1rem rgba(255,200,100,0.5)',
        )}
      />
      <div
        ref={minuteRef}
        style={brassHand(
          1,
          30,
          'inset 0 0 0.3rem #3a2b00, 0 0 1rem rgba(255,200,80,0.4)',
        )}
      />
      <div
        ref={secondRef}
        style={brassHand(
          0.5,
          30,
          'inset 0 0 0.2rem #4a3400, 0 0 1rem rgba(255,200,80,0.4)',
        )}
      />
    </div>
  );
}

