      </div>
    );
  }

  // Time math
  const seconds = time.getSeconds() + time.getMilliseconds() / 1000;
  const minutes = time.getMinutes() + seconds / 60;
  const hours = (time.getHours() % 12) + minutes / 60;

  const secondDeg = seconds * 6;
  const minuteDeg = minutes * 6;
  const hourDeg = hours * 30;

  const clockSize = '90vh';
  const numberSize = '15vh';
  const handWidth = '10vmin';
  const hourHandLength = '30vmin';
  const minuteHandLength = '38vmin';
  const secondHandLength = '42vmin';
  const radius = '32vmin';

  const numbers = [
    { src: twelve, angle: 0 },
    { src: one, angle: 30 },
    { src: two, angle: 60 },
    { src: three, angle: 90 },
    { src: four, angle: 120 },
    { src: five, angle: 150 },
    { src: six, angle: 180 },
    { src: seven, angle: 210 },
    { src: eight, angle: 240 },
    { src: nine, angle: 270 },
    { src: ten, angle: 300 },
    { src: eleven, angle: 330 },
  ];

  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        overflow: 'hidden',
        background: '#000',
      }}
    >
      {/* Background layers */}
      <div
        style={{
          position: 'absolute',
          inset: 0,
          backgroundImage: `url(${extraBg})`,
          backgroundSize: 'cover',
          filter: 'brightness(0.5) hue-rotate(230deg)',
          zIndex: 1,
        }}
      />

      <div
        style={{
          position: 'absolute',
          inset: 0,
          backgroundImage: `url(${pageBackground})`,
          backgroundSize: '100% 100%',
          zIndex: 6,
        }}
      />

      {/* Clock */}
      <div
        style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 5,
        }}
      >
        <div
          style={{
            width: clockSize,
            height: clockSize,
            position: 'relative',
          }}
        >
          {numbers.map(({ src, angle }, i) => {
            const rad = (angle * Math.PI) / 180;
            return (
              <img
                decoding="async"
                loading="lazy"
                key={i}
                src={src}
                style={{
                  position: 'absolute',
                  width: numberSize,
                  height: numberSize,
                  left: `calc(50% + ${radius} * ${Math.sin(rad)} - ${numberSize} / 2)`,
                  top: `calc(50% - ${radius} * ${Math.cos(rad)} - ${numberSize} / 2)`,
                }}
              />
            );
          })}

          <img
            decoding="async"
            loading="lazy"
            src={hourHand}
            style={{
              position: 'absolute',
              width: handWidth,
              height: hourHandLength,
              left: `calc(50% - ${handWidth} / 2)`,
              top: `calc(50% - ${hourHandLength} * 0.75)`,
              transform: `rotate(${hourDeg}deg)`,
              transformOrigin: 'center 75%',
            }}
          />

          <img
            decoding="async"
            loading="lazy"
            src={minuteHand}
            style={{
              position: 'absolute',
              width: handWidth,
              height: minuteHandLength,
              left: `calc(50% - ${handWidth} / 2)`,
              top: `calc(50% - ${minuteHandLength} * 0.75)`,
              transform: `rotate(${minuteDeg}deg)`,
              transformOrigin: 'center 75%',
            }}
          />

          <img
            decoding="async"
            loading="lazy"
            src={secondHand}
            style={{
              position: 'absolute',
              width: handWidth,
              height: secondHandLength,
              left: `calc(50% - ${handWidth} / 2)`,
              top: `calc(50% - ${secondHandLength} * 0.75)`,
              transform: `rotate(${secondDeg}deg)`,
              transformOrigin: 'center 75%',
            }}
          />
        </div>
      </div>

      {loadingError && (
        <div
          style={{
            position: 'fixed',
            bottom: 20,
            left: '50%',
            transform: 'translateX(-50%)',
            color: '#ff4444',
          }}
        >
          {loadingError}
        </div>
      )}
    </div>
  );
};

export default Clock;

