  {
    fontFamily: 'ClockFont',
    fontUrl: font2025_11_18,
  },
];

export default function MarsDigitalClock() {
  const [time, setTime] = useState(new Date());
  const [fontLoaded, setFontLoaded] = useState<boolean>(false);
  const rafRef = useRef(null);

  useEffect(() => {
    let cancelled = false;
    const font = new FontFace('ClockFont', `url(${font2025_11_18})`, {
      style: 'normal',
      weight: '400',
    });

    font
      .load()
      .then((loaded) => {
        if (cancelled) return;
        document.fonts.add(loaded);
        setFontLoaded(true);
      })
      .catch(() => {
        // In case of error, still show the clock with fallback font
        if (!cancelled) setFontLoaded(true);
      });

    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    let mounted = true;
    const loop: React.FC = () => {
      if (!mounted) return;
      setTime(new Date());
      rafRef.current = setInterval(() => setTime(new Date()), 100);
    };
    rafRef.current = setInterval(() => setTime(new Date()), 100);
    return () => {
      mounted = false;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
