    };
    intervalId = setInterval(animate, 50);
    return () => clearInterval(intervalId);
  }, []);

  const now = time;

  // Degrees
  const totalHours =
    now.getHours() +
    now.getMinutes() / 60 +
    now.getSeconds() / 3600 +
    now.getMilliseconds() / 3600000;

  const totalMinutes =
    now.getMinutes() + now.getSeconds() / 60 + now.getMilliseconds() / 60000;

  const totalSeconds = now.getSeconds() + now.getMilliseconds() / 1000;

  const hourDeg = totalHours * 30;
  const minuteDeg = totalMinutes * 6;
  const secondDeg = totalSeconds * 6;

  return (
    <div style={outerContainerStyle}>
      <div style={clockContainerStyle}>
        {/* Hour hand */}
        <img
          decoding="async"
          loading="lazy"
          src={hourHand}
          alt="hour"
          style={handStyle(hourDeg, 18, 24)}
        />

        {/* Minute hand (restored) */}
        <img
          decoding="async"
          loading="lazy"
          src={minuteHand}
          alt="minute"
          style={handStyle(minuteDeg, 20, 32)}
        />

        {/* Second hand */}
        <img
          decoding="async"
          loading="lazy"
          src={secondHand}
          alt="second"
          style={handStyle(secondDeg, 16, 33)}
        />
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import bgImage from '@/assets/images/2025/25-12/25-12-09/muybridge.webp';
import customFont_2025_1210 from '@/assets/fonts/2025/25-12-09-muy.ttf?url';
import { useSuspenseFontLoader } from '@/utils/fontLoader';

const elementColor = '#BBA8C8FF';

const digitBoxStyle = {
  position: 'relative',
  width: 'clamp(28px, 8vw, 48px)',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  fontFamily: 'MuybridgeFont, serif',
  fontSize: 'clamp(44px, 32vw, 68px)',
  color: elementColor,
  textShadow: '0.5px 0.5px 0px black, -0.5px -0.5px 0px white',
  flexShrink: 1,
  minWidth: 0,
  overflow: 'hidden',
};

export default function DigitalClock() {
  const [time, setTime] = useState(new Date());
  const [fontLoaded, setFontLoaded] = useState<boolean>(false);

  useEffect(() => {
    // Load font before showing content
    const font = new FontFace('MuybridgeFont', `url(${customFont_2025_1210})`);

    font
      .load()
      .then(() => {
        document.fonts.add(font);
        setFontLoaded(true);
      })
      .catch((err) => {
        console.error('Font loading failed:', err);
        setFontLoaded(true); // Show content anyway after error
      });
  }, []);

  useEffect(() => {
    if (!fontLoaded) return;
    const interval = setInterval(() => setTime(new Date()), 100);
    return () => clearInterval(interval);
  }, [fontLoaded]);

  const containerStyle = {
    position: 'fixed',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    width: '100%',
    height: '100%',
    minHeight: '-webkit-fill-available',
    backgroundImage: `url(${bgImage})`,
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    backgroundColor: '#090909FF',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    overflow: 'hidden',
    touchAction: 'manipulation',
    WebkitOverflowScrolling: 'touch',
    overscrollBehavior: 'none',
    opacity: fontLoaded ? 1 : 0,
    transition: 'opacity 0.3s ease-in',
  };

  const clockContainerStyle = {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontFamily: 'MuybridgeFont, serif',
    width: '100%',
    maxWidth: '100vw',
    boxSizing: 'border-box',
    transform: 'scale(0.9)',
    position: 'absolute',
    bottom: '18vh',
    left: 0,
    right: 0,
  };

  const separatorStyle = {
    fontSize: 'clamp(34px, 22vw, 58px)',
    color: elementColor,
    lineHeight: 1,
    paddingBottom: '1.5vw',
    flexShrink: 0,
  };

  const hours = String(time.getHours()).padStart(2, '0');
  const minutes = String(time.getMinutes()).padStart(2, '0');
  const seconds = String(time.getSeconds()).padStart(2, '0');

  return (
    <div style={containerStyle}>
      <style>{`
        @font-face {
          font-family: 'MuybridgeFont';
          src: url(${customFont_2025_1210}) format('opentype');
          font-display: block;
        }
        @media screen and (-webkit-min-device-pixel-ratio: 0) {
          * {
            -webkit-text-size-adjust: 100%;
            text-size-adjust: 100%;
            -moz-text-size-adjust: 100%;
          }
        }
      `}</style>
      <div style={clockContainerStyle}>
        <div style={digitBoxStyle} aria-hidden="true">
          {hours[0]}
        </div>
        <div style={digitBoxStyle} aria-hidden="true">
          {hours[1]}
        </div>
        <div style={separatorStyle} aria-hidden="true">
          :
        </div>
        <div style={digitBoxStyle} aria-hidden="true">
          {minutes[0]}
        </div>
        <div style={digitBoxStyle} aria-hidden="true">
          {minutes[1]}
        </div>
        <div style={separatorStyle} aria-hidden="true">
          :
        </div>
        <div style={digitBoxStyle} aria-hidden="true">
          {seconds[0]}
        </div>
        <div style={digitBoxStyle} aria-hidden="true">
          {seconds[1]}
        </div>
      </div>
    </div>
  );
}

