import React, { useEffect, useState, useMemo, memo, useRef } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';
import { useSuspenseFontLoader } from '@/utils/fontLoader';

// --- Image Imports ---
import bg1 from '@/assets/images/2025/25-12/25-12-10/j.webp';
import bg2 from '@/assets/images/2025/25-12/25-12-10/jj.webp';
import portImg from '@/assets/images/2025/25-12/25-12-10/eagle.webp';
import hourHandImg from '@/assets/images/2025/25-12/25-12-10/oa.gif';
import minuteHandImg from '@/assets/images/2025/25-12/25-12-10/oak.gif';
import secondHandImg from '@/assets/images/2025/25-12/25-12-10/nk.gif';
const font251211 = '../../../assets/fonts/2025/25-12-10-jup.ttf';

// --- CONFIG ---
const CONFIG = {
  clockSize: 'min(90vw, 90vh)',
  numeralRadius: 43,
  hands: [
    { img: secondHandImg, width: '22vw', max: '200px' },
    { img: minuteHandImg, width: '28vw', max: '200px' },
    { img: hourHandImg, width: '26vw', max: '166px' },
  ],
  numerals: [
    { text: 'XII', deg: 0 },
    { text: 'III', deg: 90 },
    { text: 'VI', deg: 180 },
    { text: 'IX', deg: 270 },
  ],
  tileSize: 100,
};

// --- HOOKS ---
function useTime() {
  const [time, setTime] = useState(() => new Date());

  useEffect(() => {
    let animationFrameId;

    const updateTime: React.FC = () => {
      setTime(new Date());
    };

    // Start the interval loop
    const intervalId = setInterval(updateTime, 50);

    // Cleanup function to clear the interval when component unmounts
    return () => {
      clearInterval(intervalId);
    };
  }, []);

  return time;
}

function useClockAngles(time) {
  return useMemo(() => {
    const ms = time.getMilliseconds();
    const s = time.getSeconds() + ms / 1000;
    const m = time.getMinutes() + s / 60;
    const h = (time.getHours() % 12) + m / 60;
    return { second: s * 6, minute: m * 6, hour: h * 30 };
  }, [time]);
}

// Pre-calculate numeral positions (only once)
const NUMERAL_POSITIONS = CONFIG.numerals.map(({ text, deg }) => {
  const rad = (deg - 90) * (Math.PI / 180);
  return {
    text,
    x: 50 + CONFIG.numeralRadius * Math.cos(rad),
    y: 50 + CONFIG.numeralRadius * Math.sin(rad),
  };
});

// --- GLOBAL FONT ---
const GlobalStyles = memo(() => (
  <style>{`
    @font-face {
      font-family: 'CustomFont251211';
      src: url(${font251211}) format('truetype');
      font-display: swap;
    }
    @keyframes scrollUp {
      from { transform: translateY(0); }
      to { transform: translateY(-66.66%); }
    }
  `}</style>
));

// --- INFINITE UPWARD SCROLLING BG1 ---
const InfiniteScrollingBG = memo(() => (
  <div
    style={{
      position: 'fixed',
      inset: 0,
      overflow: 'hidden',
      zIndex: 1,
      pointerEvents: 'none',
    }}
  >
    <div
      style={{
        position: 'absolute',
        width: '100%',
        height: '300%',
        backgroundImage: `url(${bg1})`,
        backgroundSize: '100% auto',
        backgroundRepeat: 'repeat-y',
        backgroundPosition: 'center top',
        animation: 'scrollUp 19s linear infinite',
        willChange: 'transform',
      }}
    />
  </div>
));

// --- STATIC BG2 ---
const BackgroundImage2 = memo(() => (
  <div
    style={{
      position: 'fixed',
      inset: 0,
      backgroundImage: `url(${bg2})`,
      backgroundSize: 'cover',
      backgroundRepeat: 'no-repeat',
      backgroundPosition: 'center',
      zIndex: 10,
      filter: 'saturate(3.5) contrast(1.5) brightness(17.5)',
      pointerEvents: 'none',
    }}
  />
));

// --- TILED EAGLE LAYER ---
const TiledBackground = memo(() => {
  const tiles = useMemo(() => {
    const { tileSize } = CONFIG;
    const cols = Math.ceil(window.innerWidth / tileSize) + 3;
    const rows = Math.ceil(window.innerHeight / tileSize) + 3;
    const result = [];

    for (let r = -2; r < rows; r++) {
      for (let c = -2; c < cols; c++) {
        const flip = (r + c) % 2 === 1;
        result.push(
          <div
            key={`${r}-${c}`}
            style={{
              position: 'fixed',
              width: tileSize,
              height: tileSize,
              background: `url(${portImg}) center/contain no-repeat`,
              opacity: 0.7,
              filter: 'hue-rotate(190deg) saturate(9.5)',
              transform: flip ? 'scaleX(-1)' : 'none',
              left: c * tileSize - tileSize,
              top: r * tileSize - tileSize,
              zIndex: 3,
              pointerEvents: 'none',
            }}
          />,
        );
      }
    }
    return result;
  }, []);

  return <>{tiles}</>;
});

// --- NUMERAL ---
const ClockNumeral = memo(({ text, x, y }) => (
  <div
    style={{
      position: 'absolute',
      left: `${x}%`,
      top: `${y}%`,
      transform: 'translate(-50%, -50%)',
      color: '#1D97F4FF',
      fontFamily: 'CustomFont251211, serif',
      fontSize: 'clamp(5rem, 8vw, 6.5rem)',
      textShadow: '2px 2px 0px #FAC72DFF',
      zIndex: 0,
      pointerEvents: 'none',
    }}
  >
    {text}
  </div>
));

// --- CLOCK HAND ---
const ClockHand = memo(({ img, width, max, rotation }) => (
  <img
    decoding="async"
    loading="lazy"
    src={img}
    alt=""
    draggable={false}
    style={{
      position: 'absolute',
      top: '50%',
      left: '50%',
      width: `clamp(30px, ${width}, ${max})`,
      transform: `translate(-50%, -100%) rotate(${rotation}deg)`,
      transformOrigin: 'bottom center',
      zIndex: 7,
      pointerEvents: 'none',
      userSelect: 'none',
      filter:
        'hue-rotate(20deg) saturate(2) brightness(1.2) drop-shadow(2px 2px 0px #0E63EBFF)',
      willChange: 'transform',
    }}
  />
));

// --- CLOCK FACE ---
const ClockFace = memo(({ angles }) => (
  <div
    style={{
      position: 'fixed',
      top: '50%',
      left: '50%',
      width: CONFIG.clockSize,
      height: CONFIG.clockSize,
      transform: 'translate(-50%, -50%)',
      borderRadius: '50%',
      zIndex: 10,
    }}
  >
    {NUMERAL_POSITIONS.map((p, i) => (
      <ClockNumeral key={i} text={p.text} x={p.x} y={p.y} />
    ))}

    <div
      style={{
        position: 'absolute',
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%)',
      }}
    >
      {CONFIG.hands.map((h, i) => (
        <ClockHand
          key={i}
          img={h.img}
          width={h.width}
          max={h.max}
          rotation={
            i === 0 ? angles.second : i === 1 ? angles.minute : angles.hour
          }
        />
      ))}
    </div>
  </div>
));

// --- MAIN COMPONENT ---
export default function AnalogClock() {
  const time = useTime();
  const angles = useClockAngles(time);
  const preloadedRef = useRef(false);

  // Preload hand images once
  useEffect(() => {
    if (!preloadedRef.current) {
      [hourHandImg, minuteHandImg, secondHandImg].forEach((src) => {
        const img = new Image();
        img.src = src;
      });
      preloadedRef.current = true;
    }
  }, []);

  return (
    <>
      <GlobalStyles />
      <InfiniteScrollingBG />
      <BackgroundImage2 />
      <TiledBackground />
      <ClockFace angles={angles} />
    </>
  );
}

// GeologicTimeClock.jsx
import React, { useEffect, useState, useMemo } from 'react';

// Static configuration moves outside the component lifecycle
const GEOLOGIC_EVENTS = [
  { label: 'Formation of Earth', value: '4.540 Billion Years' },
  { label: 'Phanerozoic Eon Begins', value: '541 Million Years' },
  { label: 'Cenozoic Era Begins', value: '66 Million Years' },
  { label: 'Quaternary Period', value: '2.58 Million Years' },
  { label: 'Holocene Epoch', value: '11,700 Years' },
  { label: 'Proposed Anthropocene', value: '~75 Years' },
];

export default function GeologicTimeClock() {
  const [now, setNow] = useState(new Date());

  // Efficient time loop
  useEffect(() => {
    let frameId;
    const updateClock: React.FC = () => {
      setNow(new Date());
      frameId = requestAnimationFrame(updateClock);
    };
    updateClock();
    return () => cancelAnimationFrame(frameId);
  }, []);

  // Memoize the time formatting to separate data prep from rendering
  const timeData = useMemo(() => {
    // Using padding is faster and sufficient for clock digits vs Intl
    const pad = (n, w = 2) => String(n).padStart(w, '0');

    return [
      { label: 'Current Year', value: `${now.getFullYear()} C.E.` },
      {
        label: 'Current Month',
        value: now.toLocaleString('en', { month: 'long' }),
      },
      { label: 'Current Day', value: pad(now.getDate()) },
      { label: 'Current Hour', value: pad(now.getHours()) },
      { label: 'Current Minute', value: pad(now.getMinutes()) },
      { label: 'Current Second', value: pad(now.getSeconds()) },
      { label: 'Current Millisecond', value: pad(now.getMilliseconds(), 3) },
    ];
  }, [now]);

  // Merge static and dynamic events
  const timeline = useMemo(() => [...GEOLOGIC_EVENTS, ...timeData], [timeData]);

  return (
    <div
      style={{
        height: '100vh',
        width: '100vw',
        position: 'relative',
        background: 'linear-gradient(90deg, #F5C280 0%, #F0E983FF 100%)',
        overflow: 'hidden',
        fontFamily: 'system-ui, -apple-system, sans-serif',
        userSelect: 'none',
        WebkitUserSelect: 'none',
      }}
    >
      {/* Semantic list container using flexbox for even distribution */}
      <div
        style={{
          height: '100%',
          width: '100%',
          display: 'flex',
          flexDirection: 'column',
          padding:
            'env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left)',
          boxSizing: 'border-box',
        }}
      >
        {timeline.map((item, i) => (
          <TimelineRow
            key={item.label}
            label={item.label}
            value={item.value}
            isLast={i === timeline.length - 1}
          />
        ))}
      </div>
    </div>
  );
}

/**
 * TimelineRow Component
 * Extracted to isolate presentation logic and prevent layout trashing
 */
const TimelineRow = React.memo(({ label, value, isLast }) => {
  return (
    <div
      style={{
        // Flex: 1 automatically handles the vertical distribution
        // without complex JS viewport math
        flex: 1,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        width: '100%',
        maxWidth: '800px',
        margin: '0 auto',
        padding: '0.2vh 0',
        minHeight: 0, // Critical for nested flex scrolling behavior
        borderBottom: isLast ? 'none' : '1px solid rgba(17,58,102,0.2)',
      }}
    >
      {/* Label */}
      <div
        style={{
          flex: '0 0 40%',
          textAlign: 'right',
          paddingRight: '1rem',
          fontFamily: '"Playfair Display", Georgia, serif',
          // Using container queries (cqw/cqh) would be ideal future-proof,
          // but vmin is a robust fallback for fullscreen apps.
          fontSize: 'clamp(0.8rem, 2.5vmin, 2rem)',
          fontWeight: 500,
          color: '#113A66',
          whiteSpace: 'nowrap',
          textOverflow: 'ellipsis',
          overflow: 'hidden',
        }}
      >
        {label}
      </div>

      {/* Vertical divider bar */}
      <div
        style={{
          width: '0.4vmin',
          height: '60%',
          minHeight: '1rem',
          background: 'linear-gradient(to bottom, #113A66, #3D1759)',
          borderRadius: '3px',
          flexShrink: 0,
          opacity: 0.8,
        }}
      />

      {/* Value */}
      <div
        style={{
          flex: '0 0 60%',
          paddingLeft: '1rem',
          fontFamily: '"Roboto Mono", monospace',
          fontSize: 'clamp(0.8rem, 2.5vmin, 2rem)',
          color: '#3D1759',
          textAlign: 'left',
          whiteSpace: 'nowrap',
          textOverflow: 'ellipsis',
          overflow: 'hidden',
        }}
      >
        {value}
      </div>
    </div>
  );
});

import React, { useEffect, useState } from 'react';
import bgImage from './wheel.svg';

export default function AnalogBackgroundClock() {
  const [now, setNow] = useState(() => new Date());

  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 100);
    return () => clearInterval(id);
  }, []);

  const seconds = now.getSeconds() + now.getMilliseconds() / 1000;
  const minutes = now.getMinutes() + seconds / 60;
  const hours = (now.getHours() % 12) + minutes / 60;

  /* ---------------- COLOR CYCLING ---------------- */

  const [randomHueOffset] = useState(() => Math.floor(Math.random() * 360)); // Random starting color
  const cycleProgress = (Date.now() % 15000) / 15000;
  const getBrightness = (offset) =>
    (Math.sin((cycleProgress + offset) * Math.PI * 2) + 1) / 2;

  const makeHand = (brightness, width, height, rotation) => {
    const v = Math.round(brightness * 255);
    return {
      position: 'absolute',
      top: '50%',
      left: '50%',
      width,
      height,
      background: `rgb(${v},${v},${v})`,
      transformOrigin: '50% 100%',
      transform: `translate(-50%, -100%) rotate(${rotation}deg)`,
      borderRadius: '1vh',
      boxShadow: `0 4px 10px rgb(${255 - v},${255 - v},${255 - v})`,
      opacity: 0.85,
    };
  };

  const hourHand = makeHand(getBrightness(0), '2vh', '14vh', hours * 30);
  const minuteHand = makeHand(
    getBrightness(0.25),
    '1.5vh',
    '20vh',
    minutes * 6,
  );
  const secondHand = makeHand(getBrightness(0.5), '0.5vh', '30vh', seconds * 6);

  /* ---------------- BACKGROUND ---------------- */

  const hue = ((Date.now() / 60000) * 360 + randomHueOffset) % 360; // Add random offset
  const gradient = `hsl(${hue}, 100%, 50%)`;

  return (
    <>
      {/* Gradient */}
      <div
        style={{
          position: 'fixed',
          inset: 0,
          background: gradient,
          zIndex: 1,
        }}
      />
      {/* Wheel image */}
      <div
        style={{
          position: 'fixed',
          inset: 0,
          backgroundImage: `url(${bgImage})`,
          backgroundRepeat: 'no-repeat',
          backgroundPosition: 'center',
          backgroundSize: 'contain',
          zIndex: 2,
        }}
      />
      {/* Clock hands */}
      <div
        style={{
          position: 'fixed',
          inset: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 3,
        }}
      >
        <div
          style={{
            position: 'relative',
            width: '80vh',
            height: '80vh',
            borderRadius: '50%',
          }}
        >
          <div style={hourHand} />
          <div style={minuteHand} />
          <div style={secondHand} />
        </div>
      </div>
    </>
  );
}

