import React, { useEffect, useState } from 'react';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import backgroundImage from '@/assets/images/2025/25-12/25-12-18/ci.webp';
import FONT_PATH from '@/assets/fonts/2025/25-12-18-cine.ttf?url';

const TiltedReverseClock: React.FC = () => {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const id = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  // Load font
  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = `
      @font-face {
        font-family: 'speed';
        src: url(${FONT_PATH}) format('truetype');
        font-weight: normal;
        font-style: normal;
        font-display: swap;
      }
    `;
    document.head.appendChild(style);

    return () => {
      document.head.removeChild(style);
    };
  }, []);

  const hours24 = time.getHours();
  const hours12 = hours24 % 12 || 12;
  const minutes = time.getMinutes();

  const hourDigits = String(hours12);
  const minuteDigits = String(minutes).padStart(2, '0');

  return (
    <div
      style={{
        width: '100vw',
        height: '100dvh',
        background: 'black',
        position: 'relative',
        overflow: 'hidden',
      }}
    >
      <style>{`
        @keyframes flicker {
          0%, 19%, 21%, 23%, 25%, 54%, 56%, 100% { opacity: 1; }
