  }, []);

  return time;
}

// Format time with padding
function formatTime(date) {
  const pad = (n) => String(n).padStart(2, '0');
  return {
    hours: pad(date.getHours()),
    minutes: pad(date.getMinutes()),
    seconds: pad(date.getSeconds()),
