  return (
    <div style={containerStyle}>
      <style>{`
        @font-face {
          font-family: 'Cram260102';
          src: url(${fontFile}) format('truetype');
        }

        body { margin: 0; padding: 0; }

        /* The background layer with the filter applied */
        .filtered-bg::before {
          content: "";
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background-image: url(${backgroundImage});
          background-size: cover;
          background-position: center;
          background-repeat: no-repeat;
          filter: brightness(0.8) contrast(3.9) saturate(0.6);
          z-index: 1;
        }
      `}</style>

      {/* Hours Section */}
      <div style={segmentStyle} className="filtered-bg">
        <div style={textStyle}>{hours}</div>
      </div>

      {/* Minutes Section */}
      <div style={segmentStyle} className="filtered-bg">
        <div style={textStyle}>{minutes}</div>
      </div>
    </div>
  );
};

export default StretchedClock;

