import { useState, useEffect } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';
import { useMultipleFontLoader } from '@/utils/fontLoader';
import backgroundImage from '@/assets/images/2026/26-01/26-01-06/aa.jpg';
import gizaFont from '@/assets/fonts/2026/26-01-05-26-01-06-aa.ttf?url';
import aaaImage from '@/assets/images/2026/26-01/26-01-06/aaa.webp';

export default function AardvarkClock() {
  // Standardized font loading with font-display: swap to avoid FOUC
  const fontConfigs = [
    {
      fontFamily: 'Giza_20260107',
      fontUrl: gizaFont,
      options: {
        weight: 'normal',
        style: 'normal'
      }
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  const [time, setTime] = useState(new Date());
  const [totalSeconds, setTotalSeconds] = useState<number>(0);
  const [bgReady, setBgReady] = useState<boolean>(false);
  const [fontLoaded, setFontLoaded] = useState<boolean>(fontsLoaded);

  // Update fontLoaded state when fontsLoaded changes
  useEffect(() => {
    setFontLoaded(fontsLoaded);
  }, [fontsLoaded]);

  // Font loading handled by useMultipleFontLoader

  const clockLabels = [
    'a',
    'a',
    'a',
    'a',
    'a',
    'a',
    'a',
    'a',
    'a',
    'Aa',
    'Aa',
    'Aa',
  ];

  /* Clock tick */
  useEffect(() => {
    const now = new Date();
    setTime(now);
    setTotalSeconds(
      now.getHours() * 3600 + now.getMinutes() * 60 + now.getSeconds(),
    );

    const timer = setInterval(() => {
      setTime(new Date());
      setTotalSeconds((s) => s + 1);
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  // Font loading is handled by useFontLoader above - no need for duplicate logic

  // Preload background
  useEffect(() => {
    const img = new Image();
    const done = () => setBgReady(true);
    img.onload = done;
    img.onerror = done;
    img.src = backgroundImage;
    const timeout = setTimeout(done, 1200);
    return () => clearTimeout(timeout);
  }, []);

  const secDeg = (totalSeconds / 60) * 360;
  const minDeg = ((time.getMinutes() + time.getSeconds() / 60) / 60) * 360;
  const hourDeg =
    (((time.getHours() % 12) + time.getMinutes() / 60) / 12) * 360;

  const textOutline = `
    -0.5vh 0 0 #F5F9F6,
     0.3vh 0 0 #E7EDE7,
     0 -0.3vh 0 #EFEAE8,
     0  0.3vh 0 #151415
  `;

  return (
    <div
      style={{
        backgroundImage: `url(${backgroundImage})`,
        backgroundSize: '50vmin 40vmin',
        backgroundRepeat: 'repeat',
        backgroundPosition: 'center',
        backgroundAttachment: 'fixed',
        width: '100%',
        minHeight: '100dvh',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        position: 'relative',
        overflow: 'hidden',
        padding: '20px',
        boxSizing: 'border-box',
        opacity: fontLoaded && bgReady ? 1 : 0,
        visibility: fontLoaded && bgReady ? 'visible' : 'hidden',
        transition: 'opacity 0.35s ease',
      }}
    >
      {/* Corner image */}
      <img
        decoding="async"
        loading="lazy"
        src={aaaImage}
        alt=""
        style={{
          position: 'absolute',
          bottom: '0',
          right: '0',
          width: 'min(45vmin, 300px)',
          maxHeight: '90%',
          objectFit: 'contain',
          pointerEvents: 'none',
        }}
      />

      {/* CLOCK */}
      <div
        style={{
          position: 'relative',
          width: 'min(80vmin, 90%)',
          height: 'min(80vmin, 90%)',
          fontFamily: 'Giza_20260107, serif',
          color: '#F45309',
        }}
      >
        {/* Labels */}
        {clockLabels.map((label, i) => {
          const angle = (i + 1) * 30;
          const radius = 38; // vmin-based via container scaling
          const x = Math.sin((angle * Math.PI) / 180) * radius;
          const y = -Math.cos((angle * Math.PI) / 180) * radius;

          return (
            <div
              key={i}
              style={{
                position: 'absolute',
                top: '50%',
                left: '50%',
                transform: `translate(calc(-50% + ${x}vmin), calc(-50% + ${y}vmin))`,
                fontSize: 'min(13vmin, 12vw)',
                textShadow: textOutline,
                userSelect: 'none',
                lineHeight: 1,
              }}
            >
              {label}
            </div>
          );
        })}

        {/* Hour */}
        <div
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            width: '1.4vmin',
            height: '14vmin',
            background: '#F45309',
            border: '0.5vmin solid #fff',
            transformOrigin: 'bottom',
            transform: `translateX(-50%) rotate(${hourDeg}deg)`,
            borderRadius: '1vmin',
            transition: 'transform 0.5s ease-in-out',
          }}
        />

        {/* Minute */}
        <div
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            width: '0.9vmin',
            height: '24vmin',
            background: '#F45309',
            border: '0.5vmin solid #fff',
            transformOrigin: 'bottom',
            transform: `translateX(-50%) rotate(${minDeg}deg)`,
            borderRadius: '1vmin',
            transition: 'transform 0.5s ease-in-out',
          }}
        />

        {/* Second */}
        <div
          style={{
            position: 'absolute',
            bottom: '50%',
            left: '50%',
            width: '0.5vmin',
            height: '28vmin',
            background: '#F45309',
            border: '0.5vmin solid #fff',
            transformOrigin: 'bottom',
            transform: `translateX(-50%) rotate(${secDeg}deg)`,
            transition: 'transform 0.4s cubic-bezier(0.68,-0.6,0.32,1.6)',
          }}
        />
      </div>
    </div>
  );
}

