          width: 'auto',
          left: '50%',
          transform: 'translateX(-50%)',
          opacity: 0.6,
          zIndex: 2,
          filter: 'sepia(100%) hue-rotate(-30deg) saturate(400%)',
          maxHeight: '80vh',
        }}
        alt=""
      />

      {/* Clock Hands Container */}
      <div className={styles.handsContainer}>
        {/* Hour Hand (Smallest/Thickest) */}
        <img
          decoding="async"
          loading="lazy"
          src={fish}
          ref={hourHandRef}
          style={{
            ...handStyle,
            width: handSizes.hour,
            height: 'auto',
            filter: handFilter,
          }}
          alt="hour"
        />
        {/* Minute Hand (Medium) */}
        <img
          decoding="async"
          loading="lazy"
          src={fish}
          ref={minHandRef}
          style={{
            ...handStyle,
            width: handSizes.minute,
            height: 'auto',
            filter: handFilter,
          }}
          alt="minute"
        />
        {/* Second Hand (Longest/Thinnest) */}
        <img
          decoding="async"
          loading="lazy"
          src={fish}
          ref={secondHandRef}
          style={{
            ...handStyle,
            width: handSizes.second,
            height: 'auto',
            filter: handFilter,
            opacity: 0.8,
          }}
          alt="second"
        />
      </div>

      {/* Foreground Bubbles & Fish */}
      <img
        decoding="async"
        loading="lazy"
        src={bubl}
        style={{
          position: 'absolute',
          top: 0,
          left: '-22%',
          width: '144%',
          height: '110%',
          zIndex: 4,
          maxWidth: 'none',
        }}
        alt=""
      />
      <img
        decoding="async"
        loading="lazy"
        src={gfish}
        className={styles.sharedImage}
        style={{
          width: '180%',
          opacity: 0.8,
          transform: 'scaleX(-1)',
          zIndex: 7,
          maxWidth: 'none',
        }}
        alt=""
      />
    </div>
  );
};

export default AquariumClock;

