          opacity: ready ? 1 : 0,
          visibility: ready ? 'visible' : 'hidden',
          transition: 'opacity 0.3s ease',
        }}
      >
        <StaticBackground />
        <ClockFace angles={angles} />
      </div>
    </>
  );
}

