import React, { useRef, useEffect, useState } from 'react';
import { useMultiAssetLoader } from '@/utils/assetLoader';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import videoFile from '@/assets/images/2026/26-01/26-01-17/swww.mp4';
import fallbackImg from '@/assets/images/2026/26-01/26-01-17/sw.webp';
import overlayImage from '@/assets/images/2026/26-01/26-01-17/sw22.webp'; // Add your overlay image path here
import font112425sput from '@/assets/fonts/2026/26-01-17-sw.ttf?url';

export default function Clock() {
  const videoRef = useRef(null);
  const [videoFailed, setVideoFailed] = useState<boolean>(false);
  const [time, setTime] = useState(new Date());
  const [fontLoaded, setFontLoaded] = useState<boolean>(false);
  const [contentReady, setContentReady] = useState<boolean>(false);
  const [mediaReady, setMediaReady] = useState<boolean>(false);

  // 1. Load custom font
  useEffect(() => {
    const font = new FontFace('CustomClock-112425', `url(${font112425sput})`, {
      display: 'block',
    });

    let active = true;

    font
      .load()
      .then((loaded) => {
        if (active) {
          document.fonts.add(loaded);
          setFontLoaded(true);
          setContentReady(true);
        }
      })
      .catch(() => {
        if (active) {
          setFontLoaded(true);
          setContentReady(true);
        }
      });

    return () => {
      active = false;
    };
  }, []);

  // 2. Ultra-smooth clock loop
  useEffect(() => {
    const interval = setInterval(() => {
      setTime(new Date());
    }, 100); // Update every 100ms for smooth time display
    return () => clearInterval(interval);
  }, []);

  // 3. Video error handling & readiness
  useEffect(() => {
    const v = videoRef.current;
    if (!v) return;

    const fail = () => setVideoFailed(true);
    const canplay = () => setMediaReady(true);

    const playPromise = v.play();
    if (playPromise !== undefined) {
      playPromise.catch(fail);
    }

    v.addEventListener('error', fail);
    v.addEventListener('canplaythrough', canplay);
    v.addEventListener('loadeddata', canplay);
    return () => v.removeEventListener('error', fail);
  }, []);

  // Fallback image readiness in case video fails
  useEffect(() => {
    const img = new Image();
    const done = () => setMediaReady(true);
    img.onload = done;
    img.onerror = done;
    img.src = fallbackImg;
    const timeout = setTimeout(done, 1500);
    return () => clearTimeout(timeout);
  }, []);

  // Math for hands
  const ms = time.getMilliseconds();
  const seconds = (time.getSeconds() + ms / 1000) * 6;
  const minutes = time.getMinutes() * 6 + time.getSeconds() * 0.1;
  const hours = ((time.getHours() % 12) + time.getMinutes() / 60) * 30;

  return (
    <main
      aria-label={`Current time is ${time.toLocaleTimeString()}`}
      style={{
        position: 'fixed',
        inset: 0,
        width: '100vw',
        height: '100dvh',
        background: '#000',
        overflow: 'hidden',
      }}
    >
      {/* Loading state - prevents flash of unstyled content */}
      {!(contentReady && mediaReady) && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            background: '#000',
            zIndex: 100,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        />
      )}

      {/* BACKGROUND VIDEO layer */}
      {!videoFailed && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            width: '100vw',
            height: '100vh',
            zIndex: 1,
            overflow: 'hidden',
          }}
        >
          <video
            ref={videoRef}
            autoPlay
            muted
            loop
            playsInline
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              filter:
                'saturate(2.5) brightness(0.9) contrast(0.9) hue-rotate(185deg)',
            }}
            preload="auto"
          >
            <source
              src={
                process.env.NODE_ENV === 'production'
                  ? `${process.env.PUBLIC_URL || ''}${videoFile}`
                  : videoFile
              }
              type="video/mp4"
            />
          </video>
        </div>
      )}

      {/* FALLBACK IMAGE layer */}
      {videoFailed && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            width: '100vw',
            height: '100vh',
            overflow: 'hidden',
            zIndex: 1,
          }}
        >
          <img
            decoding="async"
            loading="lazy"
            src={fallbackImg}
            alt=""
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              filter: 'saturate(2.5)',
            }}
          />
        </div>
      )}

      {/* OVERLAY IMAGE layer */}
      <div
        style={{
          position: 'absolute',
          inset: 0,
          pointerEvents: 'none',
          zIndex: 8,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        <img
          decoding="async"
          loading="lazy"
          src={overlayImage}
          alt=""
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            opacity: 0.6,
            zIndex: 9,
            mixBlendMode: 'overlay',
            filter: 'hue-rotate(40deg)',
          }}
        />
      </div>

      {/* GRADIENT OVERLAY layer */}
      <div
        style={{
          position: 'absolute',
          inset: 0,
          pointerEvents: 'none',
          background:
            'radial-gradient(circle, rgba(183, 127, 7, 0.52) 60%, rgba(236, 99, 26, 0.56) 100%)',
          zIndex: 10, // Keep this above the overlay image
        }}
      />

      {/* CLOCK FACE layer */}
      {contentReady && mediaReady && (
        <div
          style={{
            position: 'absolute',
            inset: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            pointerEvents: 'none',
            zIndex: 10,
          }}
        >
          <div
            style={{
              position: 'relative',
              width: '92vmin',
              height: '92vmin',
              fontFamily: "'CustomClock-112425', sans-serif",
            }}
          >
            {/* Numbers */}
            {[...Array(12)].map((_, i) => {
              const n = i + 1;
              const angle = n * 30 - 90;
              const radius = 42;
              const x = 50 + radius * Math.cos((angle * Math.PI) / 180);
              const y = 50 + radius * Math.sin((angle * Math.PI) / 180);
              return (
                <div
                  key={n}
                  style={{
                    position: 'absolute',
                    left: `${x}%`,
                    top: `${y}%`,
                    fontSize: '5vh',
                    color: '#E9BB7A',
                    fontStyle: 'italic',
                    fontVariationSettings: "'slnt' -15, 'ital' 1",
                    transform: 'translate(-50%, -50%) skewX(-10deg)',
                    userSelect: 'none',
                    opacity: 0.5,
                    zIndex: 1,
                    textShadow:
                      '1px 1px 0px rgba(50, 21, 3, 0.99), -1px -1px 0 rgba(0, 0, 0, 0.3)',
                  }}
                >
                  {n}
                </div>
              );
            })}

            {/* Hour hand */}
            <div
              style={{
                position: 'absolute',
                bottom: '50%',
                left: '50%',
                width: '2.2vmin',
                height: '22vmin',
                borderRadius: '1.5vmin',
                backgroundColor: '#DD4108',
                transformOrigin: 'center bottom',
                transform: `translateX(-50%) rotate(${hours}deg)`,
                zIndex: 2,
                opacity: 0.4,
              }}
            />

            {/* Minute hand */}
            <div
              style={{
                position: 'absolute',
                bottom: '50%',
                left: '50%',
                width: '1.4vmin',
                height: '34vmin',
                backgroundColor: '#DF3A03',
                borderRadius: '1vmin',
                transformOrigin: 'center bottom',
                transform: `translateX(-50%) rotate(${minutes}deg)`,
                zIndex: 3,
                opacity: 0.4,
              }}
            />
          </div>
        </div>
      )}
    </main>
  );
}

import React, { useEffect, useRef } from 'react';

class IsoEngine {
  constructor(canvas) {
    this.ctx = canvas.getContext('2d');
    this.canvas = canvas;
    this.scale = 20;
    this.angle = Math.PI / 6;
  }

  project(x, y, z) {
    const cosA = Math.cos(this.angle);
    const sinA = Math.sin(this.angle);
    const originX = this.canvas.width / 2;
    const originY = this.canvas.height / 2;

    const px =
      originX +
      x * this.scale * cosA +
      y * this.scale * Math.cos(Math.PI - this.angle);
    const py =
      originY -
      x * this.scale * sinA -
      y * this.scale * Math.sin(Math.PI - this.angle) -
      z * this.scale;
    return { x: px, y: py };
  }

  drawPrism(x, y, z, w, l, h, color) {
    const points = [
      [x, y, z],
      [x + w, y, z],
      [x + w, y + l, z],
      [x, y + l, z],
      [x, y, z + h],
      [x + w, y, z + h],
      [x + w, y + l, z + h],
      [x, y + l, z + h],
    ];
    const faces = [
      [0, 1, 5, 4],
      [1, 2, 6, 5],
      [4, 5, 6, 7],
    ];
    const shades = [0.8, 0.6, 1.0];

    faces.forEach((indices, i) => {
      this.ctx.beginPath();
      const p0 = this.project(...points[indices[0]]);
      this.ctx.moveTo(p0.x, p0.y);
      indices.slice(1).forEach((idx) => {
        const p = this.project(...points[idx]);
        this.ctx.lineTo(p.x, p.y);
      });
      this.ctx.closePath();
      this.ctx.fillStyle = `rgb(${color.r * shades[i]}, ${color.g * shades[i]}, ${color.b * shades[i]})`;
      this.ctx.fill();
    });
  }

  clear() {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
  }
}

const GLYPH_MAP = {
  0: [
    [0, 0, 0, 3, 1, 1],
    [0, 0, 4, 3, 1, 1],
    [0, 0, 1, 1, 1, 3],
    [2, 0, 1, 1, 1, 3],
  ],
  1: [[1, 0, 0, 1, 1, 5]],
  2: [
    [0, 0, 0, 3, 1, 1],
    [0, 0, 2, 3, 1, 1],
    [0, 0, 4, 3, 1, 1],
    [2, 0, 3, 1, 1, 1],
    [0, 0, 1, 1, 1, 1],
  ],
  3: [
    [0, 0, 0, 3, 1, 1],
    [0, 0, 2, 3, 1, 1],
    [0, 0, 4, 3, 1, 1],
    [2, 0, 1, 1, 1, 3],
  ],
  4: [
    [2, 0, 0, 1, 1, 5],
    [0, 0, 2, 1, 1, 3],
    [1, 0, 2, 1, 1, 1],
  ],
  5: [
    [0, 0, 0, 3, 1, 1],
    [0, 0, 2, 3, 1, 1],
    [0, 0, 4, 3, 1, 1],
    [0, 0, 3, 1, 1, 1],
    [2, 0, 1, 1, 1, 1],
  ],
  6: [
    [0, 0, 0, 3, 1, 1],
    [0, 0, 2, 3, 1, 1],
    [0, 0, 4, 3, 1, 1],
    [0, 0, 1, 1, 1, 3],
    [2, 0, 1, 1, 1, 1],
  ],
  7: [
    [2, 0, 0, 1, 1, 5],
    [0, 0, 4, 3, 1, 1],
  ],
  8: [
    [0, 0, 0, 3, 1, 1],
    [0, 0, 2, 3, 1, 1],
    [0, 0, 4, 3, 1, 1],
    [0, 0, 1, 1, 1, 3],
    [2, 0, 1, 1, 1, 3],
  ],
  9: [
    [0, 0, 0, 3, 1, 1],
    [0, 0, 2, 3, 1, 1],
    [0, 0, 4, 3, 1, 1],
    [0, 0, 3, 1, 1, 1],
    [2, 0, 1, 1, 1, 3],
  ],
  A: [
    [0, 0, 0, 1, 1, 4],
    [2, 0, 0, 1, 1, 4],
    [0, 0, 4, 3, 1, 1],
    [0, 0, 2, 3, 1, 1],
  ],
  P: [
    [0, 0, 0, 1, 1, 5],
    [1, 0, 4, 2, 1, 1],
    [1, 0, 2, 2, 1, 1],
    [2, 0, 3, 1, 1, 1],
  ],
  M: [
    [0, 0, 0, 1, 1, 5],
    [4, 0, 0, 1, 1, 5],
    [1, 0, 3, 1, 1, 1],
    [2, 0, 2, 1, 1, 1],
    [3, 0, 3, 1, 1, 1],
  ],
};

const OrtogonalClock: React.FC = () => {
  const canvasRef = useRef(null);
  const clockColor = { r: 255, g: 140, b: 0 };

  useEffect(() => {
    const canvas = canvasRef.current;
    const engine = new IsoEngine(canvas);
    let raf;

    const tick = (time) => {
      const width = window.innerWidth;

      // Responsive Scales
      if (width < 480) {
        engine.scale = width / 38;
      } else if (width < 1024) {
        engine.scale = 35;
      } else {
        engine.scale = 50;
      }

      engine.angle = time / 3000;
      engine.clear();

      const now = new Date();
      let hours = now.getHours();
      const ampm = hours >= 12 ? 'PM' : 'AM';
      hours = hours % 12 || 12;

      const hStr = String(hours).padStart(2, '0');
      const mStr = String(now.getMinutes()).padStart(2, '0');
      const sStr = String(now.getSeconds()).padStart(2, '0');
      const fullStr = `${hStr}:${mStr}:${sStr} ${ampm}`;

      let totalWidth = 0;
      for (let char of fullStr) {
        if (char === ':') totalWidth += 2;
        else if (char === ' ') totalWidth += 1.5;
        else if (char === 'M') totalWidth += 6;
        else totalWidth += 4;
      }

      let currentX = -(totalWidth / 2);

      for (let i = 0; i < fullStr.length; i++) {
        const char = fullStr[i];
        if (char === ':') {
          engine.drawPrism(currentX, 0, 1, 1, 1, 1, clockColor);
          engine.drawPrism(currentX, 0, 3, 1, 1, 1, clockColor);
          currentX += 2;
        } else if (char === ' ') {
          currentX += 1.5;
        } else {
          const shapes = GLYPH_MAP[char];
          if (shapes) {
            shapes.forEach((f) =>
              engine.drawPrism(
                f[0] + currentX,
                f[1],
                f[2],
                f[3],
                f[4],
                f[5],
                clockColor,
              ),
            );
          }
          currentX += char === 'M' ? 6 : 4;
        }
      }
      raf = requestAnimationFrame(tick);
    };

    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, []);

  return (
    <div
      style={{
        width: '100vw',
        height: '100dvh',
        background: 'linear-gradient(180deg, #185591 0%, #835CD7 100%)',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        overflow: 'hidden',
      }}
    >
      <canvas
        ref={canvasRef}
        width={window.innerWidth * 2}
        height={window.innerHeight * 2}
        style={{ width: '100%', height: '100%', objectFit: 'contain' }}
      />
    </div>
  );
};

export default OrtogonalClock;

