import React from 'react';
import { useClockTime } from '@/utils/hooks/useClockTime';
import { useSuspenseFontLoader } from '@/utils/fontLoader';

// Asset imports
import backgroundUrl from '@/assets/images/2026/26-01/26-01-22/1974.jpg';
import digitTextureUrl from '@/assets/images/2026/26-01/26-01-22/liq.webp';
import fontUrl from '@/assets/fonts/2026/26-01-22-1974.ttf';

const FONT_FAMILY = '1974';

const DynamicClock: React.FC = () => {
  // BTS Standard: FOUC Prevention via Suspense
  useSuspenseFontLoader([{ fontFamily: FONT_FAMILY, fontUrl }]);

  // BTS Standard: Frame-perfect time synchronization
  const time = useClockTime('seconds');
  const dateTime = time.toISOString();

  const timeString = [time.getHours(), time.getMinutes(), time.getSeconds()]
    .map((n) => n.toString().padStart(2, '0'))
    .join('');

  // ────────────────────────────────────────────────
  // Styles
  // ────────────────────────────────────────────────

  const containerStyle = {
    width: '100vw',
    height: '100dvh',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    backgroundImage: `url(${backgroundUrl})`,
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    filter: 'contrast(0.7) brightness(1.15)',
    fontFamily: `'${FONT_FAMILY}', sans-serif`,
  };

  const digitsRowStyle = {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    gap: 'clamp(1.0vw, 2vw, 4vw)', // space between boxes
    padding: '0 2vw',
    width: '100%',
    maxWidth: '99vw',
    marginTop: '-65vh',
  };

  const digitBoxStyle = {
    width: 'clamp(22vw, 22vw, 222px)', // fixed width — biggest factor in preventing jump
    height: 'clamp(29vw, 29vw, 340px)', // fixed height
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    overflow: 'hidden', // keeps content insideoptional depth
  };

  const digitStyle = {
    fontSize: 'clamp(20vw, 26vw, 260px)', // large enough to mostly fill the box
    // fontWeight: 'bold',
    lineHeight: '1',
    backgroundImage: `url(${digitTextureUrl})`,
    backgroundSize: '180% 180%',
    backgroundPosition: 'center',
    backgroundClip: 'text',
    WebkitBackgroundClip: 'text',
    color: 'transparent',
    WebkitTextFillColor: 'transparent',
    filter: 'contrast(2.2) brightness(1.1)',
    // WebkitTextStroke: '1.5px rgba(255, 255, 255, 0.5)',
    userSelect: 'none',
    textAlign: 'center',
  };

  return (
    <main style={containerStyle}>
      <div style={digitsRowStyle}>
        <time dateTime={dateTime} style={{ display: 'flex', gap: 'inherit' }}>
          {timeString.split('').map((char, i) => (
            <div key={i} style={digitBoxStyle}>
              <div style={digitStyle}>{char}</div>
            </div>
          ))}
        </time>
      </div>
    </main>
  );
};

export default DynamicClock;

import React, { useState, useEffect, CSSProperties } from 'react';

// Asset imports
import clockDigitImage from '@/assets/images/2026/26-01/26-01-23/eye.gif';
import clockBackground from '@/assets/images/2026/26-01/26-01-23/eye.webp';
import styles from './Clock.module.css';

interface CustomStyle extends CSSProperties {
  '--rotation'?: string;
}

const Clock: React.FC = () => {
  const [time, setTime] = useState(new Date());
  const [bgReady, setBgReady] = useState<boolean>(false);

  useEffect(() => {
    let animationFrameId: number;

    const tick = () => {
      setTime(new Date());
      animationFrameId = requestAnimationFrame(tick);
    };

    animationFrameId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(animationFrameId);
  }, []);

  // Preload background and digit asset to avoid flash
  useEffect(() => {
    let isMounted = true;
    const imgs = [clockDigitImage, clockBackground];

    const loadPromises = imgs.map((src) => {
      return new Promise((resolve) => {
        const img = new Image();
        img.onload = resolve;
        img.onerror = resolve;
        img.src = src;
      });
    });

    Promise.all(loadPromises).then(() => {
      if (isMounted) setBgReady(true);
    });

    // Fallback timeout
    const timeout = setTimeout(() => {
      if (isMounted) setBgReady(true);
    }, 1200);

    return () => {
      isMounted = false;
      clearTimeout(timeout);
    };
  }, []);

  // Calculate time values including milliseconds for smooth movement
  const ms = time.getMilliseconds();
  const seconds = time.getSeconds() + ms / 1000;
  const minutes = time.getMinutes() + seconds / 60;
  const hours = time.getHours() + minutes / 60;

  // Rotations
  const secDeg = (seconds / 60) * 360;
  const minDeg = (minutes / 60) * 360;
  const hourDeg = ((hours % 12) / 12) * 360;

  // Background rotation: Counter-clockwise (-), once per 60 seconds
  const bgRotation = -(seconds / 60) * 360;

  return (
    <div
      className={styles.container}
      style={{
        opacity: bgReady ? 1 : 0,
        visibility: bgReady ? 'visible' : 'hidden',
      }}
    >
      <div className={styles.clockFace}>
        {/* Rotating Background Layer */}
        <div
          className={styles.bgLayer}
          style={
            {
              backgroundImage: `url(${clockBackground})`,
              '--rotation': `${bgRotation}deg`,
            } as CustomStyle
          }
        />

        {/* Static Digits Layer */}
        {[...Array(12)].map((_, i) => {
          const rotation = (i + 1) * 30;
          return (
            <div
              key={i}
              className={styles.digitContainer}
              style={{ '--rotation': `${rotation}deg` } as CustomStyle}
            >
              <img
                decoding="async"
                loading="lazy"
                src={clockDigitImage}
                alt={`digit-${i + 1}`}
                className={styles.digitImage}
              />
            </div>
          );
        })}

        {/* Hands */}
        <div
          className={`${styles.hand} ${styles.handHour}`}
          style={{ '--rotation': `${hourDeg}deg` } as CustomStyle}
        />
        <div
          className={`${styles.hand} ${styles.handMinute}`}
          style={{ '--rotation': `${minDeg}deg` } as CustomStyle}
        />
        <div
          className={`${styles.hand} ${styles.handSecond}`}
          style={{ '--rotation': `${secDeg}deg` } as CustomStyle}
        />

        {/* Center Pivot */}
        <div className={styles.centerDot} />
      </div>
    </div>
  );
};

export default Clock;

