import React, { useEffect, useState, useMemo } from 'react';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import { useSecondClock } from '@/utils/hooks';

import digitalFontUrl from '@/assets/fonts/2026/26-02-12-disco.otf';
import digitalBgImage from '@/assets/images/2026/26-02/26-02-12/lit.webp';
import extraBg1 from '@/assets/images/2026/26-02/26-02-12/light.webp';
import extraBg2 from '@/assets/images/2026/26-02/26-02-12/li.gif';
import extraBg3 from '@/assets/images/2026/26-02/26-02-12/ball.webp';

const DISCO_COLORS = [
  '#FF00FF', // Neon Magenta
  '#FFFB00', // Neon Yellow
  '#FF3131', // Neon Red
  '#39FF14', // Neon Green
  '#B473F1', // Blue Violet
  '#FF5E00', // Neon Orange
];

interface TimeDigits {
  digits: string[];
  rawSeconds: number;
}

const CONFIG = {
  use24Hour: false,
  showSeconds: true,
};

const DigitalClockTemplate: React.FC = () => {
  const time = useSecondClock();

  const fontConfigs = useMemo(() => [{
      fontFamily: 'BorrowedDigital',
      fontUrl: digitalFontUrl,
      options: {
        weight: 'normal',
        style: 'normal'
      }
  }], []);

  useSuspenseFontLoader(fontConfigs);

  const { digits, rawSeconds }: TimeDigits = useMemo(() => {
    const hours24 = time.getHours();
    const hours = CONFIG.use24Hour ? hours24 : hours24 % 12 || 12;
    const pad = (n: number): string => String(n).padStart(2, '0');

    const hh = pad(hours);
    const mm = pad(time.getMinutes());
    const ss = pad(time.getSeconds());

    return {
      digits: (hh + mm + (CONFIG.showSeconds ? ss : '')).split(''),
      rawSeconds: time.getSeconds(),
    };
  }, [time]);


  const getDiscoColor = (index: number): string => {
    const colorIndex = (rawSeconds + index) % DISCO_COLORS.length;
    return DISCO_COLORS[colorIndex] || DISCO_COLORS[0];
  };

  const layerBase = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    pointerEvents: 'none',
  };

  return (
      <div
        style={{
          position: 'relative',
          width: '100vw',
          height: '100dvh',
          overflow: 'hidden',
          backgroundColor: '#000',
        }}
      >
        <div
          style={{
            ...layerBase,
            backgroundImage: `url(${digitalBgImage})`,
            opacity: 1.0,
            filter: 'saturate(3.8) brightness(1.5)',
            zIndex: 1,
          }}
        />
      <div
        style={{
          ...layerBase,
          backgroundImage: `url(${extraBg1})`,
          opacity: 0.6,
          filter: 'saturate(3.8) contrast(1.5) brightness(1.5)',
          mixBlendMode: 'overlay',
          zIndex: 2,
        }}
      />
      <div
        style={{
          ...layerBase,
          backgroundImage: `url(${extraBg2})`,
          opacity: 0.3,
          filter: 'saturate(3.8) contrast(1.5) brightness(1.5)',
          zIndex: 3,
        }}
      />
      <div
        style={{
          ...layerBase,
          backgroundImage: `url(${extraBg3})`,
          opacity: 0.3,
          filter: 'saturate(1.8) contrast(1.5) brightness(2.5)',
          zIndex: 4,
        }}
      />

      <div
        style={{
          position: 'relative',
          zIndex: 10,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100%',
          fontFamily: "'BorrowedDigital', sans-serif"
        }}
      >
        <div style={clockWrapperStyle}>
          {digits.map((digit, i) => (
            <span
              key={i}
              style={{
                ...digitBoxStyle,
                color: getDiscoColor(i),
                // textShadow: `0 0 15px ${getDiscoColor(i)}`,
                // transition: 'color 0.1s ease', // Optional: makes the color swap feel punchier
              }}
            >
              {digit}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
};

const clockWrapperStyle = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  padding: '1.5rem',
};

const digitBoxStyle = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  width: '0.8em', // Tight width since there are no spacers
  height: '1.1em',
  fontSize: 'clamp(4rem, 16vw, 10rem)',
  textAlign: 'center',
};

export default DigitalClockTemplate;

import React, { useMemo } from 'react';
import { useSecondClock } from '@/utils/hooks';
import styles from './Clock.module.css';

const WordClock: React.FC = () => {
  const now = useSecondClock();

  const grid = [
    ['I', 'T', 'L', 'I', 'S', 'A', 'S', 'T', 'A', 'M', 'P'],
    ['A', 'C', 'Q', 'U', 'A', 'R', 'T', 'E', 'R', 'D', 'C'],
    ['T', 'W', 'E', 'N', 'T', 'Y', 'F', 'I', 'V', 'E', 'X'],
    ['H', 'A', 'L', 'F', 'S', 'T', 'E', 'N', 'F', 'T', 'O'],
    ['P', 'A', 'S', 'T', 'E', 'R', 'U', 'S', 'E', 'V', 'E', 'N'],
    ['O', 'N', 'E', 'T', 'W', 'O', 'T', 'H', 'R', 'E', 'E'],
    ['F', 'O', 'U', 'R', 'F', 'I', 'V', 'E', 'S', 'I', 'X'],
    ['N', 'I', 'N', 'E', 'K', 'T', 'W', 'E', 'L', 'V', 'E'],
    ['E', 'I', 'G', 'H', 'T', 'E', 'L', 'E', 'V', 'E', 'N'],
    ['T', 'E', 'N', 'O', 'C', 'L', 'O', 'C', 'K', 'S', 'X'],
  ];

  const mapping: Record<string, number[][]> = {
    it: [[0, 0], [0, 1]],
    is: [[0, 3], [0, 4]],
    quarter: [[1, 2], [1, 3], [1, 4], [1, 5], [1, 6], [1, 7], [1, 8]],
    twenty: [[2, 0], [2, 1], [2, 2], [2, 3], [2, 4], [2, 5]], // Fixed T-W-E-N-T-Y
    five_m: [[2, 6], [2, 7], [2, 8], [2, 9]], // Five (minutes)
    half: [[3, 0], [3, 1], [3, 2], [3, 3]],
    ten_m: [[3, 5], [3, 6], [3, 7]], // Ten (minutes)
    past: [[4, 0], [4, 1], [4, 2], [4, 3]],
    to: [[4, 9], [4, 10]],
    one: [[5, 0], [5, 1], [5, 2]],
    two: [[5, 3], [5, 4], [5, 5]],
    three: [[5, 6], [5, 7], [5, 8], [5, 9], [5, 10]],
    four: [[6, 0], [6, 1], [6, 2], [6, 3]],
    five: [[6, 4], [6, 5], [6, 6], [6, 7]],
    six: [[6, 8], [6, 9], [6, 10]],
    seven: [[4, 5], [4, 6], [4, 7], [4, 8], [4, 9]], // S-E-V-E-N row 4
    eight: [[8, 0], [8, 1], [8, 2], [8, 3], [8, 4]],
    nine: [[7, 0], [7, 1], [7, 2], [7, 3]],
    ten: [[9, 0], [9, 1], [9, 2]], // T-E-N (hour) row 9
    eleven: [[8, 5], [8, 6], [8, 7], [8, 8], [8, 9], [8, 10]],
    twelve: [[7, 5], [7, 6], [7, 7], [7, 8], [7, 9], [7, 10]],
    oclock: [[9, 3], [9, 4], [9, 5], [9, 6], [9, 7], [9, 8], [9, 9]],
  };

  const hourWords = ["twelve", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven"];

  const activeIndices = useMemo(() => {
    const h = now.getHours();
    const m = now.getMinutes();
    const active = new Set<string>();

    const lightUp = (key: string) => {
      mapping[key]?.forEach(([r, c]) => active.add(`${r}-${c}`));
    };

    lightUp('it');
    lightUp('is');

    // Determine which hour to highlight
    let hourIdx = h % 12;
    if (m >= 35) hourIdx = (h + 1) % 12;

    lightUp(hourWords[hourIdx]);

    // Minute Logic
    if (m >= 5 && m < 10) { lightUp('five_m'); lightUp('past'); }
    else if (m >= 10 && m < 15) { lightUp('ten_m'); lightUp('past'); }
    else if (m >= 15 && m < 20) { lightUp('quarter'); lightUp('past'); }
    else if (m >= 20 && m < 25) { lightUp('twenty'); lightUp('past'); }
    else if (m >= 25 && m < 30) { lightUp('twenty'); lightUp('five_m'); lightUp('past'); }
    else if (m >= 30 && m < 35) { lightUp('half'); lightUp('past'); }
    else if (m >= 35 && m < 40) { lightUp('twenty'); lightUp('five_m'); lightUp('to'); }
    else if (m >= 40 && m < 45) { lightUp('twenty'); lightUp('to'); }
    else if (m >= 45 && m < 50) { lightUp('quarter'); lightUp('to'); }
    else if (m >= 50 && m < 55) { lightUp('ten_m'); lightUp('to'); }
    else if (m >= 55) { lightUp('five_m'); lightUp('to'); }
    else { lightUp('oclock'); }

    return active;
  }, [now]);

  return (
    <div className={styles.wrapper}>
      <div className={styles.container}>
        {grid.map((row, rIdx) => (
          <div key={rIdx} className={styles.row}>
            {row.map((char, cIdx) => (
              <span
                key={`${rIdx}-${cIdx}`}
                className={`${styles.char} ${activeIndices.has(`${rIdx}-${cIdx}`) ? styles.active : ''}`}
              >
                {char}
              </span>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
};

export default WordClock;

