  const fontConfigs = [
    {
      fontFamily: 'OverFont',
      fontUrl: overFont,
    }
  ];
  const fontsLoaded = useMultipleFontLoader(fontConfigs);

  const fontFamily = fontsLoaded ? 'OverFont, Courier New, monospace' : 'Courier New, monospace';

  const timeDigits = useMemo(() => {
