import React, { useMemo, useRef, useState, useCallback, useEffect } from 'react';

import pleiadesFont from '@/assets/fonts/2026/26-04-30-pleides.otf';
import { useClockTime } from '@/utils/clockUtils';
import { useSuspenseFontLoader } from '@/utils/fontLoader';
import type { FontConfig } from '@/types/clock';

import styles from './Clock.module.css';

// --- Types & Constants ---

type AnimType = 'twinkle' | 'pulse' | 'flicker';
type ColorType = 'white' | 'blue' | 'gold';

interface StarPair {
  id: number;
  startX: string;
  startY: string;
  angle: number;
  duration: number;
  length: number;
  distance: number;
  key: number;
}

const STAR_COUNT = 150;
const formatTime = (num: number): string => num.toString().padStart(2, '0');

const positions = [
  { top: '35%', left: '44%' },    // 0: Hour tens - Atlas (upper left of cluster)
  { top: '32%', left: '52%' },    // 1: Hour ones - Pleione (upper right, near Atlas)
  { top: '50%', left: '50%' },    // 2: Minute ones - Alcyone (center, brightest)
  { top: '45%', left: '58%' },    // 3: Minute tens - Merope (right of center)
  { top: '65%', left: '46%' },    // 4: A/P indicator - Electra (lower left)
  { top: '62%', left: '54%' },    // 5: M indicator - Maia (lower right)
] as const;

// --- Helper Functions ---

const generateRandomPair = (id: number, key: number): StarPair => ({
  id,
  startX: `${Math.random() * 100}%`,
  startY: `${Math.random() * 100}%`,
  angle: Math.random() * 360,
  duration: Math.random() * 0.8 + 0.4,
  length: Math.random() * 150 + 50,
  distance: Math.random() * 60 + 20,
  key,
});

// Pleiades cluster positions (7 sisters + Atlas/Pleione parents)
const PLEIADES_STARS = [
  { top: 35, left: 44, brightness: 0.9 }, // Atlas
  { top: 32, left: 52, brightness: 0.8 }, // Pleione
  { top: 50, left: 50, brightness: 1.0 }, // Alcyone (brightest)
  { top: 45, left: 58, brightness: 0.7 }, // Merope
  { top: 58, left: 42, brightness: 0.6 }, // Electra
  { top: 62, left: 56, brightness: 0.6 }, // Maia
  { top: 55, left: 48, brightness: 0.5 }, // Taygeta
  { top: 48, left: 40, brightness: 0.4 }, // Celeano
  { top: 40, left: 62, brightness: 0.4 }, // Sterope
];

const STARS = Array.from({ length: STAR_COUNT }, (_, i) => {
  const rand = Math.random;
  const animRoll = rand();
  const colorRoll = rand();

  // 70% of stars clustered around Pleiades positions, 30% scattered
  const useCluster = rand() < 0.7;
  let top, left;

  if (useCluster) {
    const clusterIndex = Math.floor(rand() * PLEIADES_STARS.length);
    const cluster = PLEIADES_STARS[clusterIndex]!;
    const spread = 6; // degrees of spread around cluster center
    top = cluster.top + (rand() * spread * 2 - spread);
    left = cluster.left + (rand() * spread * 2 - spread);
  } else {
    top = rand() * 100;
    left = rand() * 100;
  }

  return {
    id: i,
    top: `${top}%`,
    left: `${left}%`,
    size: rand() * 2.5 + 0.5,
    opacity: rand() * 0.5 + 0.4,
    delay: rand() * 5,
    duration: rand() * 3 + 2,
    animType: animRoll > 0.8 ? 'pulse' : animRoll > 0.6 ? 'flicker' : 'twinkle' as AnimType,
    colorType: colorRoll > 0.9 ? 'blue' : colorRoll > 0.8 ? 'gold' : 'white' as ColorType,
  };
});

const fontConfigs: FontConfig[] = [{ fontFamily: 'Pleiades', fontUrl: pleiadesFont }];

// --- Component ---

const PleiadesClock: React.FC = () => {
  useSuspenseFontLoader(fontConfigs);
  const time = useClockTime();
  const [starPairs, setStarPairs] = useState<StarPair[]>(() =>
    Array.from({ length: 24 }, (_, i) => generateRandomPair(i, 0))
  );
  const timeoutsRef = useRef<Set<ReturnType<typeof setTimeout>>>(new Set());

  const regeneratePair = useCallback((id: number) => {
    const delay = Math.random() * 6000 + 2000;
    const timeout = setTimeout(() => {
      setStarPairs(prev => prev.map(p => (p.id === id ? generateRandomPair(id, p.key + 1) : p)));
    }, delay);
    timeoutsRef.current.add(timeout);
  }, []);

  useEffect(() => {
    const timeouts = timeoutsRef.current;
    return () => {
      timeouts.forEach(clearTimeout);
      timeouts.clear();
    };
  }, []);

  const { hourTens, hourOnes, minuteTens, minuteOnes, isAM, isoTime } = useMemo(() => {
    let h = time.getHours();
    const isAM = h < 12;
    h = h % 12 || 12;
    const hStr = formatTime(h);
    const mStr = formatTime(time.getMinutes());
    const isoString = time.toISOString();
    return { hourTens: hStr[0], hourOnes: hStr[1], minuteTens: mStr[0], minuteOnes: mStr[1], isAM, isoTime: isoString };
  }, [time]);

  const getStarClass = (animType: AnimType): string => {
    switch (animType) {
      case 'twinkle': return styles.starTwinkle ?? '';
      case 'pulse': return styles.starPulse ?? '';
      case 'flicker': return styles.starFlicker ?? '';
      default: return styles.starTwinkle ?? '';
    }
  };

  const getStarColor = (colorType: ColorType): string => {
    if (colorType === 'blue') return '#a8d0ff';
    if (colorType === 'gold') return '#ffd700';
    return '#fff';
  };

  const getStarBoxShadowColor = (colorType: ColorType): string => {
    if (colorType === 'white') return '#fff';
    return 'currentColor';
  };

  return (
    <div className={styles.container}>
      {/* Static Starfield */}
      {STARS.map((star) => (
        <span
          key={star.id}
          className={getStarClass(star.animType)}
          style={{
            top: star.top,
            left: star.left,
            width: star.size,
            height: star.size,
            backgroundColor: getStarColor(star.colorType),
            opacity: star.opacity,
            animationDuration: `${star.duration}s`,
            animationDelay: `${star.delay}s`,
            boxShadow: `0 0 ${star.size * 2}px ${getStarBoxShadowColor(star.colorType)}`,
          }}
        />
      ))}

      {/* Shooting Stars */}
      {starPairs.map((star) => (
        <span
          key={`${star.id}-${star.key}`}
          className={styles.shootingStar}
          style={{
            top: star.startY,
            left: star.startX,
            width: star.length,
            transform: `rotate(${star.angle}deg)`,
            animation: `shoot-${star.id}-${star.key} ${star.duration}s ease-out forwards`,
          }}
          onAnimationEnd={() => regeneratePair(star.id)}
        />
      ))}

      {/* Digits and Indicators */}
      <time dateTime={isoTime} className={styles.timeWrapper}>
        <span className={`${styles.digit} ${styles.digitStandard}`} style={{ top: positions[0].top, left: positions[0].left }}>{hourTens}</span>
        <span className={`${styles.digit} ${styles.digitStandard}`} style={{ top: positions[1].top, left: positions[1].left }}>{hourOnes}</span>
        <span className={`${styles.digit} ${styles.digitStandard}`} style={{ top: positions[3].top, left: positions[3].left }}>{minuteTens}</span>
        <span className={`${styles.digit} ${styles.digitCenter} ${styles.digitBright}`} style={{ top: positions[2].top, left: positions[2].left }}>{minuteOnes}</span>

        <span className={`${styles.indicator} ${styles.indicatorActive} ${styles.indicatorTransition}`} style={{ top: positions[4].top, left: positions[4].left }}>{isAM ? 'A' : 'P'}</span>
        <span className={`${styles.indicator} ${styles.indicatorActive} ${styles.indicatorTransition}`} style={{ top: positions[5].top, left: positions[5].left }}>M</span>
      </time>

      <style>{`
        ${starPairs.map(s => `
          @keyframes shoot-${s.id}-${s.key} {
            0% { transform: rotate(${s.angle}deg) translateX(0); opacity: 0; }
            10% { opacity: 1; }
            30% { transform: rotate(${s.angle}deg) translateX(${s.distance}vw); opacity: 0; }
            100% { transform: rotate(${s.angle}deg) translateX(${s.distance}vw); opacity: 0; }
          }
        `).join('')}
      `}</style>
    </div>
  );
};

export default PleiadesClock;

import React, { useMemo, useRef, useEffect } from 'react';

import { useClockTime } from '@/utils/clockUtils';

import styles from './Clock.module.css';

interface HandProps {
  angle: number;
  length: number;
  width: number;
  color: string;
  type: 'hour' | 'minute' | 'second';
}

const getHandZIndex = (type: 'hour' | 'minute' | 'second'): number => {
  if (type === 'second') return 30;
  if (type === 'minute') return 20;
  return 10;
};

const getHandBorderRadius = (type: 'hour' | 'minute' | 'second', width: number): string => {
  if (type === 'second') return '1px';
  return `${width / 2}px`;
};

const getHandTransition = (type: 'hour' | 'minute' | 'second'): string => {
  if (type === 'second') return 'none';
  return 'transform 0.1s ease-out';
};

const ClockHand: React.FC<HandProps> = ({ angle, length, width, color, type }) => {
  const handStyle: React.CSSProperties = {
    position: 'absolute',
    bottom: '50%',
    left: '50%',
    width: `${width}px`,
    height: `${length}px`,
    backgroundColor: color,
    transformOrigin: 'bottom center',
    transform: `translateX(-50%) rotate(${angle}deg)`,
    borderRadius: getHandBorderRadius(type, width),
    zIndex: getHandZIndex(type),
    transition: getHandTransition(type),
  };

  return <div style={handStyle} className={styles.hand} data-hand-type={type} />;
};

const AnalogClock: React.FC = () => {
  const time = useClockTime();
  const rafRef = useRef<number | null>(null);
  const [, forceRender] = React.useReducer((x) => x + 1, 0);

  useEffect(() => {
    const animate = () => {
      forceRender();
      rafRef.current = requestAnimationFrame(animate);
    };
    rafRef.current = requestAnimationFrame(animate);

    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, []);

  const { hours, minutes, seconds, ms, isoTime } = useMemo(() => {
    const h = time.getHours();
    const m = time.getMinutes();
    const s = time.getSeconds();
    const msVal = time.getMilliseconds();
    return {
      hours: h,
      minutes: m,
      seconds: s,
      ms: msVal,
      isoTime: time.toISOString(),
    };
  }, [time]);

  const hourAngle = ((hours % 12) + minutes / 60) * 30;
  const minuteAngle = (minutes + seconds / 60) * 6;
  const secondAngle = (seconds + ms / 1000) * 6;

  const tickMarks = useMemo(() => {
    return Array.from({ length: 60 }, (_, i) => {
      const isHour = i % 5 === 0;
      const angle = i * 6;
      return {
        id: i,
        angle,
        isHour,
        length: isHour ? 16 : 8,
        width: isHour ? 4 : 2,
      };
    });
  }, []);

  const numbers = useMemo(() => {
    return Array.from({ length: 12 }, (_, i) => {
      const num = i === 0 ? 12 : i;
      const angle = i * 30;
      const radian = (angle - 90) * (Math.PI / 180);
      const radius = 35;
      const x = 50 + radius * Math.cos(radian);
      const y = 50 + radius * Math.sin(radian);
      return {
        num,
        x,
        y,
      };
    });
  }, []);

  return (
    <div className={styles.container}>
      <time dateTime={isoTime} className={styles.timeWrapper}>
        <div className={styles.clockFace}>
          {/* Outer ring */}
          <div className={styles.outerRing} />

          {/* Inner decorative ring */}
          <div className={styles.innerRing} />

          {/* Tick marks */}
          {tickMarks.map((tick) => (
            <div
              key={tick.id}
              className={tick.isHour ? styles.hourTick : styles.minuteTick}
              style={{
                transform: `rotate(${tick.angle}deg)`,
              }}
            />
          ))}

          {/* Numbers */}
          {numbers.map((n) => (
            <span
              key={n.num}
              className={styles.number}
              style={{
                left: `${n.x}%`,
                top: `${n.y}%`,
              }}
            >
              {n.num}
            </span>
          ))}

          {/* Clock hands */}
          <ClockHand
            type="hour"
            angle={hourAngle}
            length={60}
            width={6}
            color="#1a1a1a"
          />
          <ClockHand
            type="minute"
            angle={minuteAngle}
            length={85}
            width={4}
            color="#333"
          />
          <ClockHand
            type="second"
            angle={secondAngle}
            length={95}
            width={2}
            color="#d32f2f"
          />

          {/* Center dot */}
          <div className={styles.centerDot} />
          <div className={styles.centerDotInner} />
        </div>

        {/* Digital readout */}
        <div className={styles.digitalTime}>
          {String(hours).padStart(2, '0')}:
          {String(minutes).padStart(2, '0')}:
          {String(seconds).padStart(2, '0')}
        </div>
      </time>
    </div>
  );
};

